var e=[{id:`pronunciation`,slug:`pronunciation`,title:`Your Mouth Is Lying to You`,emoji:`👄`,tagline:`French Pronunciation`,funnyDescription:`The French "r" sounds like gentle gargling. The "u" has no English equivalent. Half the letters you see are silent. This unit exists so your first spoken word isn't a disaster.`,color:`#3B82F6`,accentColor:`#60a5fa`,lessons:[{id:`pronunciation-1`,title:`The Sounds That Will Haunt You`,subtitle:`French vowels, the dreaded R, and why "u" sounds like nothing in English.`,xpReward:20,vocab:[{french:`le r`,english:`The French R`,pronunciation:`ʁ`,funnyNote:`Imagine gargling water very gently at the back of your throat. That's the French "r". It sounds nothing like the English R. Practice in private first.`},{french:`tu / du / bu`,english:`The French "u" sound`,pronunciation:`y`,funnyNote:`Say "ee" with your lips in an O shape. This is one of the hardest sounds for English speakers. People will confuse "dessus" (above) and "dessous" (below) if you get it wrong.`},{french:`eu / feu / deux`,english:`The "eu" sound`,pronunciation:`ø`,funnyNote:`Like "u" but a bit more open. "Deux" (two) sounds very different from "du" — a crucial distinction when ordering bread.`},{french:`é / été / café`,english:`Closed "e" — sharp and bright`,pronunciation:`e`,funnyNote:`Pure, like the "ay" in "bay" but without the glide. This one is actually easy once you hear it.`},{french:`è / être / mère`,english:`Open "e" — softer and lower`,pronunciation:`ɛ`,funnyNote:`Like the "e" in "bed". The circumflex (ê) and grave accent (è) both signal this sound.`},{french:`on / bon / maison`,english:`The nasal "on"`,pronunciation:`ɔ̃`,funnyNote:`The classic French nasal. Air through the nose. "Bon" (good) is your first nasal victory.`}],exercises:[{type:`multiple-choice`,prompt:`The French "r" is produced where?`,answer:`Back of the throat (uvula)`,options:[`Tip of the tongue`,`Back of the throat (uvula)`,`Lips pressed together`,`Side of the mouth`]},{type:`multiple-choice`,prompt:`The accent on "é" (as in "café") signals which sound?`,answer:`Closed "e", like "ay"`,options:[`Silent letter`,`Closed "e", like "ay"`,`Nasal vowel`,`Open "e", like "bed"`]},{type:`translation`,prompt:`Spell out "Good" in French — the word with the nasal "on" sound.`,answer:`Bon`,hint:`The nasal bɔ̃ sound`}]},{id:`pronunciation-2`,title:`Silent Letters: A French Tradition`,subtitle:`Half the letters you see are decorative. Here's which ones.`,xpReward:20,vocab:[{french:`Paris / vous / ils`,english:`Silent final consonants`,pronunciation:`paʁi / vu / il`,funnyNote:`Most word-final consonants are silent in French. "Paris" = pah-ree, not pah-ris. "Vous" = voo. "Ils" = eel. The letters sit there looking decorative.`},{french:`hôtel / heure / homme`,english:`H is always silent`,pronunciation:`otɛl / œʁ / ɔm`,funnyNote:`French H is completely silent, always. So you must elide: l'hôtel, l'heure, l'homme. There's a so-called aspirate H (haricot, hibou) that still isn't pronounced — it just blocks elision.`},{french:`vingt / doigt / temps`,english:`Tricky silent endings`,pronunciation:`vɛ̃ / dwa / tɑ̃`,funnyNote:`"Vingt" (twenty) has a silent "gt". "Doigt" (finger) is just "dwa". "Temps" (time/weather) is "tɑ̃". French spelling is inherited from Latin; pronunciation moved on without it.`},{french:`beaucoup / trop / pas`,english:`Adverbs with silent finals`,pronunciation:`boku / tʁo / pa`,funnyNote:`"Beaucoup" = bo-koo. The P is silent. "Trop" = tro. Pronouncing the final P is the mark of a beginner. The French will wince.`}],exercises:[{type:`multiple-choice`,prompt:`How is "Paris" actually pronounced by French speakers?`,answer:`pah-ree`,options:[`pah-ris`,`pah-ree`,`pair-ee`,`pah-riz`]},{type:`multiple-choice`,prompt:`Which is true about the letter "h" in French?`,answer:`It is always silent`,options:[`It is always aspirated`,`It is always silent`,`It sounds like English H sometimes`,`It only appears in loan words`]},{type:`translation`,prompt:`How do you say "a lot" in French? (the P at the end is silent)`,answer:`beaucoup`,hint:`bo-koo`}]},{id:`pronunciation-3`,title:`Liaison & Elision: Words That Merge`,subtitle:`When silent consonants wake up, and vowels vanish. This is what makes French flow.`,xpReward:25,vocab:[{french:`les enfants`,english:`The children`,pronunciation:`le zɑ̃fɑ̃`,funnyNote:`The "s" of "les" comes alive before a vowel: "lez-onfants". This is liaison. It makes French flow like music — or like a river, depending on your progress.`},{french:`vous avez`,english:`You have`,pronunciation:`vu zave`,funnyNote:`"Vous-avez" becomes "voo-zahvay". The Z-liaison is the most common. It happens with: nous, ils, elles, les, des, mes, tes, ses, ces.`},{french:`un ami`,english:`A friend`,pronunciation:`œ̃ nami`,funnyNote:`"Un ami" = "uhn-nami". The N sound carries over. Liaison is mandatory after articles (un, les, des) and pronouns (nous, vous, ils, elles).`},{french:`la/le → l'`,english:`Elision — the vowel drops`,pronunciation:``,funnyNote:`Before a vowel, "le" and "la" become "l'". Le ami → l'ami. La école → l'école. The same happens with: je→j', me→m', te→t', se→s', de→d', ne→n', que→qu'.`},{french:`du / au / des / aux`,english:`Contracted articles`,pronunciation:`dy / o / de / o`,funnyNote:`"de + le" → "du". "à + le" → "au". "de + les" → "des". "à + les" → "aux". You can't say "de le" or "à le" — the contraction is mandatory.`}],exercises:[{type:`translation`,prompt:`Say "the children" — where does the liaison go?`,answer:`les enfants`,hint:`The s in les links to the vowel: lez-onfants`},{type:`multiple-choice`,prompt:`Which phrase shows correct elision?`,answer:`l'école`,options:[`le école`,`la école`,`l'école`,`les école`]},{type:`multiple-choice`,prompt:`"de + le marché" contracts to?`,answer:`du marché`,options:[`de le marché`,`du marché`,`del marché`,`des marché`]}]}],isPreA1:!0,isA1:!1,isBeyondA1:!1},{id:`building-blocks`,slug:`building-blocks`,title:`The Vocab You're Missing`,emoji:`🎨`,tagline:`Colors, Days & Months`,funnyDescription:`Colors go after the noun. Days aren't capitalized. Months aren't either. The calendar week starts on Monday. These are the building blocks everything else is built on.`,color:`#10B981`,accentColor:`#34d399`,lessons:[{id:`building-blocks-1`,title:`Colors: Say What You See`,subtitle:`Because "the red one, please" is more useful than you think.`,xpReward:15,vocab:[{french:`rouge`,english:`red`,pronunciation:`ʁuʒ`,example:`Un vin rouge`,exampleTranslation:`A red wine`},{french:`bleu(e)`,english:`blue`,pronunciation:`blø / bløz`,example:`La mer est bleue.`,exampleTranslation:`The sea is blue.`},{french:`vert(e)`,english:`green`,pronunciation:`vɛʁ / vɛʁt`,example:`Une pomme verte`,exampleTranslation:`A green apple`,funnyNote:`The feminine adds a T sound that's audible: vɛʁt.`},{french:`jaune`,english:`yellow`,pronunciation:`ʒon`,funnyNote:`Same form for masc and fem. Easy win.`},{french:`blanc / blanche`,english:`white`,pronunciation:`blɑ̃ / blɑ̃ʃ`,funnyNote:`One of the trickier agreements — the feminine "blanche" adds that -che ending that you can hear.`},{french:`noir(e)`,english:`black`,pronunciation:`nwaʁ`},{french:`gris(e)`,english:`grey`,pronunciation:`ɡʁi / ɡʁiz`},{french:`rose`,english:`pink`,pronunciation:`ʁoz`,funnyNote:`Same form regardless of gender.`},{french:`orange`,english:`orange`,pronunciation:`oʁɑ̃ʒ`,funnyNote:`Invariable — never changes, regardless of gender or number.`},{french:`violet / violette`,english:`purple / violet`,pronunciation:`vjolɛ / vjolɛt`},{french:`marron`,english:`brown`,pronunciation:`maʁɔ̃`,funnyNote:`Literally "chestnut". Marron is invariable — never changes form, unlike most adjectives.`}],exercises:[{type:`multiple-choice`,prompt:`What color is "rouge"?`,answer:`Red`,options:[`Blue`,`Red`,`Green`,`Yellow`]},{type:`translation`,prompt:`How do you say "a red wine" in French?`,answer:`Un vin rouge`,hint:`Adjectives come after the noun in French`},{type:`multiple-choice`,prompt:`Which color is invariable — never changes form?`,answer:`orange`,options:[`blanc`,`vert`,`orange`,`violet`]}]},{id:`building-blocks-2`,title:`Days of the Week`,subtitle:`No capital letters, Monday starts the week, and the weekend is a concept.`,xpReward:20,vocab:[{french:`lundi`,english:`Monday`,pronunciation:`lœ̃di`,funnyNote:`Days are never capitalized in French. The calendar week starts on Monday, not Sunday.`},{french:`mardi`,english:`Tuesday`,pronunciation:`maʁdi`},{french:`mercredi`,english:`Wednesday`,pronunciation:`mɛʁkʁədi`},{french:`jeudi`,english:`Thursday`,pronunciation:`ʒødi`},{french:`vendredi`,english:`Friday`,pronunciation:`vɑ̃dʁədi`},{french:`samedi`,english:`Saturday`,pronunciation:`samdi`},{french:`dimanche`,english:`Sunday`,pronunciation:`dimɑ̃ʃ`,funnyNote:`Sunday is the 7th day on French calendars, not the 1st. Most shops are closed. Not a minor inconvenience — a cultural institution.`},{french:`aujourd'hui`,english:`today`,pronunciation:`oʒuʁdɥi`,funnyNote:`Literally "on the day of today" — it's very layered. But entirely normal to say.`},{french:`demain`,english:`tomorrow`,pronunciation:`dəmɛ̃`},{french:`hier`,english:`yesterday`,pronunciation:`jɛʁ`}],exercises:[{type:`multiple-choice`,prompt:`Which day comes after mercredi (Wednesday)?`,answer:`Jeudi`,options:[`Mardi`,`Lundi`,`Jeudi`,`Samedi`]},{type:`translation`,prompt:`How do you say "yesterday" in French?`,answer:`hier`,hint:`Sounds like "yair"`},{type:`fill-blank`,prompt:`___jourd'hui means "today"`,answer:`au`,hint:`Au + jour + d'hui`}]},{id:`building-blocks-3`,title:`Months, Seasons & Dates`,subtitle:`The date system is perfectly logical once you stop expecting it to be English.`,xpReward:20,vocab:[{french:`janvier / février / mars`,english:`January / February / March`,pronunciation:`ʒɑ̃vje / fevʁije / maʁs`},{french:`avril / mai / juin`,english:`April / May / June`,pronunciation:`avʁil / mɛ / ʒɥɛ̃`},{french:`juillet / août / septembre`,english:`July / August / September`,pronunciation:`ʒɥijɛ / u / sɛptɑ̃bʁ`,funnyNote:`"Août" is the stealth word — technically "ut" or just a brief "oo". Many native speakers barely say it.`},{french:`octobre / novembre / décembre`,english:`October / November / December`,pronunciation:`ɔktɔbʁ / nɔvɑ̃bʁ / desɑ̃bʁ`},{french:`le printemps / l'été`,english:`spring / summer`,pronunciation:`pʁɛ̃tɑ̃ / lete`,funnyNote:`Use "au" before printemps: "au printemps". Use "en" before the others: en été, en automne, en hiver.`},{french:`l'automne / l'hiver`,english:`autumn / winter`,pronunciation:`lotɔn / livɛʁ`},{french:`le premier janvier`,english:`the 1st of January`,pronunciation:`lə pʁəmje ʒɑ̃vje`,funnyNote:`For the 1st, use "premier". For all other dates, use the cardinal number: le deux février, le vingt mars, etc.`}],exercises:[{type:`multiple-choice`,prompt:`Which month comes after juillet (July)?`,answer:`Août`,options:[`Juin`,`Septembre`,`Août`,`Mai`]},{type:`translation`,prompt:`How do you say "in summer" in French?`,answer:`en été`,hint:`Use "en" before vowel-starting seasons`},{type:`multiple-choice`,prompt:`How do you say "the 1st of March"?`,answer:`le premier mars`,options:[`le un mars`,`le premier mars`,`le 1 mars`,`une mars`]}]},{id:`building-blocks-4`,title:`Same Words, Different Order`,subtitle:`Where French puts its words: same basic order, colors after the noun, and the ne…pas sandwich.`,xpReward:20,vocab:[{french:`Je mange une pomme.`,english:`I eat an apple.`,pronunciation:`ʒə mɑ̃ʒ yn pɔm`,funnyNote:`Good news first: who + does + what lines up word for word with English. Je = I, mange = eat, une pomme = an apple.`},{french:`Elle parle français.`,english:`She speaks French.`,pronunciation:`ɛl paʁl fʁɑ̃sɛ`,example:`Il parle anglais.`,exampleTranslation:`He speaks English.`},{french:`une voiture rouge`,english:`a red car`,pronunciation:`yn vwatyʁ ʁuʒ`,funnyNote:`French names the thing first, then describes it — literally "a car red". Colors always go after the noun.`},{french:`un chat noir`,english:`a black cat`,pronunciation:`œ̃ ʃa nwaʁ`,example:`J'ai un chat noir.`,exampleTranslation:`I have a black cat.`},{french:`Je ne mange pas.`,english:`I don't eat.`,pronunciation:`ʒə nə mɑ̃ʒ pa`,funnyNote:`Negation is a sandwich: ne goes in front of the verb, pas right after it. There's no word for "do" — French doesn't need a helper.`},{french:`Nous ne sommes pas fatigués.`,english:`We are not tired.`,pronunciation:`nu nə sɔm pa fatige`,example:`Tu ne danses pas.`,exampleTranslation:`You don't dance.`}],exercises:[{type:`multiple-choice`,prompt:`How do you say "a red car"?`,answer:`une voiture rouge`,options:[`une rouge voiture`,`une voiture rouge`,`rouge une voiture`,`une voiture de rouge`]},{type:`multiple-choice`,prompt:`Which sentence means "I don't eat"?`,answer:`Je ne mange pas`,options:[`Je ne mange pas`,`Je pas mange`,`Je ne pas mange`,`Ne je mange pas`]},{type:`fill-blank`,prompt:`Il ___ parle pas anglais. (He doesn't speak English)`,answer:`ne`,hint:`The front slice of the negation sandwich`},{type:`fill-blank`,prompt:`J'ai un chat ___. (I have a black cat)`,answer:`noir`,hint:`The color comes after the noun`},{type:`translation`,prompt:`You like the cat.`,answer:`Tu aimes le chat`,hint:`Same order as English: tu + aimes + le chat`},{type:`translation`,prompt:`You don't dance.`,answer:`Tu ne danses pas`,hint:`ne before the verb, pas after it`}]}],isPreA1:!0,isA1:!1,isBeyondA1:!1},{id:`emergency`,slug:`emergency`,title:`Oh Non, I'm in France`,emoji:`🚨`,tagline:`Emergency Survival`,funnyDescription:`You've been teleported. You have 5 phrases. Choose wisely. This unit might literally save your life — or at least your dignity.`,color:`#E63946`,accentColor:`#ff6b75`,lessons:[{id:`emergency-1`,title:`The 5 Phrases That Could Save Your Life`,subtitle:`You've been teleported. These are your weapons.`,xpReward:20,vocab:[{french:`Je ne parle pas français`,english:`I don't speak French`,pronunciation:`ʒə nə paʁl pa fʁɑ̃sɛ`,example:`Excusez-moi, je ne parle pas français.`,exampleTranslation:`Excuse me, I don't speak French.`,funnyNote:`The most important sentence in this entire course. Master this first.`},{french:`Parlez-vous anglais ?`,english:`Do you speak English?`,pronunciation:`paʁle vu ɑ̃ɡlɛ`,example:`Parlez-vous anglais ? S'il vous plaît ?`,exampleTranslation:`Do you speak English? Please?`,funnyNote:`Delivered with maximum hopeful desperation. The French secretly respect the attempt.`},{french:`Au secours !`,english:`Help!`,pronunciation:`o skuʁ`,funnyNote:`Not for mild inconveniences. Reserved for actual emergencies, like being lost or ordering the wrong wine.`},{french:`Appelez la police !`,english:`Call the police!`,pronunciation:`aple la pɔlis`,funnyNote:`Hopefully you won't need this. But here it is.`},{french:`J'ai besoin d'aide`,english:`I need help`,pronunciation:`ʒɛ bəzwɛ̃ dɛd`,example:`J'ai besoin d'aide, s'il vous plaît.`,exampleTranslation:`I need help, please.`,funnyNote:`Less alarming than "Au secours!" — good for logistics emergencies like missing your train.`},{french:`Je suis perdu(e)`,english:`I'm lost`,pronunciation:`ʒə sɥi pɛʁdy`,example:`Excusez-moi, je suis perdu.`,exampleTranslation:`Excuse me, I'm lost.`,funnyNote:`Add the -e at the end if you identify as feminine. French cares about this more than you do right now.`}],exercises:[{type:`multiple-choice`,prompt:`Someone asks you a question in rapid French. You don't understand. What do you say?`,answer:`Je ne parle pas français`,options:[`Je suis fatigué`,`Je ne parle pas français`,`Au secours !`,`L'addition, s'il vous plaît`]},{type:`multiple-choice`,prompt:`How do you ask someone if they speak English?`,answer:`Parlez-vous anglais ?`,options:[`Avez-vous anglais ?`,`Parlez-vous anglais ?`,`Vous parlez comment ?`,`Anglais, oui ?`]},{type:`translation`,prompt:`Translate: "I need help"`,answer:`J'ai besoin d'aide`,hint:`Think: "I have need of help"`},{type:`fill-blank`,prompt:`Complete: "Parlez-vous ___ ?" (do you speak English?)`,answer:`anglais`,hint:`The French word for English`}]},{id:`emergency-2`,title:`Numbers for Emergencies`,subtitle:`When you need to call someone, tell them an address, or say your hotel room number.`,xpReward:15,vocab:[{french:`zéro`,english:`zero`,pronunciation:`zeʁo`},{french:`un / une`,english:`one`,pronunciation:`œ̃ / yn`,funnyNote:`Masculine vs feminine. Even numbers have a gender here.`},{french:`deux`,english:`two`,pronunciation:`dø`},{french:`trois`,english:`three`,pronunciation:`tʁwa`},{french:`quatre`,english:`four`,pronunciation:`katʁ`},{french:`cinq`,english:`five`,pronunciation:`sɛ̃k`},{french:`six`,english:`six`,pronunciation:`sis`},{french:`sept`,english:`seven`,pronunciation:`sɛt`},{french:`huit`,english:`eight`,pronunciation:`ɥit`},{french:`neuf`,english:`nine`,pronunciation:`nœf`},{french:`dix`,english:`ten`,pronunciation:`dis`},{french:`quinze`,english:`fifteen`,pronunciation:`kɛ̃z`,funnyNote:`Good for emergency hotlines — 15 is SAMU (medical emergency).`},{french:`dix-sept`,english:`seventeen`,pronunciation:`dis sɛt`,funnyNote:`17 = Police. Very useful.`},{french:`dix-huit`,english:`eighteen`,pronunciation:`diz ɥit`,funnyNote:`18 = Fire department. Also very useful.`}],exercises:[{type:`multiple-choice`,prompt:`The French emergency number for police is 17. How do you say 17?`,answer:`dix-sept`,options:[`seize`,`dix-sept`,`dix-huit`,`vingt`]},{type:`translation`,prompt:`What number is "trois" ?`,answer:`3`,hint:`It sounds like "tʁwa"`},{type:`fill-blank`,prompt:`Five in French is "___ "`,answer:`cinq`}]}],isA1:!0,isBeyondA1:!1},{id:`food`,slug:`food`,title:`Feed Me or I'll Cry`,emoji:`🥐`,tagline:`Food, Cafés & Restaurants`,funnyDescription:`The croissant is your first friend. Treat it with respect. Also learn how to order coffee without getting a tall drip from somewhere that rhymes with Starducks.`,color:`#F4A261`,accentColor:`#f7b87a`,lessons:[{id:`food-1`,title:`The Sacred Art of Ordering Coffee`,subtitle:`In France, getting this wrong is a social crime.`,xpReward:20,vocab:[{french:`Un café, s'il vous plaît`,english:`A coffee, please`,pronunciation:`œ̃ kafe sil vu plɛ`,funnyNote:`"Un café" is an espresso. If you want a big American coffee, say "un café allongé". Do not ask for a "grande". Just don't.`},{french:`Un café au lait`,english:`Coffee with milk (breakfast style)`,pronunciation:`œ̃ kafe o lɛ`,funnyNote:`This is the big bowl of coffee French people dunk their croissants into at breakfast. Charming.`},{french:`Un croissant, s'il vous plaît`,english:`A croissant, please`,pronunciation:`œ̃ kʁwasɑ̃ sil vu plɛ`,funnyNote:`The correct pronunciation is NOT "croy-sant". It's "kwah-sahn". Your soul will cringe the first time you say it right, but you'll feel proud afterwards.`},{french:`L'addition, s'il vous plaît`,english:`The bill, please`,pronunciation:`ladisjɔ̃ sil vu plɛ`,funnyNote:`French waiters will NOT bring the bill until you ask. You could sit there for geological epochs. Ask for it.`},{french:`C'est délicieux !`,english:`It's delicious!`,pronunciation:`sɛ delisjø`,funnyNote:`Say this whenever you eat anything. The French will beam.`},{french:`La carte, s'il vous plaît`,english:`The menu, please`,pronunciation:`la kaʁt sil vu plɛ`,funnyNote:`"La carte" is the menu. "Le menu" is actually the fixed-price meal deal. French is designed to trip you up.`}],exercises:[{type:`multiple-choice`,prompt:`You're at a Parisian café. You want an espresso. What do you say?`,answer:`Un café, s'il vous plaît`,options:[`Un grand café`,`Un café, s'il vous plaît`,`Un espresso, please`,`Je voudrais un Starbucks`]},{type:`translation`,prompt:`How do you ask for the bill?`,answer:`L'addition, s'il vous plaît`,hint:`"L'addition" means "the bill"`},{type:`multiple-choice`,prompt:`You want to see the menu. What do you ask for?`,answer:`La carte, s'il vous plaît`,options:[`Le menu, s'il vous plaît`,`La carte, s'il vous plaît`,`La liste`,`Les options`]}]},{id:`food-2`,title:`At the Restaurant: Ordering & Surviving`,subtitle:`Navigate a French menu without accidentally ordering offal.`,xpReward:25,vocab:[{french:`Je voudrais...`,english:`I would like...`,pronunciation:`ʒə vudʁɛ`,example:`Je voudrais le poulet, s'il vous plaît.`,exampleTranslation:`I would like the chicken, please.`,funnyNote:`More polite than "Je veux" (I want). Don't use "Je veux" with strangers unless you want them to judge you silently.`},{french:`Qu'est-ce que vous recommandez ?`,english:`What do you recommend?`,pronunciation:`kɛskə vu ʁəkɔmɑ̃de`,funnyNote:`This question has a magic effect on French waiters. They suddenly become human.`},{french:`Je suis végétarien(ne)`,english:`I'm vegetarian`,pronunciation:`ʒə sɥi veʒetaʁjɛ̃`,funnyNote:`Be prepared to have a philosophical discussion. France is improving on this front, but slowly.`},{french:`Je suis allergique à...`,english:`I'm allergic to...`,pronunciation:`ʒə sɥi alɛʁʒik a`,funnyNote:`Important. Very important. Say this clearly and slowly.`},{french:`C'est trop salé / sucré / épicé`,english:`It's too salty / sweet / spicy`,pronunciation:`sɛ tʁo sale / sykʁe / epise`,funnyNote:`Complaining about food in France is a delicate art. Tread carefully.`},{french:`Une carafe d'eau, s'il vous plaît`,english:`A jug of tap water, please`,pronunciation:`yn kaʁaf do sil vu plɛ`,funnyNote:`FREE in French restaurants by law. They can't refuse this. Knowing this will save you money.`}],exercises:[{type:`translation`,prompt:`Say "I would like the fish, please" (le poisson = fish)`,answer:`Je voudrais le poisson, s'il vous plaît`,hint:`Start with "Je voudrais..."`},{type:`multiple-choice`,prompt:`You're vegetarian. What do you say to the waiter?`,answer:`Je suis végétarien`,options:[`Je mange pas viande`,`Je suis végétarien`,`Pas de viande, merci`,`Je ne veux pas meat`]},{type:`fill-blank`,prompt:`Free water in French restaurants: "Une ___ d'eau, s'il vous plaît"`,answer:`carafe`,hint:`The container that holds the water`}]},{id:`food-3`,title:`Boulangerie Basics`,subtitle:`The bread is non-negotiable. You must buy bread.`,xpReward:15,vocab:[{french:`Une baguette, s'il vous plaît`,english:`A baguette, please`,pronunciation:`yn baɡɛt sil vu plɛ`,funnyNote:`A well-baked baguette. Carrying one under your arm is not a stereotype, it's a lifestyle.`},{french:`Bien cuite`,english:`Well done / crispy`,pronunciation:`bjɛ̃ kɥit`,funnyNote:`Ask for this if you want a darker, crunchier baguette. Some bakeries will look at you knowingly.`},{french:`Un pain au chocolat`,english:`A chocolate croissant`,pronunciation:`œ̃ pɛ̃ o ʃɔkɔla`,funnyNote:`NOT a "chocolatine". Unless you're in southwest France. This debate is their version of the pronunciation war.`},{french:`C'est combien ?`,english:`How much is it?`,pronunciation:`sɛ kɔ̃bjɛ̃`,funnyNote:`A baguette costs about €1–€1.50. If it's more, you're in a tourist trap.`}],exercises:[{type:`multiple-choice`,prompt:`You want a crispy baguette. What extra word do you add?`,answer:`Bien cuite`,options:[`Très bonne`,`Bien cuite`,`Extra croustillante`,`Avec crunch`]},{type:`translation`,prompt:`How do you ask "How much is it?"`,answer:`C'est combien ?`,hint:`It literally means "It's how much?"`}]}],isA1:!0,isBeyondA1:!1},{id:`directions`,slug:`directions`,title:`Where On Earth Am I?`,emoji:`🗺️`,tagline:`Getting Around`,funnyDescription:`Parisians walk at twice the speed of everyone else. Learn to ask directions while jogging. The metro is your friend; Google Maps is your backup.`,color:`#2A9D8F`,accentColor:`#3ab5a6`,lessons:[{id:`directions-1`,title:`Getting Around Without Getting Arrested`,subtitle:`Parisians walk at twice the speed of everyone else. Learn this fast.`,xpReward:25,vocab:[{french:`Où est... ?`,english:`Where is... ?`,pronunciation:`u ɛ`,example:`Où est la station de métro ?`,exampleTranslation:`Where is the metro station?`,funnyNote:`The most useful two words in this course. Memorize them.`},{french:`À gauche`,english:`To the left`,pronunciation:`a ɡoʃ`,funnyNote:`Gauche also means "awkward" in English. Think of turning left as the awkward option.`},{french:`À droite`,english:`To the right`,pronunciation:`a dʁwat`,funnyNote:`"Droite" also means "right" as in correct/right-wing. Politically charged navigation.`},{french:`Tout droit`,english:`Straight ahead`,pronunciation:`tu dʁwa`,funnyNote:`Not "tout droite". The gender disappears here. French just does this sometimes to spite you.`},{french:`Tournez à gauche / droite`,english:`Turn left / right`,pronunciation:`tuʁne a ɡoʃ / dʁwat`},{french:`La station de métro`,english:`The metro station`,pronunciation:`la stasjɔ̃ də metʁo`,funnyNote:`Paris has one of the best metro systems on Earth. Trust it.`},{french:`L'arrêt de bus`,english:`The bus stop`,pronunciation:`laʁɛ də bys`},{french:`C'est loin ?`,english:`Is it far?`,pronunciation:`sɛ lwɛ̃`,funnyNote:`French people will say "non, c'est pas loin" for things that are 30 minutes away. Be skeptical.`}],exercises:[{type:`multiple-choice`,prompt:`You need the metro. What do you ask?`,answer:`Où est la station de métro ?`,options:[`Où est le taxi ?`,`Où est la station de métro ?`,`Comment aller métro ?`,`Metro, s'il vous plaît`]},{type:`multiple-choice`,prompt:`Someone says "tournez à gauche". What do they mean?`,answer:`Turn left`,options:[`Turn right`,`Go straight`,`Turn left`,`Stop here`]},{type:`translation`,prompt:`How do you say "Straight ahead"?`,answer:`Tout droit`,hint:`Two words — no gender ending needed`},{type:`fill-blank`,prompt:`"___ est la pharmacie ?" (Where is the pharmacy?)`,answer:`Où`,hint:`The French word for "where". Mind the accents.`}]},{id:`directions-2`,title:`Taxis, Trains & Getting Out of Trouble`,subtitle:`When your feet give up.`,xpReward:20,vocab:[{french:`Appelez-moi un taxi, s'il vous plaît`,english:`Call me a taxi, please`,pronunciation:`aple mwa œ̃ taksi sil vu plɛ`,funnyNote:`Or just use an app. But knowing this phrase is never wrong.`},{french:`Je voudrais aller à...`,english:`I would like to go to...`,pronunciation:`ʒə vudʁɛ ale a`,example:`Je voudrais aller à la Tour Eiffel.`,exampleTranslation:`I would like to go to the Eiffel Tower.`},{french:`Un aller simple / Un aller-retour`,english:`One way / Round trip`,pronunciation:`œ̃ nale sɛ̃pl / œ̃ nale ʁətuʁ`,funnyNote:`Know this for the train. Trains are excellent in France.`},{french:`À quelle heure part le train ?`,english:`What time does the train leave?`,pronunciation:`a kɛl œʁ paʁ lə tʁɛ̃`},{french:`Composez votre billet !`,english:`Validate your ticket!`,pronunciation:`kɔ̃poze vɔtʁ bijɛ`,funnyNote:`The yellow machines on the platform. ALWAYS stamp your ticket before boarding or face a fine. This is how they get tourists.`}],exercises:[{type:`translation`,prompt:`Say: "I would like to go to the airport" (l'aéroport = airport)`,answer:`Je voudrais aller à l'aéroport`,hint:`"Je voudrais aller à" + destination. Mind the accents.`},{type:`multiple-choice`,prompt:`You're buying a one-way train ticket. What do you ask for?`,answer:`Un aller simple`,options:[`Un ticket simple`,`Un aller simple`,`Un aller seul`,`Un billet unique`]}]}],isA1:!0,isBeyondA1:!1},{id:`numbers`,slug:`numbers`,title:`Money Talks (Poorly)`,emoji:`💶`,tagline:`Numbers & Money`,funnyDescription:`€4.50 for an espresso. You need to understand what just happened to your wallet. Also: French counting goes completely off the rails after 60.`,color:`#457B9D`,accentColor:`#5a93b8`,lessons:[{id:`numbers-1`,title:`Numbers 1–20: The Foundation`,subtitle:`€4.50 for an espresso. You need to understand what just happened.`,xpReward:20,vocab:[{french:`un / une`,english:`1`,pronunciation:`œ̃ / yn`},{french:`deux`,english:`2`,pronunciation:`dø`},{french:`trois`,english:`3`,pronunciation:`tʁwa`},{french:`quatre`,english:`4`,pronunciation:`katʁ`},{french:`cinq`,english:`5`,pronunciation:`sɛ̃k`},{french:`six`,english:`6`,pronunciation:`sis`},{french:`sept`,english:`7`,pronunciation:`sɛt`},{french:`huit`,english:`8`,pronunciation:`ɥit`},{french:`neuf`,english:`9`,pronunciation:`nœf`},{french:`dix`,english:`10`,pronunciation:`dis`},{french:`onze`,english:`11`,pronunciation:`ɔ̃z`},{french:`douze`,english:`12`,pronunciation:`duz`},{french:`treize`,english:`13`,pronunciation:`tʁɛz`},{french:`quatorze`,english:`14`,pronunciation:`katɔʁz`},{french:`quinze`,english:`15`,pronunciation:`kɛ̃z`},{french:`seize`,english:`16`,pronunciation:`sɛz`},{french:`dix-sept`,english:`17`,pronunciation:`dis sɛt`},{french:`dix-huit`,english:`18`,pronunciation:`diz ɥit`},{french:`dix-neuf`,english:`19`,pronunciation:`diz nœf`},{french:`vingt`,english:`20`,pronunciation:`vɛ̃`,funnyNote:`The "t" is silent. Of course it is.`}],exercises:[{type:`multiple-choice`,prompt:`What number is "quinze"?`,answer:`15`,options:[`12`,`14`,`15`,`16`]},{type:`multiple-choice`,prompt:`How do you say "17"?`,answer:`dix-sept`,options:[`seize`,`dix-sept`,`sept-dix`,`dix-neuf`]},{type:`translation`,prompt:`Write the French word for 8`,answer:`huit`,hint:`IPA: /ɥit/`}]},{id:`numbers-2`,title:`Numbers 20–100: The Chaos Begins`,subtitle:`French counting works normally until 60. Then it goes completely off the rails.`,xpReward:25,vocab:[{french:`vingt`,english:`20`,pronunciation:`vɛ̃`},{french:`trente`,english:`30`,pronunciation:`tʁɑ̃t`},{french:`quarante`,english:`40`,pronunciation:`kaʁɑ̃t`},{french:`cinquante`,english:`50`,pronunciation:`sɛ̃kɑ̃t`},{french:`soixante`,english:`60`,pronunciation:`swasɑ̃t`},{french:`soixante-dix`,english:`70`,pronunciation:`swasɑ̃t dis`,funnyNote:`Literally "sixty-ten". Because why use a simple word when you can do mental math?`},{french:`quatre-vingts`,english:`80`,pronunciation:`katʁ vɛ̃`,funnyNote:`Literally "four-twenties". France invented this number system in a fit of creative madness.`},{french:`quatre-vingt-dix`,english:`90`,pronunciation:`katʁ vɛ̃ dis`,funnyNote:`Literally "four-twenty-ten". Belgium and Switzerland said no and invented "nonante". They are right.`},{french:`cent`,english:`100`,pronunciation:`sɑ̃`}],exercises:[{type:`multiple-choice`,prompt:`"Quatre-vingts" literally means what?`,answer:`Four twenties`,options:[`Four tens`,`Four twenties`,`Eighty things`,`Some large number`]},{type:`multiple-choice`,prompt:`How do the French say 70?`,answer:`soixante-dix (sixty-ten)`,options:[`septante`,`soixante-dix (sixty-ten)`,`sept-dix`,`soixante-sept`]},{type:`translation`,prompt:`Write 100 in French`,answer:`cent`,hint:`Like the English word "sent"`}]},{id:`numbers-3`,title:`Time & Money`,subtitle:`The two things France will test your nerves with.`,xpReward:20,vocab:[{french:`Quelle heure est-il ?`,english:`What time is it?`,pronunciation:`kɛl œʁ ɛtil`,funnyNote:`Important for catching the last metro at 1:15am.`},{french:`Il est... heures`,english:`It is... o'clock`,pronunciation:`il ɛ œʁ`,example:`Il est deux heures.`,exampleTranslation:`It's two o'clock.`},{french:`Il est midi / minuit`,english:`It's noon / midnight`,pronunciation:`il ɛ midi / minɥi`,funnyNote:`Restaurants typically take lunch orders 12h–14h30. Miss this window and you'll be eating a sad supermarket sandwich.`},{french:`C'est combien ?`,english:`How much is it?`,pronunciation:`sɛ kɔ̃bjɛ̃`},{french:`Trop cher !`,english:`Too expensive!`,pronunciation:`tʁo ʃɛʁ`,funnyNote:`Optional. But satisfying.`},{french:`Avez-vous de la monnaie ?`,english:`Do you have change?`,pronunciation:`ave vu də la mɔnɛ`,funnyNote:`Coins are actually still used in France. Cash is not dead here.`}],exercises:[{type:`translation`,prompt:`How do you ask "What time is it?"`,answer:`Quelle heure est-il ?`,hint:`Literally "which hour is it?"`},{type:`multiple-choice`,prompt:`Something costs way too much. What do you mutter?`,answer:`Trop cher !`,options:[`Très bon !`,`Trop cher !`,`Pas cher`,`C'est correct`]},{type:`fill-blank`,prompt:`"C'est ___ ?" (How much is it?)`,answer:`combien`,hint:`The French word for "how much/how many"`}]}],isA1:!0,isBeyondA1:!1},{id:`greetings`,slug:`greetings`,title:`Bonjour, Everyone`,emoji:`👋`,tagline:`Greetings & Social`,funnyDescription:`Not saying "bonjour" to the shopkeeper is a genuine social transgression. We'll explain the rules, the bisou minefield, and when "salut" will get you judged.`,color:`#6A4C93`,accentColor:`#8a6cb3`,lessons:[{id:`greetings-1`,title:`Bonjour: The Most Important Word in France`,subtitle:`Not saying it to a shopkeeper is considered a war crime here.`,xpReward:20,vocab:[{french:`Bonjour`,english:`Good morning / Good day`,pronunciation:`bɔ̃ʒuʁ`,funnyNote:`Say this to EVERYONE when you enter a shop, a bakery, a doctor's office, an elevator. Always. The French will think better of you immediately.`},{french:`Bonsoir`,english:`Good evening`,pronunciation:`bɔ̃swaʁ`,funnyNote:`Switch from "bonjour" to "bonsoir" around 6pm. There's no hard rule. Just feel it.`},{french:`Bonne nuit`,english:`Good night`,pronunciation:`bɔn nɥi`,funnyNote:`Only when actually going to sleep. Not a general evening greeting.`},{french:`Salut`,english:`Hi / Bye (informal)`,pronunciation:`saly`,funnyNote:`Only with friends! Using "salut" with a stranger in a shop is like patting your boss on the head.`},{french:`Au revoir`,english:`Goodbye`,pronunciation:`o ʁəvwaʁ`,funnyNote:`Literally "until seeing again". Say this AND "bonne journée" when leaving a shop. Both. The full combo.`},{french:`Bonne journée !`,english:`Have a good day!`,pronunciation:`bɔn ʒuʁne`,funnyNote:`This is the required exit phrase. Shopkeepers will love you.`}],exercises:[{type:`multiple-choice`,prompt:`You enter a boulangerie at 9am. What's the first thing you say?`,answer:`Bonjour !`,options:[`Salut !`,`Bonjour !`,`Bonsoir !`,`Bonne nuit !`]},{type:`multiple-choice`,prompt:`You're leaving a shop. What's the proper farewell combo?`,answer:`Au revoir, bonne journée !`,options:[`Salut, ciao`,`Au revoir, bonne journée !`,`Bye bye`,`Adieu`]},{type:`translation`,prompt:`What does "Bonsoir" mean?`,answer:`Good evening`,hint:`Used in the evening, not morning`}]},{id:`greetings-2`,title:`Introductions & The Bisou Minefield`,subtitle:`One cheek? Two? Left first or right? Nobody agrees. We'll explain.`,xpReward:25,vocab:[{french:`Comment vous appelez-vous ?`,english:`What is your name? (formal)`,pronunciation:`kɔmɑ̃ vu zaple vu`,funnyNote:`Formal version. Use with strangers, elders, or anyone you want to impress.`},{french:`Je m'appelle...`,english:`My name is...`,pronunciation:`ʒə mapɛl`,example:`Je m'appelle Sophie.`,exampleTranslation:`My name is Sophie.`},{french:`Enchanté(e)`,english:`Pleased to meet you`,pronunciation:`ɑ̃ʃɑ̃te`,funnyNote:`Add -e if you're feminine. "Enchanté" is arguably the most sophisticated thing you can say in French.`},{french:`Comment allez-vous ?`,english:`How are you? (formal)`,pronunciation:`kɔmɑ̃ ale vu`,funnyNote:`The formal "How are you". Expect "Très bien, merci" in response regardless of actual situation.`},{french:`Ça va ?`,english:`How's it going? (informal)`,pronunciation:`sa va`,funnyNote:`"Ça va?" is also the answer: "Ça va." It means everything from fine to catastrophically bad. Context is everything.`},{french:`Très bien, merci`,english:`Very well, thank you`,pronunciation:`tʁɛ bjɛ̃ mɛʁsi`,funnyNote:`The auto-response. Comes out before you can think.`}],exercises:[{type:`translation`,prompt:`How do you say "My name is Marco"?`,answer:`Je m'appelle Marco`,hint:`Start with "Je m'appelle"`},{type:`multiple-choice`,prompt:`What does "Enchanté" mean?`,answer:`Pleased to meet you`,options:[`Enchanted`,`Very good`,`Pleased to meet you`,`My pleasure`]},{type:`fill-blank`,prompt:`"___ va ?" (How's it going?)`,answer:`Ça`,hint:`The short casual greeting`}]},{id:`greetings-3`,title:`Politeness Power-Ups`,subtitle:`The magic words that make France tolerable — and often delightful.`,xpReward:15,vocab:[{french:`S'il vous plaît`,english:`Please (formal)`,pronunciation:`sil vu plɛ`,funnyNote:`Literally "if it pleases you". Extremely important. Use it constantly.`},{french:`Merci`,english:`Thank you`,pronunciation:`mɛʁsi`},{french:`Merci beaucoup`,english:`Thank you very much`,pronunciation:`mɛʁsi boku`},{french:`De rien`,english:`You're welcome`,pronunciation:`də ʁjɛ̃`,funnyNote:`Literally "of nothing". The French are philosophically generous.`},{french:`Excusez-moi`,english:`Excuse me`,pronunciation:`ɛkskyze mwa`,funnyNote:`To get past someone on the street, to get a waiter's attention, to apologize for bumping into someone. One phrase, infinite uses.`},{french:`Pardon`,english:`Sorry / Excuse me`,pronunciation:`paʁdɔ̃`,funnyNote:`Slightly softer than "excusez-moi". Both work. Say one of them. Just say something.`}],exercises:[{type:`multiple-choice`,prompt:`What's the formal way to say "please"?`,answer:`S'il vous plaît`,options:[`Merci`,`S'il vous plaît`,`De rien`,`Pardon`]},{type:`translation`,prompt:`Someone thanks you. How do you say "You're welcome"?`,answer:`De rien`,hint:`Literally "of nothing"`}]}],isA1:!0,isBeyondA1:!1},{id:`shopping`,slug:`shopping`,title:`Retail Therapy`,emoji:`🛍️`,tagline:`Shopping & Pharmacies`,funnyDescription:`French clothing sizes will make you question your entire identity. Also: French pharmacies are incredible and will solve your problems better than WebMD.`,color:`#E76F51`,accentColor:`#f08060`,lessons:[{id:`shopping-1`,title:`Shopping: Clothes & Sizes`,subtitle:`French clothing sizes will make you question your entire identity.`,xpReward:20,vocab:[{french:`Je cherche...`,english:`I'm looking for...`,pronunciation:`ʒə ʃɛʁʃ`,example:`Je cherche une veste.`,exampleTranslation:`I'm looking for a jacket.`},{french:`Avez-vous ça en taille... ?`,english:`Do you have this in size... ?`,pronunciation:`ave vu sa ɑ̃ taj`,funnyNote:`French sizes are different. A French 38 ≈ US 8 for women. You will feel like a different person.`},{french:`C'est trop grand / petit`,english:`It's too big / small`,pronunciation:`sɛ tʁo ɡʁɑ̃ / pəti`},{french:`Je peux essayer ça ?`,english:`Can I try this on?`,pronunciation:`ʒə pø ɛsɛje sa`,funnyNote:`The fitting rooms are called "cabines d'essayage". Point if needed.`},{french:`Je vais le prendre`,english:`I'll take it`,pronunciation:`ʒə vɛ lə pʁɑ̃dʁ`},{french:`Ce n'est pas ce que je cherche`,english:`That's not what I'm looking for`,pronunciation:`sə nɛ pa sə kə ʒə ʃɛʁʃ`,funnyNote:`A polite way to decline without causing international incident.`}],exercises:[{type:`translation`,prompt:`How do you say "I'm looking for a shirt" (une chemise = shirt)?`,answer:`Je cherche une chemise`,hint:`Start with "Je cherche"`},{type:`multiple-choice`,prompt:`The jacket is too big. What do you say?`,answer:`C'est trop grand`,options:[`C'est trop petit`,`C'est trop grand`,`C'est parfait`,`Je le prends`]},{type:`fill-blank`,prompt:`"Je peux ___ ça ?" (Can I try this on?)`,answer:`essayer`,hint:`The verb "to try on"`}]},{id:`shopping-2`,title:`The Pharmacy: Your Unlikely Best Friend`,subtitle:`French pharmacies are incredible. They will solve your problems.`,xpReward:20,vocab:[{french:`La pharmacie`,english:`The pharmacy`,pronunciation:`la faʁmasi`,funnyNote:`Identified by a green cross sign. Open late, staffed by actual pharmacists who can recommend treatments. Better than urgent care for minor issues.`},{french:`J'ai besoin de...`,english:`I need...`,pronunciation:`ʒɛ bəzwɛ̃ də`,example:`J'ai besoin de quelque chose contre le rhume.`,exampleTranslation:`I need something for a cold.`},{french:`J'ai mal à la tête`,english:`I have a headache`,pronunciation:`ʒɛ mal a la tɛt`},{french:`J'ai de la fièvre`,english:`I have a fever`,pronunciation:`ʒɛ də la fjɛvʁ`},{french:`Avez-vous de l'aspirine ?`,english:`Do you have aspirin?`,pronunciation:`ave vu də laspiʁin`},{french:`Une ordonnance`,english:`A prescription`,pronunciation:`yn ɔʁdɔnɑ̃s`,funnyNote:`Many things that require a prescription in the US are over-the-counter in France. Your pharmacist will know.`}],exercises:[{type:`translation`,prompt:`Say "I have a headache"`,answer:`J'ai mal à la tête`,hint:`"J'ai mal à" = I have pain in/at`},{type:`multiple-choice`,prompt:`What is a "pharmacie" identified by?`,answer:`A green cross`,options:[`A red cross`,`A green cross`,`A blue circle`,`A white snake`]}]}],isA1:!0,isBeyondA1:!1},{id:`accommodation`,slug:`accommodation`,title:`A Bed, Please`,emoji:`🏨`,tagline:`Hotels & Accommodation`,funnyDescription:`The shower has 47 settings. None of them work the way you expect. Navigate check-in, WiFi complaints, and the mystery of French breakfast.`,color:`#1D3557`,accentColor:`#2d4d77`,lessons:[{id:`accommodation-1`,title:`Hotel Check-in Without a Breakdown`,subtitle:`The shower has 47 settings. None of them work as expected.`,xpReward:20,vocab:[{french:`J'ai une réservation`,english:`I have a reservation`,pronunciation:`ʒɛ yn ʁezɛʁvasjɔ̃`,funnyNote:`Say this immediately upon entering. It establishes you as a legitimate guest, not someone who wandered in.`},{french:`Au nom de...`,english:`In the name of... / Under the name...`,pronunciation:`o nɔ̃ də`,example:`Au nom de Smith.`,exampleTranslation:`Under the name Smith.`},{french:`Ma chambre, s'il vous plaît`,english:`My room, please`,pronunciation:`ma ʃɑ̃bʁ sil vu plɛ`},{french:`Le WiFi ne fonctionne pas`,english:`The WiFi isn't working`,pronunciation:`lə wifi nə fɔ̃ksjɔn pa`,funnyNote:`A universal phrase. Transcends culture.`},{french:`Il n'y a pas d'eau chaude`,english:`There's no hot water`,pronunciation:`il nja pa do ʃod`,funnyNote:`Critical. Learn this one.`},{french:`À quelle heure est le petit-déjeuner ?`,english:`What time is breakfast?`,pronunciation:`a kɛl œʁ ɛ lə pəti deʒœne`,funnyNote:`French hotel breakfast is often just coffee and bread. Manage expectations accordingly.`},{french:`Clé / Carte magnétique`,english:`Key / Key card`,pronunciation:`kle / kaʁt maɲetik`}],exercises:[{type:`translation`,prompt:`Say "I have a reservation under the name Chen"`,answer:`J'ai une réservation au nom de Chen`,hint:`Combine "J'ai une réservation" + "au nom de" — Mind the accent on à.`},{type:`multiple-choice`,prompt:`The WiFi is broken. What do you say at the front desk?`,answer:`Le WiFi ne fonctionne pas`,options:[`Le WiFi est cassé`,`Le WiFi ne fonctionne pas`,`Internet broken`,`Pas de WiFi ici`]},{type:`fill-blank`,prompt:`"___ n'y a pas d'eau chaude" (There's no hot water)`,answer:`Il`,hint:`The impersonal subject pronoun`},{type:`multiple-choice`,prompt:`You want to know when breakfast is served. What do you ask?`,answer:`À quelle heure est le petit-déjeuner ?`,options:[`Où est le restaurant ?`,`À quelle heure est le petit-déjeuner ?`,`Le buffet est bon ?`,`Quand ouvre la salle ?`]},{type:`translation`,prompt:`Ask for your room key`,answer:`Ma clé, s'il vous plaît`,hint:`"Ma" + the word for key (mind the accent) + "s'il vous plaît"`}]},{id:`accommodation-2`,title:`Room Requests & Amenities`,subtitle:`The minibar is a trap. The view, however, might be worth it.`,xpReward:20,vocab:[{french:`Est-ce que la chambre a une vue sur... ?`,english:`Does the room have a view of...?`,pronunciation:`ɛskə la ʃɑ̃bʁ a yn vy syʁ`,example:`Est-ce que la chambre a une vue sur la mer ?`,exampleTranslation:`Does the room have a sea view?`},{french:`Je voudrais changer de chambre`,english:`I'd like to change rooms`,pronunciation:`ʒə vudʁɛ ʃɑ̃ʒe də ʃɑ̃bʁ`,funnyNote:`Say this politely. You'll be asked why. Have an answer ready.`},{french:`Pouvez-vous apporter... ?`,english:`Could you bring...?`,pronunciation:`puve vu apɔʁte`,example:`Pouvez-vous apporter des serviettes ?`,exampleTranslation:`Could you bring some towels?`},{french:`Des serviettes`,english:`Towels`,pronunciation:`de sɛʁvjɛt`},{french:`La climatisation`,english:`Air conditioning`,pronunciation:`la klimatizasjɔ̃`,funnyNote:`In France: often exists, sometimes works, occasionally freezes you into a different geological era.`},{french:`Le chauffage`,english:`The heating`,pronunciation:`lə ʃofaʒ`},{french:`Changer les draps`,english:`Change the sheets`,pronunciation:`ʃɑ̃ʒe le dʁa`,funnyNote:`Eco-friendly hotels will ask if you want daily changes. "Non merci" saves water and earns points with French environmentalists.`},{french:`L'ascenseur`,english:`The lift / elevator`,pronunciation:`lasɑ̃sœʁ`,funnyNote:`Parisian hotel lifts are often the size of a wardrobe. Your suitcase may need to take the stairs.`},{french:`Le parking`,english:`The car park`,pronunciation:`lə paʁkiŋ`}],exercises:[{type:`translation`,prompt:`Ask "Could you bring towels?"`,answer:`Pouvez-vous apporter des serviettes ?`,hint:`"Pouvez-vous apporter" + what you want`},{type:`multiple-choice`,prompt:`Your room is sweltering. What do you complain about?`,answer:`La climatisation ne fonctionne pas`,options:[`La climatisation ne fonctionne pas`,`Il fait chaud dehors`,`Je veux une fenêtre`,`Le minibar est vide`]},{type:`fill-blank`,prompt:`"Je voudrais ___ de chambre" (I'd like to change rooms)`,answer:`changer`,hint:`The infinitive meaning "to change"`},{type:`multiple-choice`,prompt:`You want a sea-view room. What do you ask?`,answer:`Est-ce que la chambre a une vue sur la mer ?`,options:[`Je veux voir l'eau`,`Est-ce que la chambre a une vue sur la mer ?`,`La chambre est belle ?`,`Puis-je avoir une fenêtre ?`]},{type:`translation`,prompt:`Ask for the sheets to be changed`,answer:`Pouvez-vous changer les draps ?`,hint:`"Pouvez-vous" + "changer les draps"`},{type:`multiple-choice`,prompt:`What is "l'ascenseur"?`,answer:`The lift / elevator`,options:[`The staircase`,`The lift / elevator`,`The lobby`,`The corridor`]}]},{id:`accommodation-3`,title:`Check-out & The Bill`,subtitle:`Mystery charges. Wrong dates. A receipt your accountant demands. Let's handle it.`,xpReward:25,vocab:[{french:`À quelle heure dois-je libérer la chambre ?`,english:`What time do I need to check out?`,pronunciation:`a kɛl œʁ dwa ʒə libere la ʃɑ̃bʁ`,funnyNote:`Standard French check-out is noon. Ask about "late check-out" if your flight is evening.`},{french:`Je voudrais partir demain matin`,english:`I'd like to leave tomorrow morning`,pronunciation:`ʒə vudʁɛ paʁtiʁ dəmɛ̃ matɛ̃`},{french:`La note / La facture`,english:`The bill / The invoice`,pronunciation:`la nɔt / la faktyʁ`,funnyNote:`"La note" is the hotel bill. "La facture" is a formal invoice — the one your company's finance team will demand.`},{french:`Puis-je avoir un reçu ?`,english:`Can I have a receipt?`,pronunciation:`pɥi ʒə avwaʁ œ̃ ʁəsy`},{french:`Il y a une erreur sur la note`,english:`There's an error on the bill`,pronunciation:`il ja yn ɛʁœʁ syʁ la nɔt`,funnyNote:`The most diplomatically useful sentence you'll learn. Stay calm. Point calmly. Be extremely polite.`},{french:`Je n'ai pas utilisé le minibar`,english:`I didn't use the minibar`,pronunciation:`ʒə nɛ pa ytilize lə minibaʁ`,funnyNote:`A classic billing dispute. You didn't touch the €12 cashews. You have principles.`},{french:`Pouvez-vous appeler un taxi ?`,english:`Can you call me a taxi?`,pronunciation:`puve vu aple œ̃ taksi`},{french:`Puis-je laisser mes bagages ici ?`,english:`Can I leave my bags here?`,pronunciation:`pɥi ʒə lɛse me bagaʒ isi`,funnyNote:`Most hotels allow this after check-out if your flight is late. Always ask.`},{french:`Le dépôt de garantie`,english:`The security deposit`,pronunciation:`lə depo də ɡaʁɑ̃ti`,funnyNote:`Usually charged at check-in and released at check-out. Ask when it's refunded if it's not instant.`}],exercises:[{type:`translation`,prompt:`Ask what time you need to check out`,answer:`À quelle heure dois-je libérer la chambre ?`,hint:`"À quelle heure" (mind the accent on À) = at what time, "dois-je libérer la chambre" = do I need to vacate the room`},{type:`multiple-choice`,prompt:`You've been charged for the minibar but didn't touch it. What do you say?`,answer:`Il y a une erreur — je n'ai pas utilisé le minibar`,options:[`Le minibar était vide à mon arrivée`,`Il y a une erreur — je n'ai pas utilisé le minibar`,`Je veux parler au directeur`,`Le minibar est trop cher`]},{type:`fill-blank`,prompt:`"Puis-je avoir un ___ ?" (Can I have a receipt?)`,answer:`reçu`,hint:`The French word for receipt`},{type:`multiple-choice`,prompt:`Your flight is at 8pm but check-out is noon. What do you ask?`,answer:`Puis-je laisser mes bagages ici ?`,options:[`Puis-je rester dans ma chambre ?`,`Puis-je laisser mes bagages ici ?`,`Mon vol est annulé`,`Je voudrais une chambre pour une nuit de plus`]},{type:`translation`,prompt:`Ask the hotel to call you a taxi`,answer:`Pouvez-vous appeler un taxi ?`,hint:`"Pouvez-vous" + "appeler un taxi"`},{type:`multiple-choice`,prompt:`What is the difference between "la note" and "la facture"?`,answer:`"La note" is the hotel bill; "la facture" is a formal invoice`,options:[`They mean the same thing`,`"La note" is the hotel bill; "la facture" is a formal invoice`,`"La note" is a tip; "la facture" is the bill`,`"La facture" is only used at restaurants`]}]}],isA1:!0,isBeyondA1:!1},{id:`medical`,slug:`medical`,title:`I Am Dying (Probably)`,emoji:`🏥`,tagline:`Medical & Health`,funnyDescription:`You ate something. You don't know what. Your stomach has opinions. Learn to communicate body parts, symptoms, and how to get help without panicking.`,color:`#E63946`,accentColor:`#ff6b75`,lessons:[{id:`medical-1`,title:`Body Parts & Symptoms`,subtitle:`You ate something. You don't know what. Your stomach has opinions.`,xpReward:25,vocab:[{french:`J'ai mal à...`,english:`I have pain in my...`,pronunciation:`ʒɛ mal a`,example:`J'ai mal à la tête.`,exampleTranslation:`I have a headache.`,funnyNote:`"J'ai mal à" + body part. The most useful medical construction in French.`},{french:`la tête`,english:`head`,pronunciation:`la tɛt`},{french:`le ventre / l'estomac`,english:`stomach / belly`,pronunciation:`lə vɑ̃tʁ / lɛstɔma`},{french:`le dos`,english:`back`,pronunciation:`lə do`},{french:`la gorge`,english:`throat`,pronunciation:`la ɡɔʁʒ`,funnyNote:`"J'ai mal à la gorge" = sore throat. Very common.`},{french:`Je me sens mal`,english:`I feel sick / I feel bad`,pronunciation:`ʒə mə sɑ̃ mal`},{french:`J'ai de la fièvre`,english:`I have a fever`,pronunciation:`ʒɛ də la fjɛvʁ`},{french:`Je vomis`,english:`I'm vomiting`,pronunciation:`ʒə vɔmi`,funnyNote:`Unglamorous but critical vocabulary.`},{french:`Appelez un médecin !`,english:`Call a doctor!`,pronunciation:`aple œ̃ medsɛ̃`},{french:`Où est l'hôpital ?`,english:`Where is the hospital?`,pronunciation:`u ɛ lopital`}],exercises:[{type:`translation`,prompt:`Say "I have a stomachache"`,answer:`J'ai mal au ventre`,hint:`"J'ai mal à" + le ventre → au ventre (à + le = au)`},{type:`multiple-choice`,prompt:`You feel sick and need a doctor. What do you shout?`,answer:`Appelez un médecin !`,options:[`Je suis malade`,`Appelez un médecin !`,`Aide-moi s'il te plaît`,`Docteur ici !`]},{type:`fill-blank`,prompt:`"Où est ___ ?" (Where is the hospital?)`,answer:`l'hôpital`,hint:`"Hospital" in French, with the article`},{type:`multiple-choice`,prompt:`"J'ai mal à la gorge" means:`,answer:`I have a sore throat`,options:[`I have a headache`,`I have a sore throat`,`I have a stomachache`,`I have a backache`]},{type:`translation`,prompt:`Say "I have a fever"`,answer:`J'ai de la fièvre`,hint:`"J'ai de la" + fièvre. Mind the accents.`}]},{id:`medical-2`,title:`At the Pharmacy`,subtitle:`The green cross is your friend. French pharmacists are surprisingly powerful.`,xpReward:25,vocab:[{french:`La pharmacie`,english:`The pharmacy`,pronunciation:`la faʁmasi`,funnyNote:`Identified by a glowing green cross. French pharmacists can diagnose, recommend, and treat minor issues on the spot. They're basically doctors with better retail space.`},{french:`J'ai besoin de...`,english:`I need...`,pronunciation:`ʒɛ bəzwɛ̃ də`,example:`J'ai besoin de quelque chose contre la toux.`,exampleTranslation:`I need something for a cough.`},{french:`Quelque chose contre...`,english:`Something for... / Something against...`,pronunciation:`kɛlkə ʃoz kɔ̃tʁ`,funnyNote:`"Contre" literally means "against". In France, you are at war with your ailments.`},{french:`La toux`,english:`A cough`,pronunciation:`la tu`},{french:`Le rhume`,english:`A cold`,pronunciation:`lə ʁym`},{french:`Un médicament`,english:`A medicine / medication`,pronunciation:`œ̃ medikamɑ̃`},{french:`Une ordonnance`,english:`A prescription`,pronunciation:`yn ɔʁdɔnɑ̃s`,funnyNote:`Some medications require one. The pharmacist will say "Il faut une ordonnance" — you'll need to see a doctor first.`},{french:`La posologie`,english:`The dosage instructions`,pronunciation:`la pozɔlɔʒi`,funnyNote:`On every medication box. Tells you how much to take and when.`},{french:`J'ai une allergie à...`,english:`I'm allergic to...`,pronunciation:`ʒɛ yn alɛʁʒi a`,funnyNote:`Critical. Say it slowly and clearly before accepting any medication.`},{french:`Des anti-douleurs`,english:`Painkillers`,pronunciation:`de ɑ̃ti dulœʁ`}],exercises:[{type:`translation`,prompt:`Ask for "something for a cough"`,answer:`Quelque chose contre la toux`,hint:`"Quelque chose contre" + the ailment. Mind the accents.`},{type:`multiple-choice`,prompt:`The pharmacist says "Il faut une ordonnance." What does this mean?`,answer:`You need a prescription`,options:[`You need a prescription`,`It's very expensive`,`Come back tomorrow`,`We don't have that`]},{type:`fill-blank`,prompt:`"J'ai ___ de médicaments contre le rhume" (I need cold medicine)`,answer:`besoin`,hint:`"Avoir besoin de" = to need`},{type:`multiple-choice`,prompt:`What is "la posologie" on a medicine box?`,answer:`The dosage instructions`,options:[`The expiry date`,`The dosage instructions`,`The price`,`The ingredients list`]},{type:`translation`,prompt:`Say "I'm allergic to penicillin" (pénicilline)`,answer:`J'ai une allergie à la pénicilline`,hint:`"J'ai une allergie à" + the substance. Mind the accents.`},{type:`multiple-choice`,prompt:`What is "la pharmacie" identified by in France?`,answer:`A glowing green cross`,options:[`A red cross sign`,`A glowing green cross`,`A blue shield`,`A white snake symbol`]}]},{id:`medical-3`,title:`Emergencies & Accidents`,subtitle:`Hopefully you never need this. But if you do, you'll be ready.`,xpReward:30,vocab:[{french:`Au secours !`,english:`Help!`,pronunciation:`o səkuʁ`,funnyNote:`The universal cry for help in French. Louder is better in a genuine emergency.`},{french:`Appelez le SAMU !`,english:`Call an ambulance! (emergency medical service)`,pronunciation:`aple lə samy`,funnyNote:`SAMU = 15. Police = 17. Fire brigade = 18. European emergency number = 112. Save these.`},{french:`J'ai eu un accident`,english:`I've had an accident`,pronunciation:`ʒɛ y œ̃ aksidɑ̃`},{french:`Il / Elle est blessé(e)`,english:`He / She is injured`,pronunciation:`il / ɛl ɛ blɛse`},{french:`Je saigne`,english:`I'm bleeding`,pronunciation:`ʒə sɛɲ`,funnyNote:`You should probably know this one.`},{french:`Je ne peux pas bouger`,english:`I can't move`,pronunciation:`ʒə nə pø pa buʒe`},{french:`Je suis diabétique / épileptique`,english:`I'm diabetic / epileptic`,pronunciation:`ʒə sɥi djabetik / epilɛptik`,funnyNote:`Give this information to emergency responders immediately. Also: asthmatique (asthmatic).`},{french:`Où est l'urgence la plus proche ?`,english:`Where is the nearest emergency room?`,pronunciation:`u ɛ lyʁʒɑ̃s la ply pʁɔʃ`},{french:`C'est urgent`,english:`It's urgent`,pronunciation:`sɛ tyʁʒɑ̃`},{french:`J'ai perdu connaissance`,english:`I lost consciousness`,pronunciation:`ʒɛ pɛʁdy kɔnɛsɑ̃s`}],exercises:[{type:`multiple-choice`,prompt:`What number do you call for an ambulance (SAMU) in France?`,answer:`15`,options:[`15`,`911`,`999`,`17`]},{type:`translation`,prompt:`Shout "Help! Call an ambulance!"`,answer:`Au secours ! Appelez le SAMU !`,hint:`"Au secours" = Help, "Appelez le SAMU" = Call an ambulance`},{type:`fill-blank`,prompt:`"Je ___ pas bouger" (I can't move)`,answer:`ne peux`,hint:`Negation: ne...pas wraps around the verb "peux" (can)`},{type:`multiple-choice`,prompt:`Someone is injured. What do you say to the emergency operator?`,answer:`Il est blessé`,options:[`Il est blessé`,`Il est très fatigué`,`Il a mangé quelque chose`,`Il dort profondément`]},{type:`translation`,prompt:`Say "I'm bleeding and it's urgent"`,answer:`Je saigne et c'est urgent`,hint:`"Je saigne" + "et" (and) + "c'est urgent"`},{type:`multiple-choice`,prompt:`"J'ai perdu connaissance" means:`,answer:`I lost consciousness`,options:[`I lost my bag`,`I lost consciousness`,`I can't remember`,`I lost my phone`]}]}],isA1:!0,isBeyondA1:!1},{id:`smalltalk`,slug:`smalltalk`,title:`Weather & Vibes`,emoji:`☀️`,tagline:`Small Talk & Opinions`,funnyDescription:`Talking about weather is a universal language. Even the French respect this. Express emotions, compliments, and strong opinions about croissants.`,color:`#F4A261`,accentColor:`#f7b87a`,lessons:[{id:`smalltalk-1`,title:`Weather: The Universal Icebreaker`,subtitle:`Talking about weather transcends all cultural barriers. Even the French respect this.`,xpReward:20,vocab:[{french:`Il fait beau`,english:`The weather is nice / It's nice out`,pronunciation:`il fɛ bo`,funnyNote:`Say this on a gray Paris day and watch the French nod politely while internally disagreeing.`},{french:`Il fait mauvais`,english:`The weather is bad`,pronunciation:`il fɛ movɛ`},{french:`Il pleut`,english:`It's raining`,pronunciation:`il plø`},{french:`Il fait chaud / froid`,english:`It's hot / cold`,pronunciation:`il fɛ ʃo / fʁwa`,funnyNote:`France has actual seasons. "Il fait chaud" in August in Paris — you'll need this.`},{french:`Il neige`,english:`It's snowing`,pronunciation:`il nɛʒ`}],exercises:[{type:`multiple-choice`,prompt:`It's a beautiful sunny day. What do you say?`,answer:`Il fait beau !`,options:[`Il fait mauvais`,`Il fait beau !`,`Il pleut`,`Il fait froid`]},{type:`translation`,prompt:`How do you say "It's cold"?`,answer:`Il fait froid`,hint:`"Il fait" + the temperature adjective`}]},{id:`smalltalk-2`,title:`Opinions, Emotions & Compliments`,subtitle:`Express yourself. Poorly but enthusiastically.`,xpReward:20,vocab:[{french:`C'est magnifique !`,english:`It's magnificent!`,pronunciation:`sɛ maɲifik`,funnyNote:`Use this freely. The Eiffel Tower. A really good croissant. A sunset. All magnifique.`},{french:`C'est incroyable !`,english:`It's incredible!`,pronunciation:`sɛ tɛ̃kʁwajabl`},{french:`Je suis fatigué(e)`,english:`I'm tired`,pronunciation:`ʒə sɥi fatiɡe`,funnyNote:`The universal state of a tourist.`},{french:`Je suis content(e)`,english:`I'm happy`,pronunciation:`ʒə sɥi kɔ̃tɑ̃`,funnyNote:`"Content" in French means happy/satisfied — NOT the English "content" (which would be "contenu").`},{french:`Vous êtes très sympa`,english:`You're very kind/nice`,pronunciation:`vu zɛt tʁɛ sɛ̃pa`,funnyNote:`"Sympa" (short for sympathique) is the French word for "nice person". A powerful compliment.`},{french:`J'adore ça !`,english:`I love that!`,pronunciation:`ʒadɔʁ sa`},{french:`Je n'aime pas trop ça`,english:`I don't really like that`,pronunciation:`ʒə nɛm pa tʁo sa`,funnyNote:`The polite French way of saying something is terrible.`}],exercises:[{type:`multiple-choice`,prompt:`Your host is very kind. What do you say?`,answer:`Vous êtes très sympa`,options:[`Vous êtes très bon`,`Vous êtes très sympa`,`Merci pour ça`,`Très bien vous`]},{type:`translation`,prompt:`How do you say "I'm tired"?`,answer:`Je suis fatigué`,hint:`Use "Je suis" + the adjective. Mind the accents.`},{type:`fill-blank`,prompt:`"C'est ___ !" (It's magnificent!)`,answer:`magnifique`,hint:`The French cognate of "magnificent"`}]}],isA1:!0,isBeyondA1:!1},{id:`identity`,slug:`identity`,title:`Who Even Are You?`,emoji:`🙋`,tagline:`Nationality, Profession & Family`,funnyDescription:`You've survived the basics. Now someone asks where you're from, what you do, and whether you have kids — all in French. Learn to answer without accidentally claiming to be a country.`,color:`#8B5CF6`,accentColor:`#a78bfa`,lessons:[{id:`identity-1`,title:`Where Are You From?`,subtitle:`Talk about your origins without accidentally claiming to be a country.`,xpReward:20,vocab:[{french:`Je viens de...`,english:`I come from...`,pronunciation:`ʒə vjɛ̃ də`,example:`Je viens des États-Unis.`,exampleTranslation:`I come from the United States.`},{french:`J'habite à...`,english:`I live in...`,pronunciation:`ʒabit a`,example:`J'habite à Londres.`,exampleTranslation:`I live in London.`},{french:`Je suis américain(e)`,english:`I am American`,pronunciation:`ʒə sɥi zameʁikɛ̃ / ameʁikɛn`,funnyNote:`Add -e for feminine. Nationalities are NOT capitalized in French. You're "américain", not "Américain". Same for all nationalities.`},{french:`anglais(e) / australien(ne)`,english:`English / Australian`,pronunciation:`ɑ̃ɡlɛ / ostʁalijɛ̃`,funnyNote:`Feminine forms can change dramatically: australien → australienne.`},{french:`Je parle anglais / français`,english:`I speak English / French`,pronunciation:`ʒə paʁl ɑ̃ɡlɛ / fʁɑ̃sɛ`,funnyNote:`Languages are NOT capitalized either: "le français", "l'anglais". Only country names get capitals.`},{french:`Je parle un peu de français`,english:`I speak a little French`,pronunciation:`ʒə paʁl œ̃ pø də fʁɑ̃sɛ`,funnyNote:`Your new best phrase. Even a terrible attempt earns enormous goodwill from French people.`}],exercises:[{type:`translation`,prompt:`How do you say "I come from Australia"?`,answer:`Je viens d'Australie`,hint:`de + Australie → d'Australie (elision before vowel)`},{type:`multiple-choice`,prompt:`How do you say "I speak a little French"?`,answer:`Je parle un peu de français`,options:[`Je parle le petit français`,`Je parle un peu de français`,`Je suis parlant français`,`Je parle français un peu`]},{type:`fill-blank`,prompt:`J'___ à Paris. (I live in Paris)`,answer:`habite`,hint:`habiter → first person singular`}]},{id:`identity-2`,title:`What Do You Do?`,subtitle:`Professions, studies, and why you drop the article after être.`,xpReward:20,vocab:[{french:`Je suis étudiant(e)`,english:`I am a student`,pronunciation:`ʒə sɥi etydijɑ̃`,funnyNote:`Notice: no article before the profession. In French, "Je suis professeur" not "Je suis UN professeur". The article disappears after être when stating a profession.`},{french:`Je suis professeur`,english:`I am a teacher`,pronunciation:`ʒə sɥi pʁofesœʁ`},{french:`Je suis médecin`,english:`I am a doctor`,pronunciation:`ʒə sɥi medsɛ̃`},{french:`Je suis infirmier / infirmière`,english:`I am a nurse (m/f)`,pronunciation:`ʒə sɥi ɛ̃fiʁmje / ɛ̃fiʁmjɛʁ`},{french:`Je travaille dans...`,english:`I work in...`,pronunciation:`ʒə tʁavaj dɑ̃`,example:`Je travaille dans la finance.`,exampleTranslation:`I work in finance.`},{french:`Qu'est-ce que vous faites ?`,english:`What do you do? (formal)`,pronunciation:`kɛskə vu fɛt`,funnyNote:`Literally "what is it that you do?" — the go-to conversation opener at a dinner party or professional event.`},{french:`Je suis à la retraite`,english:`I am retired`,pronunciation:`ʒə sɥi a la ʁətʁɛt`}],exercises:[{type:`multiple-choice`,prompt:`Which is grammatically correct in French?`,answer:`Je suis médecin`,options:[`Je suis un médecin`,`Je suis médecin`,`J'ai un médecin`,`Je fais médecin`]},{type:`translation`,prompt:`How do you say "I work in technology"?`,answer:`Je travaille dans la technologie`,hint:`Je travaille dans + article + field. Mind the accents.`},{type:`fill-blank`,prompt:`Qu'est-ce que vous ___ ? (What do you do?)`,answer:`faites`,hint:`Faire conjugated for vous`}]},{id:`identity-3`,title:`Family & Relationships`,subtitle:`Talking about the people in your life without accidentally oversharing.`,xpReward:25,vocab:[{french:`la famille`,english:`the family`,pronunciation:`la famij`},{french:`mon mari / ma femme`,english:`my husband / my wife`,pronunciation:`mɔ̃ maʁi / ma fam`},{french:`mon copain / ma copine`,english:`my boyfriend / my girlfriend`,pronunciation:`mɔ̃ kɔpɛ̃ / ma kɔpin`,funnyNote:`"Copain/copine" also means friend — context usually clarifies. For unambiguous "partner" use mon compagnon / ma compagne.`},{french:`mon frère / ma sœur`,english:`my brother / my sister`,pronunciation:`mɔ̃ fʁɛʁ / ma sœʁ`},{french:`mes parents`,english:`my parents`,pronunciation:`me paʁɑ̃`,funnyNote:`"Parents" in French means parents (not all relatives — that's "famille"). "Mes parents" = my mum and dad.`},{french:`mon fils / ma fille`,english:`my son / my daughter`,pronunciation:`mɔ̃ fis / ma fij`,funnyNote:`"Fils" — the L is silent but the S is pronounced: "fis". That S surprises people every time.`},{french:`J'ai deux enfants`,english:`I have two children`,pronunciation:`ʒe dø zɑ̃fɑ̃`,funnyNote:`Note the liaison: "deux enfants" → dø-z-ɑ̃fɑ̃. The S from "deux" carries over.`},{french:`Je suis célibataire`,english:`I am single`,pronunciation:`ʒə sɥi selibatɛʁ`,funnyNote:`A magnificent word. Six syllables. No English equivalent is this elegant.`}],exercises:[{type:`multiple-choice`,prompt:`How do you say "my sister"?`,answer:`ma sœur`,options:[`mon sœur`,`ma sœur`,`le sœur`,`mes sœurs`]},{type:`translation`,prompt:`How do you say "I have two children"?`,answer:`J'ai deux enfants`,hint:`Remember the liaison between deux and enfants`},{type:`fill-blank`,prompt:`Mon ___ s'appelle Thomas. (My son's name is Thomas)`,answer:`fils`,hint:`The L is silent, but the S is pronounced`}]}],isA1:!1,isA1A2:!0,isBeyondA1:!1},{id:`weather`,slug:`weather`,title:`The Forecast for Awkward Silence`,emoji:`🌦️`,tagline:`Weather & Seasons`,funnyDescription:`Weather is the universal small-talk opener in every culture — and the French have particularly strong opinions about theirs. "Il fait beau" is not just an observation; it's an invitation.`,color:`#0EA5E9`,accentColor:`#38bdf8`,lessons:[{id:`weather-1`,title:`Il Fait Beau — Or Does It?`,subtitle:`Weather is the universal French small-talk opener. Master it first.`,xpReward:20,vocab:[{french:`Il fait beau`,english:`The weather is nice`,pronunciation:`il fɛ bo`,funnyNote:`Literally "it makes beautiful". French weather uses "faire" not "être". Never say "il est beau" about the weather — that means someone is handsome.`},{french:`Il fait mauvais`,english:`The weather is bad`,pronunciation:`il fɛ movɛ`},{french:`Il fait chaud`,english:`It's hot`,pronunciation:`il fɛ ʃo`},{french:`Il fait froid`,english:`It's cold`,pronunciation:`il fɛ fʁwa`},{french:`Il pleut`,english:`It's raining`,pronunciation:`il plø`,funnyNote:`"Pleuvoir" is conjugated in the third person only. It just "il pleut". That's it. The verb exists for no other subject.`},{french:`Il neige`,english:`It's snowing`,pronunciation:`il nɛʒ`},{french:`Il y a du vent`,english:`It's windy`,pronunciation:`il ja dy vɑ̃`,funnyNote:`"Il y a" = there is/are. "Du soleil" = sunshine. "Du brouillard" = fog. All follow the same pattern.`},{french:`Quel temps fait-il ?`,english:`What's the weather like?`,pronunciation:`kɛl tɑ̃ fɛ til`,funnyNote:`"Temps" means both "weather" AND "time" in French. Context distinguishes them. Quel temps = what weather. Combien de temps = how much time.`}],exercises:[{type:`translation`,prompt:`How do you say "It's raining"?`,answer:`Il pleut`,hint:`Pleuvoir only conjugates in third person singular`},{type:`multiple-choice`,prompt:`"Il fait chaud" means?`,answer:`It's hot`,options:[`It's cold`,`It's nice`,`It's hot`,`It's windy`]},{type:`fill-blank`,prompt:`Il y a du ___ (It's windy)`,answer:`vent`,hint:`"Du vent" = some wind`}]},{id:`weather-2`,title:`Seasons, Forecasts & French Complaints`,subtitle:`The French have opinions about weather. Many. Loudly expressed.`,xpReward:20,vocab:[{french:`le printemps`,english:`spring`,pronunciation:`lə pʁɛ̃tɑ̃`,funnyNote:`French spring is genuinely beautiful. Even Parisians become briefly pleasant.`},{french:`l'été`,english:`summer`,pronunciation:`lete`,funnyNote:`Paris in August: everyone leaves. July–August is "les grandes vacances". Entire offices close. Plan accordingly.`},{french:`l'automne`,english:`autumn / fall`,pronunciation:`lotɔn`},{french:`l'hiver`,english:`winter`,pronunciation:`livɛʁ`},{french:`au printemps / en été / en automne / en hiver`,english:`in spring / in summer / in autumn / in winter`,pronunciation:`o pʁɛ̃tɑ̃ / ɑ̃ ete / ɑ̃ otɔn / ɑ̃ nivɛʁ`,funnyNote:`Use "au" before printemps (masculine). Use "en" before the other three. "En hiver" has a liaison: ɑ̃-nivɛʁ.`},{french:`la météo`,english:`the weather forecast`,pronunciation:`la meteo`},{french:`Il fait combien de degrés ?`,english:`What's the temperature?`,pronunciation:`il fɛ kɔ̃bjɛ̃ də dəɡʁe`,funnyNote:`France uses Celsius. 20°C = pleasant. 30°C = borderline canicule. 38°C = everyone complains to the government.`},{french:`une canicule`,english:`a heatwave`,pronunciation:`yn kanikyl`,funnyNote:`The French take canicules seriously after the catastrophic 2003 heatwave. Rightfully so.`}],exercises:[{type:`multiple-choice`,prompt:`How do you say "in spring"?`,answer:`au printemps`,options:[`en printemps`,`au printemps`,`à le printemps`,`dans printemps`]},{type:`translation`,prompt:`What is "la météo"?`,answer:`The weather forecast`,hint:`Short for météorologie`},{type:`multiple-choice`,prompt:`"En été" means?`,answer:`In summer`,options:[`In autumn`,`In winter`,`In spring`,`In summer`]}]}],isA1:!1,isA1A2:!0,isBeyondA1:!1},{id:`plans`,slug:`plans`,title:`Actually Doing Things`,emoji:`📅`,tagline:`Time, Plans & Reservations`,funnyDescription:`Telling the time in French requires more precision than you'd think. Making a rendez-vous is a social contract. Booking a restaurant table involves real stakes. Let's sort all of this out.`,color:`#F59E0B`,accentColor:`#fbbf24`,lessons:[{id:`plans-1`,title:`Telling the Time`,subtitle:`France uses a 24-hour clock. Your phone helps. Learn it anyway.`,xpReward:20,vocab:[{french:`Quelle heure est-il ?`,english:`What time is it?`,pronunciation:`kɛl œʁ ɛ til`},{french:`Il est deux heures`,english:`It's two o'clock`,pronunciation:`il ɛ dø zœʁ`,funnyNote:`Note the liaison: "deux heures" → dø-z-œʁ. Always use "heures" (plural) except for midi and minuit.`},{french:`Il est midi / minuit`,english:`It's noon / midnight`,pronunciation:`il ɛ midi / minɥi`,funnyNote:`"Midi" and "minuit" are singular — never say "midi heures". It's just "il est midi".`},{french:`et quart / et demie`,english:`quarter past / half past`,pronunciation:`e kaʁ / e dəmi`,example:`Il est trois heures et quart.`,exampleTranslation:`It's quarter past three.`},{french:`moins le quart`,english:`quarter to`,pronunciation:`mwɛ̃ lə kaʁ`,example:`Il est cinq heures moins le quart.`,exampleTranslation:`It's quarter to five (= 4:45).`},{french:`du matin / de l'après-midi / du soir`,english:`in the morning / afternoon / evening`,pronunciation:`dy matɛ̃ / də lapʁɛmidi / dy swaʁ`,funnyNote:`Formal French uses 24h: 14h00 = quatorze heures. Informal speech adds matin/après-midi/soir to clarify.`}],exercises:[{type:`multiple-choice`,prompt:`"Il est trois heures et demie" means?`,answer:`It's half past three`,options:[`It's quarter past three`,`It's three o'clock`,`It's half past three`,`It's quarter to three`]},{type:`translation`,prompt:`How do you ask "What time is it?"`,answer:`Quelle heure est-il ?`,hint:`Quelle = which/what, heure = hour`},{type:`fill-blank`,prompt:`Il est midi et ___ (It's half past noon)`,answer:`demie`,hint:`Half = demie`}]},{id:`plans-2`,title:`Making Plans & Appointments`,subtitle:`The rendez-vous is sacred in France. Don't be late. Don't cancel last-minute.`,xpReward:25,vocab:[{french:`un rendez-vous`,english:`an appointment / a meeting`,pronunciation:`œ̃ ʁɑ̃devu`,funnyNote:`Literally "present yourselves". Covers everything from a doctor's appointment to a date — the same word for all.`},{french:`Je suis libre à...`,english:`I'm free at...`,pronunciation:`ʒə sɥi libʁ a`,example:`Je suis libre à 18h.`,exampleTranslation:`I'm free at 6pm.`},{french:`Je suis occupé(e)`,english:`I'm busy`,pronunciation:`ʒə sɥi okype`},{french:`On se retrouve où ?`,english:`Where shall we meet?`,pronunciation:`ɔ̃ sə ʁətʁuv u`},{french:`Ça vous convient ?`,english:`Does that work for you? (formal)`,pronunciation:`sa vu kɔ̃vjɛ̃`,funnyNote:`The polished way to confirm a meeting time. Very common in professional emails and calls.`},{french:`La semaine prochaine`,english:`Next week`,pronunciation:`la səmɛn pʁɔʃɛn`},{french:`Ce soir / cet après-midi`,english:`Tonight / this afternoon`,pronunciation:`sə swaʁ / sɛt apʁɛmidi`,funnyNote:`"Ce" becomes "cet" before a vowel sound: cet après-midi, cet hiver.`}],exercises:[{type:`translation`,prompt:`How do you say "I'm busy tomorrow"?`,answer:`Je suis occupé(e) demain`,hint:`Occupé(e) + demain (tomorrow). Mind the accents.`},{type:`multiple-choice`,prompt:`What does "un rendez-vous" cover?`,answer:`Any appointment or meeting`,options:[`Only romantic dates`,`Only doctor's appointments`,`Any appointment or meeting`,`Only business meetings`]},{type:`fill-blank`,prompt:`On se ___ où ? (Where shall we meet?)`,answer:`retrouve`,hint:`Se retrouver = to meet up`}]},{id:`plans-3`,title:`Reservations & Bookings`,subtitle:`"Je voudrais réserver" — four words that open many doors in France.`,xpReward:25,vocab:[{french:`Je voudrais réserver...`,english:`I'd like to book...`,pronunciation:`ʒə vudʁɛ ʁezɛʁve`,funnyNote:`"Voudrais" is the conditional of vouloir — polite and indispensable. More polite than "je veux" (I want), which can sound blunt or demanding.`},{french:`une table pour deux`,english:`a table for two`,pronunciation:`yn tabl puʁ dø`},{french:`une chambre`,english:`a room`,pronunciation:`yn ʃɑ̃bʁ`},{french:`Pour combien de personnes ?`,english:`For how many people?`,pronunciation:`puʁ kɔ̃bjɛ̃ də pɛʁsɔn`},{french:`C'est au nom de...`,english:`It's under the name of...`,pronunciation:`sɛ o nɔ̃ də`,funnyNote:`The phrase for giving your booking name at a restaurant or hotel. More common than saying your name unprompted.`},{french:`Annuler / confirmer la réservation`,english:`To cancel / confirm the reservation`,pronunciation:`anyle / kɔ̃fiʁme la ʁezɛʁvasjɔ̃`,funnyNote:`French restaurants increasingly require cards for reservations. Cancellation policies are getting stricter.`}],exercises:[{type:`translation`,prompt:`How do you say "I'd like to book a table for two"?`,answer:`Je voudrais réserver une table pour deux`,hint:`Je voudrais réserver + une table pour + number`},{type:`multiple-choice`,prompt:`"C'est au nom de..." is used to:`,answer:`Give your name for a booking`,options:[`Ask what the name is`,`Give your name for a booking`,`Introduce yourself formally`,`Ask the price`]},{type:`fill-blank`,prompt:`Je ___ réserver une chambre. (I'd like to book a room)`,answer:`voudrais`,hint:`Conditional of vouloir`}]}],isA1:!1,isA1A2:!0,isBeyondA1:!1},{id:`vie-francaise`,slug:`vie-francaise`,title:`Vivre à la Française`,emoji:`🥂`,tagline:`The Apéro, the Market & the Art of Slowing Down`,funnyDescription:`L'apéro is not a drink, it's a philosophy. The market is not a supermarket, it's a ritual. Sitting at a café for two hours is not wasting time, it's living correctly. This unit explains all of it.`,color:`#9B2335`,accentColor:`#c44`,lessons:[{id:`vie-francaise-1`,title:`L'Apéro: France's Happiest Hour`,subtitle:`The ritual that happens before every French dinner. It is not optional.`,xpReward:25,vocab:[{french:`L'apéro / l'apéritif`,english:`Pre-dinner drinks`,pronunciation:`lapero / lapeʁitif`,funnyNote:`L'apéro is not just a drink — it's a decompression ritual. It happens between roughly 6pm and 8pm. Light snacks appear. Nobody is in a hurry. The whole concept is the opposite of happy hour.`},{french:`On prend l'apéro ?`,english:`Shall we have drinks?`,pronunciation:`ɔ̃ pʁɑ̃ lapero`,funnyNote:`This four-word phrase is a genuine social invitation. Saying yes commits you to at least an hour of pleasant conversation. Saying no is technically allowed but socially noted.`},{french:`Un kir`,english:`White wine with blackcurrant liqueur`,pronunciation:`œ̃ kiʁ`,funnyNote:`The classic French aperitif. Named after Canon Félix Kir, mayor of Dijon, who popularised it after WWII. Kir Royale = same thing with Champagne. Order one and you immediately look like you know what you're doing.`},{french:`Un pastis`,english:`Anise-flavoured aperitif, diluted with water`,pronunciation:`œ̃ pastis`,funnyNote:`The South of France in a glass. Pernod, Ricard, Pastis 51 — all pastis. You pour a measure and add cold water; it turns cloudy. Never add ice first. This matters to French people.`},{french:`Des amuse-gueules`,english:`Small snacks served with drinks`,pronunciation:`de zamyz ɡœl`,funnyNote:`Literally "mouth-amusers". Olives, crisps, small toasts, tiny tarts. Nothing elaborate — the point is to maintain the conversation, not replace dinner.`},{french:`Santé !`,english:`Cheers! (Informal)`,pronunciation:`sɑ̃te`,funnyNote:`Literally "health". When toasting, you MUST make eye contact with each person as you clink glasses. Missing someone is considered bad luck — seven years of bad luck, by some accounts. The French take this seriously.`},{french:`À votre santé !`,english:`To your health! (Formal)`,pronunciation:`a votʁ sɑ̃te`,funnyNote:`The formal version. Use with people you'd use "vous" with. In a group of strangers, "à votre santé" signals good manners.`},{french:`Cul sec !`,english:`Bottoms up! / Down in one!`,pronunciation:`ky sɛk`,funnyNote:`Literally "dry bottom". Only for among friends, and only when someone challenges you. Not a standard toast.`}],exercises:[{type:`multiple-choice`,prompt:`You're toasting at a dinner table with 5 French people. What is expected of you?`,answer:`Make eye contact with each person as you clink glasses`,options:[`Just raise your glass and say Santé`,`Make eye contact with each person as you clink glasses`,`Clink only with the person next to you`,`Wait for the host to clink with you first`]},{type:`translation`,prompt:`How do you ask a friend "Shall we have drinks?"`,answer:`On prend l'apéro ?`,hint:`On prend + l'apéro`},{type:`multiple-choice`,prompt:`A pastis turns cloudy when you add water. This is:`,answer:`Normal — it's the louche effect of anise`,options:[`A sign it's gone off`,`Normal — it's the louche effect of anise`,`Only supposed to happen with ice`,`A sign you added too much water`]}]},{id:`vie-francaise-2`,title:`Le Marché: Shopping as a Way of Life`,subtitle:`The market is not a supermarket. It is a cultural institution.`,xpReward:25,vocab:[{french:`Le marché`,english:`The market`,pronunciation:`lə maʁʃe`,funnyNote:`Every French town has a market — usually weekly, often twice weekly. The marché is where locals actually shop for food, not the supermarché. Going to the market is a ritual, not an errand.`},{french:`Le maraîcher`,english:`The market gardener / produce seller`,pronunciation:`lə maʁɛʃe`,funnyNote:`Your local produce vendor at the market. They grow what they sell, usually within 50km. Building a rapport with your maraîcher is a French life skill.`},{french:`De saison`,english:`In season`,pronunciation:`də sɛzɔ̃`,funnyNote:`The most important phrase in French food culture. "C'est de saison ?" (Is it in season?) is not a quirky question — it's the correct question. Buying strawberries in November is quietly frowned upon.`},{french:`Le terroir`,english:`The land, soil, and local character of produce`,pronunciation:`lə tɛʁwaʁ`,funnyNote:`One of the most untranslatable French words. "Terroir" means the taste of where something is from — the soil, climate, tradition of a specific place. Wine, cheese, vegetables all have terroir. It's a philosophy, not just a word.`},{french:`Un kilo de... / une livre de...`,english:`A kilo of... / half a kilo of...`,pronunciation:`œ̃ kilo də / yn livʁ də`,funnyNote:`"Une livre" is 500g in French (half a kilo). Not a pound. This is a common confusion. "Une livre de tomates" = 500g of tomatoes.`},{french:`C'est de chez qui ?`,english:`Who is it from? / Where is it from?`,pronunciation:`sɛ də ʃe ki`,funnyNote:`The question that separates the shopper from the tourist. Asking where the produce is from shows you understand that origin matters. Vendors love this question.`},{french:`Le fromager`,english:`The cheese seller`,pronunciation:`lə fʁomaʒe`,funnyNote:`A specialist who sells only cheese. At a good marché, they will let you taste before you buy, recommend something for tonight vs something for the weekend, and have opinions.`},{french:`Ne touchez pas, s'il vous plaît`,english:`Please don't touch`,pronunciation:`nə tuʃe pa sil vu plɛ`,funnyNote:`Market etiquette: you do not touch the produce yourself. You point and the vendor picks it. This is the rule. Don't be the person who squeezes every peach.`}],exercises:[{type:`multiple-choice`,prompt:`At a French market, how do you select your fruit and vegetables?`,answer:`Point at what you want — the vendor picks it for you`,options:[`Pick them up and examine them yourself`,`Point at what you want — the vendor picks it for you`,`Ask for a bag and fill it yourself`,`Choose from pre-packaged displays only`]},{type:`translation`,prompt:`Ask for "a kilo of tomatoes"`,answer:`Un kilo de tomates`,hint:`Un kilo de + the item`},{type:`multiple-choice`,prompt:`"Le terroir" refers to:`,answer:`The distinctive character a place gives to its food and wine`,options:[`Organic farming methods`,`The distinctive character a place gives to its food and wine`,`The soil type only`,`A wine classification system`]}]},{id:`vie-francaise-3`,title:`La Flânerie: The Art of Going Nowhere`,subtitle:`France is one of the few places where aimless wandering is a recognised activity.`,xpReward:25,vocab:[{french:`La flânerie`,english:`Aimless, pleasurable wandering`,pronunciation:`la flanʁi`,funnyNote:`To "flâner" is to wander without purpose — slowly, observantly, for the pleasure of it. The "flâneur" was romanticised by Baudelaire. In France, wandering around a neighbourhood for two hours is a legitimate Saturday activity, not a sign of being lost.`},{french:`Une terrasse`,english:`A café terrace`,pronunciation:`yn tɛʁas`,funnyNote:`The outdoor section of a café, usually on the pavement. In France, the terrasse is not where you sit when there's no room inside — it's where you sit by choice. The view of the street is the point.`},{french:`Je prends juste un café`,english:`I'll just have a coffee`,pronunciation:`ʒə pʁɑ̃ ʒyst œ̃ kafe`,funnyNote:`In France, ordering one coffee and sitting for 90 minutes is entirely acceptable. Nobody will hurry you. Nobody will bring the bill until you ask. A café is not a place to process customers — it's a place to be.`},{french:`Se balader`,english:`To stroll, wander around`,pronunciation:`sə balade`,funnyNote:`"On se balade ?" = Shall we go for a wander? More casual than flânerie, but the same spirit. Walking with no destination.`},{french:`Prendre le temps`,english:`To take one's time`,pronunciation:`pʁɑ̃dʁ lə tɑ̃`,funnyNote:`"Prenez le temps" — take your time — is said frequently in France and genuinely meant. Rushing is considered a sign of poor organisation, not dedication.`},{french:`Le quartier`,english:`The neighbourhood`,pronunciation:`lə kaʁtje`,funnyNote:`French people identify strongly with their quartier. A Parisian says they're from the 11th arrondissement, not from Paris. The quartier has its own market, café, baker, and character.`},{french:`Flâner dans les rues`,english:`To wander the streets`,pronunciation:`flane dɑ̃ le ʁy`,funnyNote:`The sentence that sums up an ideal French afternoon. No phone, no destination, a good coat.`}],exercises:[{type:`multiple-choice`,prompt:`You sit at a Paris café, finish your coffee, and stay talking for an hour. The waiter:`,answer:`Leaves you alone until you ask for the bill`,options:[`Asks you to order again or leave`,`Leaves you alone until you ask for the bill`,`Brings the bill after 20 minutes`,`Asks you to move to free up the table`]},{type:`translation`,prompt:`How do you say "to take one's time"?`,answer:`Prendre le temps`,hint:`Prendre = to take, le temps = time`},{type:`multiple-choice`,prompt:`"La flânerie" means:`,answer:`Aimless, pleasurable wandering`,options:[`Speed-walking for exercise`,`Aimless, pleasurable wandering`,`Window shopping without buying`,`Getting lost in a foreign city`]}]}],isA1:!1,isA1A2:!0,isBeyondA1:!1},{id:`false-friends`,slug:`false-friends`,title:`False Friends Will Betray You`,emoji:`🪤`,tagline:`Dangerous Cognates`,funnyDescription:`"Librairie" is not a library. "Actuellement" does not mean "actually". These words look English but will embarrass you in public. Learn them before they strike.`,color:`#2A9D8F`,accentColor:`#3ab5a6`,lessons:[{id:`false-friends-1`,title:`Words That Will Betray You`,subtitle:`"Librairie" is not a library. "Actuellement" is not "actually". These words are traps.`,xpReward:30,vocab:[{french:`Préservatif`,english:`Contraceptive (NOT "preservative")`,pronunciation:`pʁezɛʁvatif`,funnyNote:`"Conservateur" is the word you want for food preservatives. "Préservatif" means something very different — a common trap for English speakers.`},{french:`Blessé(e)`,english:`Injured (NOT "blessed")`,pronunciation:`blɛse`,example:`Il est blessé.`,exampleTranslation:`He is injured.`,funnyNote:`Do not say "Je suis blessé" thinking you're saying "I'm blessed". You're telling people you're hurt.`},{french:`Librairie`,english:`Bookshop (NOT "library")`,pronunciation:`libʁɛʁi`,funnyNote:`A library is "une bibliothèque". A bookshop is "une librairie". Ask for directions to a "librairie" expecting to borrow books and you'll end up buying them.`},{french:`Sensible`,english:`Sensitive (NOT "sensible")`,pronunciation:`sɑ̃sibl`,funnyNote:`Describing yourself as "très sensible" means very emotional/sensitive, not very reasonable.`},{french:`Rester`,english:`To stay (NOT "to rest")`,pronunciation:`ʁɛste`,funnyNote:`"Je veux rester ici" = I want to stay here. NOT I want to rest here. "Se reposer" means to rest.`},{french:`Attendre`,english:`To wait (NOT "to attend")`,pronunciation:`atɑ̃dʁ`,funnyNote:`"J'attends" = I'm waiting. Not "I'm attending". Very different.`},{french:`Actuellement`,english:`Currently (NOT "actually")`,pronunciation:`aktyɛlmɑ̃`,funnyNote:`"Actuellement je travaille à Paris" = Currently I work in Paris. "En fait" is "actually".`},{french:`Demander`,english:`To ask (NOT "to demand")`,pronunciation:`dəmɑ̃de`,funnyNote:`"Je demande" sounds aggressive in English but it just means "I'm asking". Breathe.`},{french:`Gentil(le)`,english:`Kind/Nice (NOT "gentle")`,pronunciation:`ʒɑ̃ti`,funnyNote:`"Il est très gentil" = He is very kind. "Doux" means gentle.`},{french:`Passer un examen`,english:`To take an exam (NOT "to pass an exam")`,pronunciation:`pase œ̃ ɛɡzamɛ̃`,funnyNote:`You've "passed" an exam in English. In French, "passer un examen" just means to sit/take it. "Réussir un examen" = to pass it.`}],exercises:[{type:`multiple-choice`,prompt:`A tourist asks a grocer for "des préservatifs" thinking it means preservatives. What do they actually mean in French?`,answer:`Contraceptives`,options:[`Food additives`,`Bandages`,`Contraceptives`,`Vitamins`]},{type:`multiple-choice`,prompt:`What does "librairie" mean?`,answer:`Bookshop`,options:[`Library`,`Bookshop`,`Book club`,`Reading room`]},{type:`multiple-choice`,prompt:`"Actuellement" means:`,answer:`Currently`,options:[`Actually`,`In actuality`,`Currently`,`In reality`]},{type:`multiple-choice`,prompt:`"Je suis blessé" means:`,answer:`I'm hurt/injured`,options:[`I'm blessed`,`I'm surprised`,`I'm hurt/injured`,`I'm offended`]},{type:`translation`,prompt:`Which French word means "to wait" (not "to attend")?`,answer:`attendre`,hint:`The deceptive cognate of "attend"`}]}],isA1:!1,isBeyondA1:!0},{id:`grammar`,slug:`grammar`,title:`Grammar Survival Kit`,emoji:`📚`,tagline:`Essential Grammar`,funnyDescription:`Every noun has a gender. Some assignments make no sense whatsoever. We don't make the rules. Survive verb conjugation, negation, and the horror of articles.`,color:`#457B9D`,accentColor:`#5a93b8`,lessons:[{id:`grammar-1`,title:`Gender: The Horror`,subtitle:`Every noun is masculine or feminine. There is no escape.`,xpReward:30,vocab:[{french:`Le / La / L'`,english:`The (masculine / feminine / before vowel)`,pronunciation:`lə / la / l`,funnyNote:`Every single noun has a gender. "Le soleil" (the sun) is masculine. "La lune" (the moon) is feminine. Many assignments seem completely random — because they are. Memorise and move on.`},{french:`Un / Une`,english:`A/An (masculine / feminine)`,pronunciation:`œ̃ / yn`,funnyNote:`"Un homme" (a man) vs "une femme" (a woman). The articles match the noun's grammatical gender, not any logical gender.`},{french:`Les`,english:`The (plural)`,pronunciation:`le`,funnyNote:`Plural for everything. "Les hommes, les femmes, les croissants." Blissfully genderless.`},{french:`Du / De la / De l'`,english:`Some (partitive article)`,pronunciation:`dy / də la / də l`,example:`Je veux du pain.`,exampleTranslation:`I want some bread.`,funnyNote:`This does not exist in English. "Give me bread" in French requires "du" (masculine) or "de la" (feminine) before the noun.`}],exercises:[{type:`multiple-choice`,prompt:`"Soleil" (sun) is masculine. What's the correct article?`,answer:`Le soleil`,options:[`La soleil`,`Le soleil`,`Les soleil`,`Un soleil`]},{type:`multiple-choice`,prompt:`The plural article "the" in French is:`,answer:`Les`,options:[`Le`,`La`,`Les`,`Des`]},{type:`fill-blank`,prompt:`"Je veux ___ pain" (I want some bread — bread is masculine)`,answer:`du`,hint:`Partitive article for masculine nouns: de + le. Mind the accents.`}]},{id:`grammar-2`,title:`Être & Avoir: The Two Most Important Verbs`,subtitle:`To be and to have. Everything in French uses one of these.`,xpReward:30,vocab:[{french:`Je suis`,english:`I am`,pronunciation:`ʒə sɥi`,example:`Je suis américain.`,exampleTranslation:`I am American.`},{french:`Tu es`,english:`You are (informal)`,pronunciation:`ty ɛ`},{french:`Il / Elle est`,english:`He / She is`,pronunciation:`il / ɛl ɛ`},{french:`Nous sommes`,english:`We are`,pronunciation:`nu sɔm`},{french:`Vous êtes`,english:`You are (formal/plural)`,pronunciation:`vu zɛt`},{french:`J'ai`,english:`I have`,pronunciation:`ʒɛ`,example:`J'ai faim.`,exampleTranslation:`I'm hungry. (lit: I have hunger)`,funnyNote:`In French you "have" hunger, not "are" hungry. You "have" cold, not "are" cold. "Avoir" does a lot of heavy lifting.`},{french:`Tu as`,english:`You have (informal)`,pronunciation:`ty a`},{french:`Il / Elle a`,english:`He / She has`,pronunciation:`il / ɛl a`}],exercises:[{type:`multiple-choice`,prompt:`How do you say "I am tired"? (fatigué = tired)`,answer:`Je suis fatigué`,options:[`J'ai fatigué`,`Je suis fatigué`,`Je fatigué`,`Moi suis fatigué`]},{type:`translation`,prompt:`Complete: "I'm hungry" (faim = hunger)`,answer:`J'ai faim`,hint:`In French you literally "have" hunger`},{type:`multiple-choice`,prompt:`"Vous êtes" means:`,answer:`You are (formal)`,options:[`We are`,`They are`,`You are (informal)`,`You are (formal)`]}]},{id:`grammar-3`,title:`Negation & Questions`,subtitle:`How to say no and ask things without sounding completely lost.`,xpReward:25,vocab:[{french:`Ne... pas`,english:`Not (negation)`,pronunciation:`nə... pa`,example:`Je ne parle pas français.`,exampleTranslation:`I don't speak French.`,funnyNote:`The verb gets sandwiched. "Je ne [verb] pas". In casual spoken French, the "ne" often disappears: "Je parle pas français." But learn the full version first.`},{french:`Est-ce que... ?`,english:`Question marker (is it that...?)`,pronunciation:`ɛskə`,example:`Est-ce que vous parlez anglais ?`,exampleTranslation:`Do you speak English?`,funnyNote:`Stick "est-ce que" in front of any sentence to make it a question. Works like magic.`},{french:`Qu'est-ce que... ?`,english:`What is it that...? / What?`,pronunciation:`kɛskə`,example:`Qu'est-ce que c'est ?`,exampleTranslation:`What is it?`},{french:`Pourquoi ?`,english:`Why?`,pronunciation:`puʁkwa`},{french:`Quand ?`,english:`When?`,pronunciation:`kɑ̃`}],exercises:[{type:`translation`,prompt:`Make this negative: "Je mange" (I eat)`,answer:`Je ne mange pas`,hint:`Sandwich the verb with "ne" and "pas"`},{type:`multiple-choice`,prompt:`How do you ask "Do you have a reservation?"`,answer:`Est-ce que vous avez une réservation ?`,options:[`Vous avez une réservation ?`,`Est-ce que vous avez une réservation ?`,`Avez vous une réservation ?`,`Question : réservation ?`]}]}],isA1:!0,isBeyondA1:!1},{id:`slang`,slug:`slang`,title:`Unlocked: The Good Stuff`,emoji:`🔥`,tagline:`Slang & Expressions`,funnyDescription:`Modern French slang, verlan (words spelled backwards), useful idioms, and things that will make French people do a double-take. You've earned this.`,color:`#6A4C93`,accentColor:`#8a6cb3`,lessons:[{id:`slang-1`,title:`Zut & Other Essentials`,subtitle:`You've earned this. Don't embarrass us.`,xpReward:35,vocab:[{french:`Zut !`,english:`Darn! / Shoot! / Rats!`,pronunciation:`zyt`,funnyNote:`The go-to French exclamation when things go wrong. "Zut, j'ai raté mon bus !" (Darn, I missed my bus!). Perfectly polite in any situation.`},{french:`C'est nul`,english:`It's no good / It's rubbish`,pronunciation:`sɛ nyl`,example:`Ce film, c'est vraiment nul.`,exampleTranslation:`This movie is really no good.`,funnyNote:`"Nul" literally means zero/null. Zero quality = nul.`},{french:`Laisse tomber`,english:`Forget it / Drop it`,pronunciation:`lɛs tɔ̃be`,funnyNote:`Literally "let it fall". Used when you're done with a topic or don't want to explain something.`},{french:`T'as l'air bien`,english:`You look good`,pronunciation:`ta lɛʁ bjɛ̃`,funnyNote:`"Avoir l'air" = to look/seem. "T'as l'air fatigué" = you look tired.`},{french:`Sympa !`,english:`Cool! / Nice!`,pronunciation:`sɛ̃pa`,funnyNote:`Short for "sympathique". One of the most versatile positives.`},{french:`C'est galère`,english:`It's a hassle / It's a struggle`,pronunciation:`sɛ ɡalɛʁ`,funnyNote:`Very common in casual French speech. "C'est la galère" = what a nightmare. Used for anything tedious or exhausting.`}],exercises:[{type:`multiple-choice`,prompt:`Someone asks why you're late. You don't want to explain. What do you say?`,answer:`Laisse tomber`,options:[`Je suis désolé`,`C'est nul`,`Laisse tomber`,`Sympa`]},{type:`multiple-choice`,prompt:`You drop your ice cream. What's the appropriate exclamation?`,answer:`Zut !`,options:[`Merci !`,`Bonjour !`,`Zut !`,`De rien`]}]},{id:`slang-2`,title:`Verlan: French Backwards Slang`,subtitle:`Young French people reverse syllables for slang. It's wild. It's real.`,xpReward:30,vocab:[{french:`Ouf`,english:`Crazy / Intense (verlan of "fou")`,pronunciation:`uf`,funnyNote:`"Fou" (crazy) backwards = "ouf". "C'est ouf !" = That's crazy! Used constantly by under-40s.`},{french:`Chelou`,english:`Sketchy / Weird (verlan of "louche")`,pronunciation:`ʃəlu`,funnyNote:`"Louche" (shady/sketchy) reversed = "chelou". "Il est chelou, ce mec" = That guy is sketchy.`},{french:`Relou`,english:`Annoying / A drag (verlan of "lourd")`,pronunciation:`ʁəlu`,funnyNote:`"Lourd" (heavy/annoying) reversed = "relou". "C'est relou" = It's such a drag.`},{french:`Meuf`,english:`Woman / Girl (verlan of "femme")`,pronunciation:`mœf`,funnyNote:`"Femme" reversed = "meuf". Standard informal French now.`},{french:`Keum`,english:`Guy / Dude (verlan of "mec")`,pronunciation:`kœm`,funnyNote:`"Mec" (guy) reversed, roughly = "keum".`}],exercises:[{type:`multiple-choice`,prompt:`"Ouf" is verlan of which word?`,answer:`Fou (crazy)`,options:[`Fort (strong)`,`Fou (crazy)`,`Fou (alternate spelling)`,`Four (oven)`]},{type:`translation`,prompt:`Your friend describes something as "chelou". What do they mean?`,answer:`sketchy or weird`,hint:`Verlan of "louche" — the shady one`}]}],isA1:!1,isBeyondA1:!0},{id:`trains`,slug:`trains`,title:`The Train Will Leave Without You`,emoji:`🚆`,tagline:`SNCF & Rail Travel`,funnyDescription:`The platform is announced 12 minutes before departure. You must stamp your ticket or pay a fine. Your carriage is at the far end. Welcome to French rail.`,color:`#E9C46A`,accentColor:`#f0d080`,lessons:[{id:`trains-1`,title:`Buying Your Ticket`,subtitle:`The machine is in French. The queue is long. You can do this.`,xpReward:25,vocab:[{french:`Un aller simple`,english:`A one-way ticket`,pronunciation:`œ̃ n‿alɛ sɛ̃pl`,funnyNote:`Aller = to go. Simple = just the one direction. Add "pour [city]" and you're basically a rail professional.`},{french:`Un aller-retour`,english:`A return ticket`,pronunciation:`œ̃ n‿alɛ ʁətuʁ`,example:`Un aller-retour pour Lyon, s'il vous plaît.`,exampleTranslation:`A return ticket to Lyon, please.`,funnyNote:`Literally "a going-return". French logic is consistent when it tries.`},{french:`Composter son billet`,english:`To validate your ticket`,pronunciation:`kɔ̃pɔste sɔ̃ bijɛ`,funnyNote:`The yellow machines at the platform entrance. You MUST stamp your ticket before boarding or face a fine. The inspector will not care about your excuses.`},{french:`Le guichet`,english:`The ticket counter`,pronunciation:`lə ɡiʃɛ`,funnyNote:`The actual human desk. Still exists! Queue here if the machine is broken (it will be).`},{french:`En quelle classe ?`,english:`Which class?`,pronunciation:`ɑ̃ kɛl klas`,funnyNote:`Première classe or deuxième classe. Second class is totally fine on French trains. Very civilised.`},{french:`Un carnet`,english:`A book of 10 metro tickets`,pronunciation:`œ̃ kaʁnɛ`,funnyNote:`Cheaper per trip than single tickets. The Navigo pass is even better for a week or more. Ask at the guichet.`}],exercises:[{type:`multiple-choice`,prompt:`You're going to Bordeaux and coming back. What do you ask for?`,answer:`Un aller-retour pour Bordeaux`,options:[`Un aller simple pour Bordeaux`,`Un aller-retour pour Bordeaux`,`Deux billets pour Bordeaux`,`Un ticket pour Bordeaux`]},{type:`fill-blank`,prompt:`Before boarding, you MUST ___ votre billet at the yellow machine.`,answer:`composter`,hint:`The verb for validating/stamping a ticket`},{type:`translation`,prompt:`How do you say "A one-way ticket to Paris, please"?`,answer:`Un aller simple pour Paris, s'il vous plaît`,hint:`Un aller simple pour [city]`}]},{id:`trains-2`,title:`Platforms & Surviving the SNCF`,subtitle:`Your train is on platform 12B. You have 4 minutes. Bon courage.`,xpReward:25,vocab:[{french:`Le quai / la voie`,english:`The platform / the track`,pronunciation:`lə kɛ / la vwa`,funnyNote:`"Voie" appears on the departure board. "Quai" is the physical platform. They're used interchangeably in conversation. Check the board — it updates late, on purpose, for sport.`},{french:`En retard / À l'heure`,english:`Late / On time`,pronunciation:`ɑ̃ ʁətaʁ / a lœʁ`,funnyNote:`"Mon train est en retard" is one of the most-used sentences in France. The SNCF is not always reliable. This is fine. Breathe.`},{french:`La voiture numéro...`,english:`Carriage number...`,pronunciation:`la vwatyʁ nymɛʁo`,funnyNote:`"Voiture" means car AND train carriage. Find the number on your ticket and look for it on the platform composition display.`},{french:`Le contrôleur`,english:`The ticket inspector`,pronunciation:`lə kɔ̃tʁolœʁ`,funnyNote:`They will find you. They always find you. Have your ticket ready — paper or phone app both work.`},{french:`La correspondance`,english:`The connection / transfer`,pronunciation:`la kɔʁɛspɔ̃dɑ̃s`,example:`J'ai une correspondance à Paris.`,exampleTranslation:`I have a connection in Paris.`,funnyNote:`Missing a correspondance is a French rite of passage.`},{french:`Le tableau des départs`,english:`The departures board`,pronunciation:`lə tablo de depaʁ`,funnyNote:`Often listed as a "Départs" screen. Yellow screens at big stations. The track is only announced 10–20 minutes before departure — this is intentional and you'll get used to it.`}],exercises:[{type:`multiple-choice`,prompt:`The departures board shows your train is "en retard". What does this mean?`,answer:`Your train is late`,options:[`Your train is cancelled`,`Your train is late`,`Your train is on time`,`Your train changed platform`]},{type:`multiple-choice`,prompt:`What is a "contrôleur" on a French train?`,answer:`The ticket inspector`,options:[`The train driver`,`The ticket machine`,`The ticket inspector`,`The station manager`]},{type:`translation`,prompt:`How do you say "I have a connection in Lyon"?`,answer:`J'ai une correspondance à Lyon`,hint:`"J'ai une correspondance à..."`}]}],isA1:!1,isBeyondA1:!0},{id:`culture`,slug:`culture`,title:`How Not to Be That Tourist`,emoji:`🫣`,tagline:`Culture & Etiquette`,funnyDescription:`Sunday closures. Two-hour lunch breaks. Mandatory bonjours. The bisou rules. Tipping norms. France has unwritten laws and you're about to learn them.`,color:`#8338EC`,accentColor:`#9a50ff`,lessons:[{id:`culture-1`,title:`The Bonjour Police`,subtitle:`Not saying it is a genuine social crime. We are not joking.`,xpReward:25,vocab:[{french:`Vous / Tu`,english:`Formal you / Informal you`,pronunciation:`vu / ty`,funnyNote:`Use "vous" with: strangers, shopkeepers, older people, your boss, anyone you just met. Use "tu" with: friends, children, colleagues who ask you to. Getting this wrong makes you seem rude OR weirdly stiff. Master it.`},{french:`Faire la bise`,english:`To do the cheek kiss greeting`,pronunciation:`fɛʁ la biz`,funnyNote:`One kiss on each cheek (in Paris). Some regions do two, three, or four. You start by leaning to YOUR left. Do not actually make lip contact with the cheek. Make a kissing sound. This is normal.`},{french:`Excusez-moi`,english:`Excuse me (formal)`,pronunciation:`ɛkskyze mwa`,funnyNote:`Use this to get someone's attention or squeeze past someone. Much more polite than just "pardon" alone.`},{french:`Je vous en prie`,english:`You're welcome (formal)`,pronunciation:`ʒə vu z‿ɑ̃ pʁi`,funnyNote:`Very formal and elegant. In everyday situations "de rien" is fine. But "je vous en prie" will make shopkeepers smile at you approvingly.`},{french:`S'il vous plaît / S'il te plaît`,english:`Please (formal / informal)`,pronunciation:`sil vu plɛ / sil tə plɛ`,funnyNote:`"S'il vous plaît" is used constantly — it's also how you get a waiter's attention. Never snap fingers or shout "garçon". Ever.`},{french:`Enchanté(e)`,english:`Delighted to meet you`,pronunciation:`ɑ̃ʃɑ̃te`,funnyNote:`Said when being introduced to someone. Sounds incredibly sophisticated. Add the "(e)" if you're a woman. It's pronounced the same but it matters in writing.`}],exercises:[{type:`multiple-choice`,prompt:`You meet your friend's grandmother for the first time. Which form do you use?`,answer:`Vous — she's a stranger and older`,options:[`Tu — it feels friendlier`,`Vous — she's a stranger and older`,`Either is fine in modern France`,`Neither — just nod`]},{type:`fill-blank`,prompt:`You enter a boulangerie. The first word out of your mouth must be "___".`,answer:`Bonjour`,hint:`The sacred greeting`},{type:`multiple-choice`,prompt:`"La bise" is a French greeting that involves:`,answer:`Leaning in for cheek-to-cheek contact with a kissing sound`,options:[`A firm handshake`,`Leaning in for cheek-to-cheek contact with a kissing sound`,`A bow of the head`,`A hug and a pat on the back`]}]},{id:`culture-2`,title:`France: The Manual`,subtitle:`Why is everything closed? When do you tip? Why is lunch two hours?`,xpReward:25,vocab:[{french:`Fermé le dimanche`,english:`Closed on Sunday`,pronunciation:`fɛʁme lə dimɑ̃ʃ`,funnyNote:`Most French shops — including many supermarkets — close on Sunday. Pharmacies take turns being on duty. Plan ahead. Sunday in France is sacred.`},{french:`La pause déjeuner`,english:`The lunch break`,pronunciation:`la poz deʒœne`,funnyNote:`From roughly 12:00 to 14:00, many small shops close for lunch. Even in 2024. This is not laziness — it's civilisation.`},{french:`Le service est compris`,english:`Service is included`,pronunciation:`lə sɛʁvis ɛ kɔ̃pʁi`,funnyNote:`You will see this at the bottom of every restaurant bill. It means the tip is built in. Leaving extra is appreciated but not expected. Do not tip 20%.`},{french:`Un jour férié`,english:`A public holiday`,pronunciation:`œ̃ ʒuʁ feʁje`,funnyNote:`France has 11 public holidays. They all fall on Tuesdays and Thursdays. The French "make a bridge" (faire le pont) — bridging to the weekend — giving them a four-day weekend. This is genius.`},{french:`Payer par carte`,english:`To pay by card`,pronunciation:`peje paʁ kaʁt`,example:`Je peux payer par carte ?`,exampleTranslation:`Can I pay by card?`,funnyNote:`Most places accept card. Some small markets or boulangeries are cash only. Always ask: "Vous acceptez la carte ?"`},{french:`La monnaie`,english:`Change / Coins`,pronunciation:`la mɔnɛ`,funnyNote:`"Avez-vous de la monnaie ?" = Do you have change? French cashiers will ask you for exact change with the energy of someone defusing a bomb. Try to comply.`}],exercises:[{type:`multiple-choice`,prompt:`It's 13:00 on a Tuesday. The pharmacy is closed. The most likely reason is:`,answer:`La pause déjeuner — they close for lunch`,options:[`It's a public holiday`,`La pause déjeuner — they close for lunch`,`They close early on Tuesdays`,`They are permanently closed`]},{type:`multiple-choice`,prompt:`Your restaurant bill says "service compris". Do you need to leave an extra tip?`,answer:`No — it's already included in the bill`,options:[`Yes — always tip 15%`,`No — it's already included in the bill`,`Yes — service compris means the food only`,`Tipping is illegal in France`]},{type:`fill-blank`,prompt:`"Je peux payer par ___ ?" (Can I pay by card?)`,answer:`carte`,hint:`The word for card`}]},{id:`culture-3`,title:`The French Meal: A 4-Act Play`,subtitle:`Entrée, plat, fromage, dessert. In that order. Always.`,xpReward:25,vocab:[{french:`L'entrée`,english:`The starter`,pronunciation:`lɑ̃tʁe`,funnyNote:`WARNING: "entrée" in France means the STARTER, not the main course. This is the opposite of American usage and has caused many ruined dinners.`},{french:`Le plat (principal)`,english:`The main course`,pronunciation:`lə pla pʁɛ̃sipal`,funnyNote:`The main event. In a proper French meal this arrives after the starter and before the cheese. Not before or during. There is an order.`},{french:`Le fromage`,english:`The cheese course`,pronunciation:`lə fʁomaʒ`,funnyNote:`Cheese comes BEFORE dessert in France. This surprises almost everyone. It's not negotiable. The cheese course is a palate bridge between savoury and sweet.`},{french:`Le dessert`,english:`Dessert`,pronunciation:`lə desɛʁ`,funnyNote:`Comes last. If someone serves cheese after dessert, a small part of France weeps.`},{french:`Le digestif`,english:`The after-dinner drink`,pronunciation:`lə diʒɛstif`,funnyNote:`Cognac, Armagnac, Calvados, Chartreuse. The French believe a small shot of something strong helps digestion. Science is uncertain. The tradition is not.`},{french:`Bon appétit !`,english:`Enjoy your meal!`,pronunciation:`bɔn apeti`,funnyNote:`Said by the host or whoever serves the food, before everyone begins eating. Do not start eating before the host says it. This is not a suggestion.`},{french:`C'est convivial`,english:`It's warm and sociable`,pronunciation:`sɛ kɔ̃vivjal`,funnyNote:`"Convivial" in French doesn't mean slightly jolly — it means genuinely warm, social, and life-affirming. The French apply this word to good meals, good company, and any gathering worth attending.`}],exercises:[{type:`multiple-choice`,prompt:`In a French meal, what comes after the plat (main course) and BEFORE dessert?`,answer:`Le fromage`,options:[`Le pain`,`Le café`,`Le fromage`,`L'entrée`]},{type:`multiple-choice`,prompt:`"L'entrée" in French means:`,answer:`The starter`,options:[`The main course`,`The entrance`,`The starter`,`The dessert`]},{type:`translation`,prompt:`What do you say before everyone starts eating?`,answer:`Bon appétit !`,hint:`The host always says this first`}]}],isA1:!1,isBeyondA1:!0},{id:`cinema`,slug:`cinema`,title:`Culture Vulture`,emoji:`🎬`,tagline:`Cinema, Museums & Leisure`,funnyDescription:`VO vs VF. The Louvre queue. Audioguides. Temporary exhibitions. Free first Sundays. France is relentlessly cultural and you might as well lean into it.`,color:`#FB5607`,accentColor:`#ff6f1f`,lessons:[{id:`cinema-1`,title:`At the Cinema`,subtitle:`VO or VF? Get this wrong and you'll watch Avengers dubbed into French.`,xpReward:25,vocab:[{french:`La version originale (VO)`,english:`Original language version (with French subtitles)`,pronunciation:`la vɛʁsjɔ̃ ɔʁiʒinal`,funnyNote:`Always look for "VO" or "VOST" (version originale sous-titrée). If you want to watch an English film in English, this is what you want. "VF" is dubbed — avoid if you value your sanity.`},{french:`La version française (VF)`,english:`French-dubbed version`,pronunciation:`la vɛʁsjɔ̃ fʁɑ̃sɛz`,funnyNote:`The French are world champions of dubbing. The voices are actually good. But if you're watching an English film to relax, VF will mess with your brain.`},{french:`Une séance`,english:`A screening / showing`,pronunciation:`yn seɑ̃s`,example:`À quelle heure est la prochaine séance ?`,exampleTranslation:`What time is the next showing?`,funnyNote:`Also means a session at a doctor's. Context will usually save you.`},{french:`Deux places, s'il vous plaît`,english:`Two seats/tickets, please`,pronunciation:`dø plas sil vu plɛ`,funnyNote:`"Une place" = one ticket. Not "un billet" in this context — a cinema ticket is "une place" (a place/seat).`},{french:`Les sous-titres`,english:`Subtitles`,pronunciation:`le su titʁ`,funnyNote:`Subtitle-friendly cinemas are marked "VOST". French cinemas in large cities reliably carry VO screenings. Small towns: bring your dubbed-French tolerance.`},{french:`La salle`,english:`The screen room / auditorium`,pronunciation:`la sal`,funnyNote:`"Salle 3" = Screen 3. You'll see this on your ticket. In France, seats are usually allocated — check your place number.`}],exercises:[{type:`multiple-choice`,prompt:`You want to watch a film in its original English with French subtitles. You ask for:`,answer:`La version originale (VO)`,options:[`La version française (VF)`,`La version originale (VO)`,`La version sous-titrée (VS)`,`La séance anglaise`]},{type:`fill-blank`,prompt:`"À quelle heure est la prochaine ___ ?" (What time is the next showing?)`,answer:`séance`,hint:`The word for a cinema screening`},{type:`translation`,prompt:`How do you ask for two tickets?`,answer:`Deux places, s'il vous plaît`,hint:`In cinemas, a ticket is called "une place"`}]},{id:`cinema-2`,title:`Museums & Culture`,subtitle:`The Louvre queue is 3 hours. The audioguide is 5 euros. C'est la vie.`,xpReward:25,vocab:[{french:`L'entrée`,english:`Entry / Admission / The entrance`,pronunciation:`lɑ̃tʁe`,example:`C'est combien l'entrée ?`,exampleTranslation:`How much is admission?`,funnyNote:`Both the physical entrance door AND the ticket/admission price. Context dependent but you'll figure it out.`},{french:`Gratuit / Payant`,english:`Free / Paid entry`,pronunciation:`ɡʁatɥi / pɛjɑ̃`,funnyNote:`Many French national museums are free for under-26s (EU residents). The first Sunday of the month is often free. Always check — you may not need to pay.`},{french:`Un audioguide`,english:`An audioguide`,pronunciation:`œ̃ n‿odjogid`,funnyNote:`Usually €5–8. Available in English. Worth it for the Louvre, Musée d'Orsay, and Versailles. Wear the headphones confidently like you own the place.`},{french:`La file d'attente`,english:`The queue / the waiting line`,pronunciation:`la fil d‿atɑ̃t`,funnyNote:`"Il y a une grande file d'attente" = there is a long queue. Book online to skip it. Seriously. Book online.`},{french:`Interdit de toucher`,english:`Do not touch`,pronunciation:`ɛ̃tɛʁdi də tuʃe`,funnyNote:`You'll see this everywhere. "Interdit de photographier" = no photos. Some rooms allow photos without flash. When in doubt, watch what the French visitors do — they ignore all rules, which means it's fine.`},{french:`L'exposition temporaire`,english:`The temporary exhibition`,pronunciation:`lɛkspozisijɔ̃ tɑ̃pɔʁɛʁ`,funnyNote:`Often requires a separate ticket on top of the museum entry. Always worth checking — French temp exhibitions are genuinely world-class.`}],exercises:[{type:`multiple-choice`,prompt:`The museum sign says "Entrée gratuite". What does this mean?`,answer:`Free entry`,options:[`Entry by reservation only`,`Free entry`,`Pay at the door`,`Closed for renovation`]},{type:`fill-blank`,prompt:`"Je voudrais un ___" (I would like an audioguide)`,answer:`audioguide`,hint:`The same word in French and English`},{type:`translation`,prompt:`How do you say "There is a long queue"?`,answer:`Il y a une grande file d'attente`,hint:`"Il y a" = there is, "grande" = long/big`}]}],isA1:!1,isBeyondA1:!0},{id:`connectors`,slug:`connectors`,title:`Mais, Donc, Pourtant`,emoji:`🔗`,tagline:`Connectors & Linking Words`,funnyDescription:`Right now you speak French like a telegram. Stop. Connectors turn five short sentences into one that sounds like a person. Stop.`,color:`#0EA5E9`,accentColor:`#38bdf8`,lessons:[{id:`connectors-1`,title:`Parce Que vs Car vs Comme`,subtitle:`Three ways to say "because" that are not interchangeable, sorry.`,xpReward:30,vocab:[{french:`parce que`,english:`because`,pronunciation:`paʁs kə`,example:`Je reste à la maison parce qu'il pleut.`,exampleTranslation:`I'm staying home because it's raining.`},{french:`car`,english:`for / because (formal, written)`,pronunciation:`kaʁ`,example:`Il n'est pas venu, car il était malade.`,exampleTranslation:`He didn't come, for he was ill.`,funnyNote:`Car never opens a sentence — it links two clauses and lives mostly in writing and careful speech. Never start a sentence with "Car..."; that job belongs to parce que.`},{french:`comme`,english:`as / since (cause, sentence-initial)`,pronunciation:`kɔm`,example:`Comme il pleuvait, on est restés à la maison.`,exampleTranslation:`Since it was raining, we stayed home.`,funnyNote:`This "comme" always opens the sentence and puts the cause before the result — the mirror image of parce que, which usually follows the result instead of leading it.`},{french:`puisque`,english:`since / given that`,pronunciation:`pɥisk`,example:`Puisque tu es là, aide-moi.`,exampleTranslation:`Since you're here, help me.`,funnyNote:`Puisque treats the reason as obvious or already known to both speakers — it can land a little pointed, close to "well, seeing as...". Parce que just states new information neutrally.`},{french:`donc`,english:`so / therefore`,pronunciation:`dɔ̃k`,example:`Il pleut, donc je prends un parapluie.`,exampleTranslation:`It's raining, so I'm taking an umbrella.`},{french:`alors`,english:`so / then`,pronunciation:`alɔʁ`,example:`Tu es fatigué ? Alors repose-toi.`,exampleTranslation:`You're tired? Then rest.`,funnyNote:`Donc leans logical ("it therefore follows that..."); alors leans conversational and does double duty as "then" in a sequence. In casual speech, alors carries most of the weight.`},{french:`c'est pourquoi`,english:`that's why / that's the reason`,pronunciation:`sɛ puʁkwa`,example:`Elle a raté son train, c'est pourquoi elle est en retard.`,exampleTranslation:`She missed her train, that's why she's late.`},{french:`grâce à`,english:`thanks to`,pronunciation:`gʁɑs a`,example:`J'ai réussi grâce à toi.`,exampleTranslation:`I succeeded thanks to you.`,funnyNote:`Grâce à only introduces a helpful cause; à cause de introduces a problem. Mix them up and you'll end up thanking someone for ruining your day.`},{french:`à cause de`,english:`because of (negative or neutral cause)`,pronunciation:`a koz də`,example:`Le vol est annulé à cause de la grève.`,exampleTranslation:`The flight is cancelled because of the strike.`}],exercises:[{type:`multiple-choice`,prompt:`Which connector can never begin a sentence?`,answer:`car`,options:[`parce que`,`car`,`comme`,`puisque`]},{type:`fill-blank`,prompt:`J'ai réussi mon examen ___ mes efforts. (thanks to my efforts)`,answer:`grâce à`,hint:`Positive cause = grâce à. Mind the accents.`},{type:`translation`,prompt:`How do you say "It's raining, so I'm staying home"? (Use donc)`,answer:`Il pleut, donc je reste à la maison.`,hint:`donc = so / therefore. Mind the accents (à).`},{type:`fill-blank`,prompt:`Le magasin est fermé ___ la grève. (because of the strike)`,answer:`à cause de`,hint:`Negative or neutral cause = à cause de. Mind the accents.`},{type:`multiple-choice`,prompt:`Which cause-connector is the one that must open the sentence (cause first, result second)?`,answer:`comme`,options:[`parce que`,`car`,`comme`,`donc`]},{type:`translation`,prompt:`How do you say "I succeeded thanks to you"? (Use grâce à)`,answer:`J'ai réussi grâce à toi.`,hint:`grâce à + person. Mind the accents.`}]},{id:`connectors-2`,title:`Mais Is Not Enough`,subtitle:`Six ways to contradict someone without repeating yourself.`,xpReward:30,vocab:[{french:`mais`,english:`but`,pronunciation:`mɛ`,example:`Je voudrais venir, mais je suis fatigué.`,exampleTranslation:`I'd like to come, but I'm tired.`},{french:`pourtant`,english:`yet / and yet / however`,pronunciation:`puʁtɑ̃`,example:`Il a révisé, pourtant il a échoué.`,exampleTranslation:`He studied, and yet he failed.`,funnyNote:`Pourtant signals real surprise — the result contradicts what you'd logically expect. It hits harder than mais, and its favorite spot is right at the front of the contrasting clause.`},{french:`cependant`,english:`however / nevertheless`,pronunciation:`səpɑ̃dɑ̃`,example:`Le prix a augmenté ; cependant, la qualité reste excellente.`,exampleTranslation:`The price has gone up; however, the quality remains excellent.`},{french:`par contre`,english:`but / on the other hand`,pronunciation:`paʁ kɔ̃tʁ`,example:`J'adore la cuisine française, par contre je déteste faire la vaisselle.`,exampleTranslation:`I love French cuisine, but I hate doing the dishes.`,funnyNote:`Purists once banned par contre from "proper" writing and pushed en revanche instead. Ignore them: par contre is completely standard in speech and in most writing today; save en revanche for very formal prose or a picky exam.`},{french:`alors que`,english:`whereas / while`,pronunciation:`alɔʁ kə`,example:`Il fait chaud à Nice, alors qu'il neige à Grenoble.`,exampleTranslation:`It's warm in Nice, whereas it's snowing in Grenoble.`},{french:`tandis que`,english:`whereas / while`,pronunciation:`tɑ̃di kə`,example:`Elle travaille le week-end, tandis que son frère se repose.`,exampleTranslation:`She works on weekends, whereas her brother rests.`},{french:`même si`,english:`even if / even though`,pronunciation:`mɛm si`,example:`Même si tu es fatigué, viens à la fête.`,exampleTranslation:`Even if you're tired, come to the party.`,funnyNote:`Big trap: même si looks hypothetical but always takes the indicative, never the subjunctive. It's "même si tu es" — never "même si tu sois".`},{french:`au lieu de`,english:`instead of (+ infinitive)`,pronunciation:`o ljø də`,example:`Il a pris le bus au lieu de marcher.`,exampleTranslation:`He took the bus instead of walking.`,funnyNote:`Au lieu de + infinitive only works when the same person does both actions. Different subjects technically need au lieu que + subjunctive, but that construction is rare and stiff — most speakers just rephrase the sentence instead.`}],exercises:[{type:`fill-blank`,prompt:`Il a pris le train ___ conduire. (instead of driving)`,answer:`au lieu de`,hint:`instead of + infinitive`},{type:`multiple-choice`,prompt:`Which sentence is grammatically correct?`,answer:`Même si tu es fatigué, viens.`,options:[`Même si tu sois fatigué, viens.`,`Même si tu es fatigué, viens.`,`Même si tu être fatigué, viens.`,`Même si tu fatigué, viens.`]},{type:`translation`,prompt:`How do you say "I love Paris, but I hate the metro"? (Use par contre)`,answer:`J'aime Paris, par contre je déteste le métro.`,hint:`par contre = but / on the other hand`},{type:`multiple-choice`,prompt:`Which statement about "par contre" is true?`,answer:`It is a common, standard way to say "but" in French today.`,options:[`It is never used in spoken French.`,`It is a common, standard way to say "but" in French today.`,`It only works in the passé composé.`,`It means "because" in formal writing.`]},{type:`fill-blank`,prompt:`___ tu es fatigué, viens à la fête. (Even if you're tired, come to the party)`,answer:`Même si`,hint:`Even if — takes the indicative, not the subjunctive`},{type:`translation`,prompt:`How do you say "She works while he rests"? (Use alors que)`,answer:`Elle travaille alors qu'il se repose.`,hint:`alors que + il = alors qu'il`}]},{id:`connectors-3`,title:`Enfin ou Finalement ?`,subtitle:`The trap that outs every intermediate learner in one word.`,xpReward:30,vocab:[{french:`d'abord`,english:`first / at first`,pronunciation:`dabɔʁ`,example:`D'abord, on va à la boulangerie.`,exampleTranslation:`First, we're going to the bakery.`},{french:`ensuite / puis`,english:`next / then`,pronunciation:`ɑ̃sɥit / pɥi`,example:`On visite le Louvre, ensuite on déjeune.`,exampleTranslation:`We visit the Louvre, then we have lunch.`,funnyNote:`Ensuite and puis both mean "then" in a sequence and are largely interchangeable. Puis also moonlights as a casual "besides": "Et puis, j'ai pas le temps" — and besides, I don't have time.`},{french:`enfin`,english:`finally / at last / well...`,pronunciation:`ɑ̃fɛ̃`,example:`Enfin, on est arrivés !`,exampleTranslation:`Finally, we arrived!`},{french:`finalement`,english:`in the end / as it turned out`,pronunciation:`finalmɑ̃`,example:`Il a hésité, mais finalement il est venu.`,exampleTranslation:`He hesitated, but in the end he came.`,funnyNote:`The classic trap: enfin closes a list or expresses relief ("at last!"); finalement reports an eventual or unexpected outcome, often after doubt. "Enfin, il est arrivé" (he finally arrived, after a long wait) vs "Finalement, il n'est pas venu" (in the end, he didn't come — a twist).`},{french:`de plus / en plus`,english:`moreover / on top of that`,pronunciation:`də plys / ɑ̃ plys`,example:`Le restaurant est excellent ; de plus, ce n'est pas cher.`,exampleTranslation:`The restaurant is excellent; moreover, it's not expensive.`,funnyNote:`De plus belongs in writing and formal speech; en plus is what people actually say out loud, and it can carry a hint of irritation — "et en plus, il est en retard" (and on top of that, he's late).`},{french:`par exemple`,english:`for example`,pronunciation:`paʁ ɛgzɑ̃pl`,example:`J'aime les sports d'hiver, par exemple le ski.`,exampleTranslation:`I like winter sports, for example skiing.`},{french:`bref`,english:`in short / anyway`,pronunciation:`bʁɛf`,example:`Bref, on a raté le train.`,exampleTranslation:`In short, we missed the train.`},{french:`en fait`,english:`actually / in fact`,pronunciation:`ɑ̃ fɛt`,example:`Je pensais qu'il était absent, en fait il était là.`,exampleTranslation:`I thought he was absent, actually he was there.`},{french:`en effet`,english:`indeed / that's right`,pronunciation:`ɑ̃n efɛ`,example:`Il fait froid aujourd'hui. — En effet, il neige même.`,exampleTranslation:`It's cold today. — Indeed, it's even snowing.`,funnyNote:`Don't confuse them: en effet confirms or agrees with something just said ("indeed, that's right"); en fait introduces a correction or a surprising truth ("actually..."). They look like siblings but are not interchangeable.`}],exercises:[{type:`translation`,prompt:`How do you say "First, we visit the museum"? (Use d'abord)`,answer:`D'abord, on visite le musée.`,hint:`d'abord = first, at the start of a sequence`},{type:`multiple-choice`,prompt:`Which word describes an unexpected or eventual outcome, often after hesitation or doubt?`,answer:`finalement`,options:[`enfin`,`finalement`,`ensuite`,`bref`]},{type:`fill-blank`,prompt:`Le film était long. ___, on s'est bien amusés. (in short)`,answer:`Bref`,hint:`the summing-up word`},{type:`multiple-choice`,prompt:`"En effet" is best used to:`,answer:`Confirm or agree with what was just said`,options:[`Introduce a surprising correction`,`Confirm or agree with what was just said`,`List items in order`,`Give an example`]},{type:`fill-blank`,prompt:`Elle a cherché ses clés partout ; ___, elles étaient dans son sac. (in the end, as it turned out)`,answer:`finalement`,hint:`the "unexpected ending" word, not enfin`},{type:`translation`,prompt:`How do you say "Indeed, it's raining"? (Use en effet)`,answer:`En effet, il pleut.`,hint:`en effet = confirming word`}]}],isA1:!1,isBeyondA1:!1,isBridge:!0},{id:`past-tenses`,slug:`past-tenses`,title:`Yesterday, Explained`,emoji:`⏪`,tagline:`Passé Composé & Imparfait`,funnyDescription:`So far you have lived in an eternal present. Time to say what actually happened — and which of two past tenses French wants for it.`,color:`#6366F1`,accentColor:`#818cf8`,lessons:[{id:`past-tenses-1`,title:`J'ai Mangé: Meet the Avoir Past`,subtitle:`Most French verbs build their past off avoir — ten stubborn irregulars refuse to follow the pattern.`,xpReward:30,vocab:[{french:`manger → j'ai mangé / finir → j'ai fini / vendre → j'ai vendu`,english:`to eat → I ate / to finish → I finished / to sell → I sold`,pronunciation:`mɑ̃ʒe → ʒe mɑ̃ʒe / fini → ʒe fini / vɑ̃dʁ → ʒe vɑ̃dy`,example:`J'ai mangé à midi, puis j'ai fini mes devoirs.`,exampleTranslation:`I ate at noon, then I finished my homework.`},{french:`faire → j'ai fait`,english:`to do/make → I did/made`,pronunciation:`fɛʁ → ʒe fɛ`,example:`J'ai fait la cuisine hier soir.`,exampleTranslation:`I cooked last night.`,funnyNote:`"Faire" refuses the regular pattern entirely — "fait" never changes, so once it's memorised it's one less thing to worry about. You'll use it constantly.`},{french:`prendre → j'ai pris / mettre → j'ai mis`,english:`to take → I took / to put → I put`,pronunciation:`pʁɑ̃dʁ → ʒe pʁi / mɛtʁ → ʒe mi`,example:`J'ai pris le train et j'ai mis mon manteau.`,exampleTranslation:`I took the train and put on my coat.`,funnyNote:`Family verbs inherit the irregularity: comprendre → compris, apprendre → appris, permettre → permis, promettre → promis. Learn the root and the rest come free.`},{french:`dire → j'ai dit / voir → j'ai vu`,english:`to say → I said / to see → I saw`,pronunciation:`diʁ → ʒe di / vwaʁ → ʒe vy`,example:`J'ai vu le film, mais je n'ai rien dit.`,exampleTranslation:`I saw the film, but I said nothing.`},{french:`avoir → j'ai eu / être → j'ai été / pouvoir → j'ai pu`,english:`to have → I had / to be → I was / to be able to → I was able to`,pronunciation:`avwaʁ → ʒe y / ɛtʁ → ʒe ete / puvwaʁ → ʒe py`,funnyNote:`Avoir and être are French's two most essential verbs — and in the passé composé they're also the two least recognisable: "eu" sounds just like the letter "u", and "été" never changes, even for "elle" (avoir never agrees with the subject).`},{french:`vouloir → j'ai voulu / devoir → j'ai dû`,english:`to want → I wanted / to have to → I had to`,pronunciation:`vulwaʁ → ʒe vuly / dəvwaʁ → ʒe dy`,funnyNote:`"Dû" keeps its circumflex accent only in the masculine singular — "due, dus, dues" all drop it. The accent exists purely to separate "j'ai dû partir" (I had to leave) from "j'ai bu du café" (I drank some coffee): "dû" and "du" sound identical.`},{french:`je n'ai pas mangé`,english:`I didn't eat`,pronunciation:`ʒə ne pa mɑ̃ʒe`,example:`Je n'ai pas mangé ce matin.`,exampleTranslation:`I didn't eat this morning.`,funnyNote:`"Ne" and "pas" wrap around the auxiliary "avoir", not the participle — "je n'ai pas mangé", never "je n'ai mangé pas".`},{french:`Tu as mangé ? / Vous avez mangé ?`,english:`Did you eat? (informal / formal)`,pronunciation:`ty a mɑ̃ʒe / vu zave mɑ̃ʒe`}],exercises:[{type:`multiple-choice`,prompt:`What is the passé composé participle of "faire" (to do/make)?`,answer:`fait`,options:[`faisé`,`fait`,`facé`,`faisis`]},{type:`fill-blank`,prompt:`Hier, j'ai ___ une pizza. (I ate a pizza)`,answer:`mangé`,hint:`Regular -er verb: manger → mangé. Mind the accents.`},{type:`translation`,prompt:`Say "I did my homework." Use the passé composé with avoir.`,answer:`J'ai fait mes devoirs`,hint:`faire → fait; avoir as the auxiliary`},{type:`multiple-choice`,prompt:`How do you correctly negate "J'ai mangé" (I ate)?`,answer:`Je n'ai pas mangé`,options:[`Je n'ai pas mangé`,`Je ne mange pas eu`,`Je n'ai mangé pas`,`Pas je n'ai mangé`]},{type:`fill-blank`,prompt:`Nous avons ___ ce film hier soir. (We saw this movie last night)`,answer:`vu`,hint:`Irregular participle of voir`},{type:`translation`,prompt:`Say "I didn't see the film." Use ne...pas around avoir.`,answer:`Je n'ai pas vu le film`,hint:`Negate avoir; vu stays after pas`}]},{id:`past-tenses-2`,title:`Je Suis Allé(e): The Être Gang`,subtitle:`A short list of movement verbs insists on être, and makes the participle agree like an adjective.`,xpReward:30,vocab:[{french:`il est allé / elle est allée`,english:`he went / she went`,pronunciation:`il ɛ ale / ɛl ɛ ale`,example:`Il est allé au marché ce matin.`,exampleTranslation:`He went to the market this morning.`,funnyNote:`With être, the past participle agrees with the subject like an adjective — add "-e" for a feminine subject. This never happens with avoir.`},{french:`il est parti / il est sorti`,english:`he left / he went out`,pronunciation:`il ɛ paʁti / il ɛ sɔʁti`,funnyNote:`These belong to a closed list of about sixteen verbs nicknamed "DR & MRS VANDERTRAMP" — devenir, revenir, monter, rester, sortir, venir, aller, naître, descendre, entrer, rentrer, tomber, retourner, arriver, mourir, partir. All of them take être, no exceptions.`},{french:`il est né / il est mort`,english:`he was born / he died`,pronunciation:`il ɛ ne / il ɛ mɔʁ`,example:`Napoléon est né en Corse et il est mort à Sainte-Hélène.`,exampleTranslation:`Napoleon was born in Corsica and died on Saint Helena.`},{french:`il est monté / il a monté les valises`,english:`he went up / he carried the suitcases up`,pronunciation:`il ɛ mɔ̃te / il a mɔ̃te le valiz`,example:`Il est monté dans sa chambre, puis il a monté les valises.`,exampleTranslation:`He went up to his room, then he carried the suitcases up.`,funnyNote:`Monter, descendre, sortir, passer and rentrer normally use être — but switch to avoir the moment they take a direct object, because now the subject is moving something else, not just themselves.`},{french:`il s'est levé`,english:`he got up`,pronunciation:`il sɛ ləve`,example:`Il s'est levé à sept heures.`,exampleTranslation:`He got up at seven o'clock.`,funnyNote:`Every reflexive verb (se + verb) takes être in the passé composé, with no exceptions — a second, much longer list on top of the sixteen movement verbs.`},{french:`elle s'est réveillée`,english:`she woke up`,pronunciation:`ɛl sɛ ʁevɛje`},{french:`ils sont arrivés / elles sont arrivées`,english:`they arrived (masc./mixed) / they arrived (fem.)`,pronunciation:`il sɔ̃ tarive / ɛl sɔ̃ tarive`,example:`Elles sont arrivées en retard.`,exampleTranslation:`They (all women) arrived late.`},{french:`je suis né(e) à...`,english:`I was born in... (a place)`,pronunciation:`ʒə sɥi ne a`,funnyNote:`"Naître" always takes être, even though being born doesn't feel like movement. Think of the whole list as verbs of change, not just literal motion.`}],exercises:[{type:`multiple-choice`,prompt:`Which group of verbs uses être — not avoir — in the passé composé?`,answer:`Movement verbs like aller, partir, and arriver`,options:[`Regular -er verbs like manger`,`Movement verbs like aller, partir, and arriver`,`Modal verbs like vouloir`,`Verbs about feelings like aimer`]},{type:`translation`,prompt:`Say "He went to the market." Use the passé composé with être.`,answer:`Il est allé au marché`,hint:`aller → allé; "il" needs no extra agreement letter. Mind the accents.`},{type:`fill-blank`,prompt:`Il s'est ___ à sept heures. (He got up at seven o'clock)`,answer:`levé`,hint:`Pronominal verb se lever, agreeing with "il" — no extra letter. Mind the accents.`},{type:`multiple-choice`,prompt:`Il ___ les valises dans le train. (He carried the suitcases onto the train)`,answer:`a monté`,options:[`est monté`,`a monté`,`est montée`,`sont montés`]},{type:`translation`,prompt:`Say "He arrived late." Use the passé composé with être.`,answer:`Il est arrivé en retard`,hint:`arriver → être; "il" takes no extra agreement letter. Mind the accents.`},{type:`fill-blank`,prompt:`Elle est ___. (She arrived — feminine agreement)`,answer:`arrivée`,hint:`Être verb + feminine singular subject: add -e. Mind the accents.`}]},{id:`past-tenses-3`,title:`Imparfait vs Passé Composé: Scene or Plot?`,subtitle:`One tense paints the background, the other moves the story forward — mixing them up is the #1 past-tense mistake.`,xpReward:30,vocab:[{french:`je mangeais / il mangeait / nous mangions`,english:`I was eating / he was eating / we were eating`,pronunciation:`ʒə mɑ̃ʒɛ / il mɑ̃ʒɛ / nu mɑ̃ʒjɔ̃`,example:`Quand j'étais jeune, je mangeais beaucoup de bonbons.`,exampleTranslation:`When I was young, I used to eat a lot of candy.`},{french:`j'étais / il était`,english:`I was / he was`,pronunciation:`ʒetɛ / il etɛ`,funnyNote:`Être is the only verb with an irregular imparfait stem, "ét-" — every other verb takes its stem straight from the nous form of the present.`},{french:`il faisait beau`,english:`the weather was nice`,pronunciation:`il fəzɛ bo`,example:`Il faisait beau quand nous sommes arrivés.`,exampleTranslation:`The weather was nice when we arrived.`},{french:`tous les jours / chaque semaine`,english:`every day / every week`,pronunciation:`tu le ʒuʁ / ʃak səmɛn`,funnyNote:`Signal words pointing straight at imparfait — anything repeated or habitual, not a one-off event.`},{french:`soudain / tout à coup`,english:`suddenly / all of a sudden`,pronunciation:`sudɛ̃ / tu ta ku`,example:`Je dormais quand, soudain, le téléphone a sonné.`,exampleTranslation:`I was sleeping when, suddenly, the phone rang.`,funnyNote:`These words interrupt an imparfait scene with a single passé composé event — the classic pairing.`},{french:`pendant que`,english:`while`,pronunciation:`pɑ̃dɑ̃ kə`,example:`Pendant que je lisais, il a préparé le dîner.`,exampleTranslation:`While I was reading, he made dinner.`,funnyNote:`The clause after "pendant que" is almost always imparfait (the ongoing background); the other clause reports what actually happened, in passé composé.`},{french:`il était une fois`,english:`once upon a time`,pronunciation:`il etɛ yn fwa`,funnyNote:`Every French fairy tale opens in the imparfait — it's the tense of scene-setting, before any plot has happened yet.`},{french:`quand j'avais... ans`,english:`when I was ... years old`,pronunciation:`kɑ̃ ʒavɛ ɑ̃`,example:`Quand j'avais dix ans, j'habitais à Lyon.`,exampleTranslation:`When I was ten, I lived in Lyon.`}],exercises:[{type:`fill-blank`,prompt:`Quand j'___ dix ans, j'habitais à Lyon. (When I was ten, I lived in Lyon)`,answer:`avais`,hint:`avoir in the imparfait: nous avons → av- + -ais`},{type:`multiple-choice`,prompt:`Which sentence correctly pairs a background action with the event that interrupts it?`,answer:`Je dormais quand le téléphone a sonné.`,options:[`Je dormais quand le téléphone a sonné.`,`J'ai dormi quand le téléphone sonnait.`,`Je dormais quand le téléphone sonnait.`,`J'ai dormi quand le téléphone a sonné.`]},{type:`translation`,prompt:`Say "It was raining when he arrived." Use imparfait then passé composé.`,answer:`Il pleuvait quand il est arrivé`,hint:`pleuvoir describes the backdrop; arriver is the single event. Mind the accents.`},{type:`fill-blank`,prompt:`Pendant que je lisais, il ___ le dîner. (he made dinner — one finished action)`,answer:`a préparé`,hint:`A single completed action interrupting the background → passé composé. Mind the accents.`},{type:`multiple-choice`,prompt:`Il ___ beau quand nous sommes arrivés. (the weather backdrop)`,answer:`faisait`,options:[`faisait`,`a fait`,`fait`,`ferait`]},{type:`translation`,prompt:`Say "Every day, he ate a croissant." Use imparfait for the habit.`,answer:`Chaque jour, il mangeait un croissant`,hint:`Chaque jour signals a repeated habit → imparfait`}]}],isA1:!1,isBeyondA1:!1,isBridge:!0},{id:`pronouns`,slug:`pronouns`,title:`Y, En & Other Tiny Words`,emoji:`🧩`,tagline:`Pronouns & Relative Clauses`,funnyDescription:`French hates repeating nouns, so it hides them in two-letter words placed exactly where English speakers never look.`,color:`#14B8A6`,accentColor:`#2dd4bf`,lessons:[{id:`pronouns-1`,title:`Le vs Lui: Objects in Disguise`,subtitle:`Direct object, indirect object, same person — a completely different tiny word.`,xpReward:30,vocab:[{french:`le / la / l' / les`,english:`him / her / it / them (direct object pronouns)`,pronunciation:`lə / la / l / le`,example:`Tu regardes le film ? Oui, je le regarde.`,exampleTranslation:`Are you watching the film? Yes, I'm watching it.`,funnyNote:`"Le" replaces a masculine noun, "la" a feminine one, "l'" either before a vowel sound, "les" any plural. They plant themselves right before the verb — English speakers keep reaching for the end of the sentence out of habit.`},{french:`lui / leur`,english:`to him / to her / to them (indirect object pronouns)`,pronunciation:`lɥi / lœʁ`,example:`J'écris une lettre à mon père. Je lui écris une lettre.`,exampleTranslation:`I'm writing a letter to my father. I'm writing him a letter.`,funnyNote:`"Lui" is genderless: it means "to him" and "to her". Only context tells you which.`},{french:`me / te / nous / vous`,english:`me / you / us / you (direct or indirect, 1st and 2nd person)`,pronunciation:`mə / tə / nu / vu`,example:`Il nous invite dimanche.`,exampleTranslation:`He's inviting us on Sunday.`},{french:`téléphoner à quelqu'un`,english:`to phone someone`,pronunciation:`telefɔne a kɛlkœ̃`,example:`Je lui téléphone demain.`,exampleTranslation:`I'll phone him tomorrow.`,funnyNote:`The classic trap. "Call someone" sounds direct in English, so learners write "je le téléphone" — wrong. Téléphoner takes à, so it's always lui/leur, never le/la.`},{french:`demander à quelqu'un`,english:`to ask someone`,pronunciation:`dəmɑ̃de a kɛlkœ̃`,example:`Je lui demande l'heure.`,exampleTranslation:`I'm asking him the time.`,funnyNote:`Same trap as téléphoner: "ask someone" feels direct in English, but demander à makes it indirect — lui, never le.`},{french:`je vais le faire`,english:`I'm going to do it (pronoun before the infinitive)`,pronunciation:`ʒə vɛ lə fɛʁ`,example:`Tu vas appeler le médecin ? Oui, je vais l'appeler.`,exampleTranslation:`Are you going to call the doctor? Yes, I'm going to call him.`},{french:`je l'ai vu(e)`,english:`I saw him / her / it (pronoun with the passé composé)`,pronunciation:`ʒə lɛ vy`,example:`Ma sœur ? Je l'ai vue hier.`,exampleTranslation:`My sister? I saw her yesterday.`,funnyNote:`With avoir, a direct object placed before the verb forces the past participle to agree: vu becomes vue for "her". Indirect objects (lui/leur) never do this.`},{french:`je ne le vois pas`,english:`I don't see him / it (pronoun placement in the negative)`,pronunciation:`ʒə nə lə vwa pa`,example:`Non, je ne le vois pas d'ici.`,exampleTranslation:`No, I can't see him from here.`}],exercises:[{type:`multiple-choice`,prompt:`Which pronoun correctly replaces "à ma sœur" in "Je téléphone à ma sœur." ?`,answer:`lui`,options:[`la`,`lui`,`elle`,`leur`]},{type:`fill-blank`,prompt:`Ma sœur ? Je ___ hier. (I saw her yesterday)`,answer:`l'ai vue`,hint:`l' + avoir + past participle, and the participle agrees because l' is feminine and comes first`},{type:`translation`,prompt:`Say "I'm going to do it." Use aller + infinitive, with the pronoun before the infinitive.`,answer:`Je vais le faire`,hint:`je vais + le + faire`},{type:`multiple-choice`,prompt:`Which sentence correctly negates "Je le vois" ?`,answer:`Je ne le vois pas`,options:[`Je le ne vois pas`,`Je ne le vois pas`,`Je ne vois pas le`,`Ne je le vois pas`]},{type:`fill-blank`,prompt:`Il ___ demande son numéro. (He's asking her for her number)`,answer:`lui`,hint:`demander à quelqu'un is always indirect`},{type:`translation`,prompt:`Say "I don't see them." Use ne...pas and the pronoun les.`,answer:`Je ne les vois pas`,hint:`je + ne + les + vois + pas`}]},{id:`pronouns-2`,title:`Y & En: The Vanishing Words`,subtitle:`Two letters that erase an entire place, thing, or quantity from the sentence.`,xpReward:30,vocab:[{french:`y`,english:`there / about it (replaces à + place or thing)`,pronunciation:`i`,example:`Tu vas à Paris ? Oui, j'y vais.`,exampleTranslation:`Are you going to Paris? Yes, I'm going (there).`,funnyNote:`"Y" replaces à + a place or à + a thing — never à + a person. For people, use lui/leur or à + moi/toi/lui.`},{french:`en`,english:`of it / of them / some (replaces de + thing, or a quantity)`,pronunciation:`ɑ̃`,example:`Tu veux du café ? Oui, j'en veux.`,exampleTranslation:`Do you want coffee? Yes, I want some.`,funnyNote:`"En" carries the quantity. With a number, you still need it: "j'en veux deux" (I want two of them) — never just "je veux deux" on its own.`},{french:`il y a`,english:`there is / there are`,pronunciation:`il i a`,example:`Il y a un problème.`,exampleTranslation:`There's a problem.`},{french:`vas-y / allez-y`,english:`go on / go for it`,pronunciation:`vazi / alezi`,example:`Tu hésites ? Vas-y, demande-lui !`,exampleTranslation:`You're hesitating? Go on, ask him!`},{french:`je m'en vais`,english:`I'm leaving / I'm off`,pronunciation:`ʒə mɑ̃ vɛ`,example:`Bon, je m'en vais, à demain !`,exampleTranslation:`Right, I'm off, see you tomorrow!`,funnyNote:`"S'en aller" is a fixed idiom for "to leave" — the "en" here isn't replacing anything, it's baked permanently into the verb.`},{french:`j'en ai marre`,english:`I'm fed up`,pronunciation:`ʒɑ̃ nɛ maʁ`,example:`J'en ai marre de ce bruit.`,exampleTranslation:`I'm fed up with this noise.`},{french:`j'y pense`,english:`I'm thinking about it`,pronunciation:`ʒi pɑ̃s`,example:`Ton anniversaire ? J'y pense déjà !`,exampleTranslation:`Your birthday? I'm already thinking about it!`,funnyNote:`"Penser à" takes y only for things. For a person, drop y and say "je pense à lui" — never "j'y pense" about someone.`},{french:`il y en a`,english:`there is / are some (of it / of them)`,pronunciation:`il jɑ̃ na`,example:`Il y en a encore ?`,exampleTranslation:`Is there any left?`,funnyNote:`The two little words stack in a fixed order: y always comes before en, no exceptions.`}],exercises:[{type:`fill-blank`,prompt:`Tu vas à la réunion ? Oui, j'___ vais. (Yes, I'm going there)`,answer:`y`,hint:`y replaces à + place`},{type:`multiple-choice`,prompt:`Which word correctly replaces "de questions" in "Je n'ai pas de questions." → "Je n'___ ai pas." ?`,answer:`en`,options:[`en`,`y`,`les`,`leur`]},{type:`translation`,prompt:`Say "I'm thinking about it." (the thing, not a person)`,answer:`J'y pense`,hint:`y replaces à + the thing`},{type:`fill-blank`,prompt:`Il y ___ a deux dans le frigo. (There are two of them in the fridge)`,answer:`en`,hint:`y + en + a + number is a fixed pattern`},{type:`multiple-choice`,prompt:`Which sentence means "There's a problem" ?`,answer:`Il y a un problème`,options:[`Il y a un problème`,`Il en a un problème`,`Il y en a un problème`,`Il a y un problème`]},{type:`translation`,prompt:`Say "I'm fed up with this noise." Use en avoir marre de.`,answer:`J'en ai marre de ce bruit`,hint:`j'en ai marre de + noise`}]},{id:`pronouns-3`,title:`Qui, Que, Où, Dont: Stitching Sentences Together`,subtitle:`How French welds two sentences into one without ever repeating the noun.`,xpReward:30,vocab:[{french:`qui`,english:`who / which / that (subject of the relative clause)`,pronunciation:`ki`,example:`J'ai un ami qui parle japonais.`,exampleTranslation:`I have a friend who speaks Japanese.`,funnyNote:`The subject test: if the noun being replaced does the verb's action in the clause, use qui. And it never elides — qui a, not "qu'a".`},{french:`que / qu'`,english:`whom / which / that (object of the relative clause)`,pronunciation:`kə / k`,example:`Le livre que je lis est passionnant.`,exampleTranslation:`The book that I'm reading is fascinating.`,funnyNote:`The object test: if the clause already has its own subject and the noun is on the receiving end, use que. It elides before a vowel: qu'il, qu'elle.`},{french:`où`,english:`where / when (place or time)`,pronunciation:`u`,example:`La ville où j'habite est petite.`,exampleTranslation:`The city where I live is small.`,funnyNote:`Où isn't just for places — it's the standard word for "when" after a time expression: "le jour où on s'est rencontrés", never "le jour quand".`},{french:`dont`,english:`whose / of which / about which (replaces de + noun)`,pronunciation:`dɔ̃`,example:`Le livre dont je parle est excellent.`,exampleTranslation:`The book I'm talking about is excellent.`,funnyNote:`Use dont whenever the verb needs de: parler de, avoir besoin de, être content de. Never add a second de afterward — that's redundant.`},{french:`ce qui`,english:`what (subject, no specific antecedent)`,pronunciation:`sə ki`,example:`Dis-moi ce qui t'inquiète.`,exampleTranslation:`Tell me what's worrying you.`},{french:`ce que / ce qu'`,english:`what (object, no specific antecedent)`,pronunciation:`sə kə / sə k`,example:`Je ne comprends pas ce que tu veux dire.`,exampleTranslation:`I don't understand what you mean.`,funnyNote:`"Ce qui" and "ce que" cover English's vague "what" when there's no specific noun to hang a relative clause on. Pick qui or que with the same subject/object test as above.`},{french:`dont j'ai besoin`,english:`that I need (chunk with avoir besoin de)`,pronunciation:`dɔ̃ ʒɛ bəzwɛ̃`,example:`Voici le stylo dont j'ai besoin.`,exampleTranslation:`Here's the pen that I need.`},{french:`le jour où`,english:`the day when`,pronunciation:`lə ʒuʁ u`,example:`Je me souviens du jour où on s'est rencontrés.`,exampleTranslation:`I remember the day we met.`}],exercises:[{type:`translation`,prompt:`Say "The book that I'm reading is fascinating." Use que.`,answer:`Le livre que je lis est passionnant`,hint:`le livre + que + je lis + est passionnant`},{type:`multiple-choice`,prompt:`J'ai un ami ___ parle japonais.`,answer:`qui`,options:[`que`,`qui`,`dont`,`où`]},{type:`fill-blank`,prompt:`Le livre ___ je parle est excellent. (the book I'm talking about)`,answer:`dont`,hint:`parler de quelque chose → dont`},{type:`multiple-choice`,prompt:`Which sentence correctly uses où for time?`,answer:`Le jour où on s'est rencontrés`,options:[`Le jour où on s'est rencontrés`,`Le jour quand on s'est rencontrés`,`Le jour que on s'est rencontrés`,`Le jour qui on s'est rencontrés`]},{type:`translation`,prompt:`Say "I don't understand what you mean." Use ce que.`,answer:`Je ne comprends pas ce que tu veux dire`,hint:`je ne comprends pas + ce que + tu veux dire`},{type:`fill-blank`,prompt:`Dis-moi ___ t'inquiète. (Tell me what's worrying you)`,answer:`ce qui`,hint:`no specific noun, and it's the subject of inquiète`}]},{id:`pronouns-4`,title:`Where Everything Goes`,subtitle:`Pronouns jump before the verb, ne…pas wraps the helper, adverbs trail the verb, and BAGS adjectives cut the line.`,xpReward:30,vocab:[{french:`Je le vois.`,english:`I see him.`,pronunciation:`ʒə lə vwa`,funnyNote:`English puts him/it/me after the verb. French moves the object pronoun in front of it: je le vois is literally "I him see".`},{french:`Elle m'appelle.`,english:`She calls me.`,pronunciation:`ɛl mapɛl`,example:`Il m'aide souvent.`,exampleTranslation:`He often helps me.`},{french:`Nous leur donnons le livre.`,english:`We give them the book.`,pronunciation:`nu lœʁ dɔnɔ̃ lə livʁ`,funnyNote:`Only the pronoun jumps. Real nouns like le livre stay after the verb, exactly where English puts them.`},{french:`Je ne l'ai pas vu.`,english:`I didn't see him.`,pronunciation:`ʒə nə le pa vy`,funnyNote:`In the passé composé the sandwich wraps the helper (ai), and the pronoun rides inside with it: ne + l' + ai + pas + vu.`},{french:`Je mange souvent ici.`,english:`I often eat here.`,pronunciation:`ʒə mɑ̃ʒ suvɑ̃ isi`,funnyNote:`English slips "often" before the verb. French puts it right after: je mange souvent — never je souvent mange.`},{french:`J'ai souvent mangé.`,english:`I have often eaten.`,pronunciation:`ʒe suvɑ̃ mɑ̃ʒe`,example:`Elle a toujours aimé Paris.`,exampleTranslation:`She has always loved Paris.`},{french:`une belle maison / une maison rouge`,english:`a beautiful house / a red house`,pronunciation:`yn bɛl mɛzɔ̃ / yn mɛzɔ̃ ʁuʒ`,funnyNote:`BAGS — Beauty, Age, Goodness, Size. Short adjectives like beau, jeune, bon and grand go before the noun; most others, like colors, go after.`},{french:`une petite voiture rouge`,english:`a small red car`,pronunciation:`yn pətit vwatyʁ ʁuʒ`}],exercises:[{type:`multiple-choice`,prompt:`Which sentence means "I see him"?`,answer:`Je le vois`,options:[`Je vois le`,`Je le vois`,`Le je vois`,`Je vois lui`]},{type:`multiple-choice`,prompt:`Which is correct for "a young man"?`,answer:`un jeune homme`,options:[`un homme le jeune`,`un jeune homme`,`un homme de jeune`,`jeune un homme`]},{type:`fill-blank`,prompt:`Je ne l'ai ___ vu. (I didn't see him)`,answer:`pas`,hint:`pas closes the sandwich right after the helper`},{type:`fill-blank`,prompt:`Elle parle ___ vite. (She always speaks fast)`,answer:`toujours`,hint:`The adverb sits right after the conjugated verb`},{type:`translation`,prompt:`You know her.`,answer:`Tu la connais`,hint:`The pronoun la jumps before the verb. Mind the accents.`},{type:`translation`,prompt:`I didn't eat it.`,answer:`Je ne l'ai pas mangé`,hint:`ne + l' + ai + pas + mangé`}]}],isA1:!1,isBeyondA1:!1,isBridge:!0},{id:`b1-narration`,slug:`b1-narration`,title:`Once Upon a Métro`,emoji:`📖`,tagline:`Storytelling & Narration`,funnyDescription:`Every French dinner party runs on anecdotes. This unit gets you a turn — and teaches you to react properly to everyone else's.`,color:`#F59E0B`,accentColor:`#fbbf24`,lessons:[{id:`b1-narration-1`,title:`Time Markers: The Depuis Trap`,subtitle:`Six tiny words decide whether your story is still happening or already over — get one wrong and native speakers will silently judge you.`,xpReward:35,vocab:[{french:`il y a`,english:`ago`,pronunciation:`il i a`,example:`Je suis arrivé il y a deux ans.`,exampleTranslation:`I arrived two years ago.`},{french:`depuis + présent`,english:`since / for (an action still going on)`,pronunciation:`dəpɥi`,example:`J'habite à Lyon depuis trois ans.`,exampleTranslation:`I have been living in Lyon for three years.`,funnyNote:`The trap: English says "I have lived" (present perfect), but if it's still true now, French stays in the présent — "j'habite... depuis", never "j'ai habité... depuis". Switch to the passé composé and you accidentally announce that you moved out.`},{french:`depuis que + proposition`,english:`since (+ clause, an event happened)`,pronunciation:`dəpɥi kə`,example:`Depuis qu'il est parti, la maison est trop calme.`,exampleTranslation:`Since he left, the house is too quiet.`},{french:`pendant`,english:`during / for (a finished stretch of time)`,pronunciation:`pɑ̃dɑ̃`,example:`J'ai vécu à Berlin pendant deux ans.`,exampleTranslation:`I lived in Berlin for two years.`,funnyNote:`Pendant marks a closed, finished span, so it pairs with the passé composé. Depuis marks a span still open and connected to now, so it pairs with the présent. Same English word "for", two completely different French tools.`},{french:`en + durée`,english:`in (the time it takes to complete something)`,pronunciation:`ɑ̃`,example:`J'ai lu ce roman en trois jours.`,exampleTranslation:`I read this novel in three days.`,funnyNote:`En answers "how long did it take?" — the action is already finished inside that window. Dans answers "how long until it starts?" — the action hasn't begun yet. Mix them up and you change whether something is done or still coming.`},{french:`dans + durée`,english:`in (a future point in time)`,pronunciation:`dɑ̃`,example:`Le train part dans dix minutes.`,exampleTranslation:`The train leaves in ten minutes.`,funnyNote:`Dans and il y a are mirror images on the timeline: "il y a deux jours" looks two days into the past, "dans deux jours" looks two days into the future. Neither one ever carries depuis's ongoing, still-true-now meaning.`},{french:`ça fait ... que`,english:`it has been ... since / for`,pronunciation:`sa fɛ kə`,example:`Ça fait six mois qu'on se connaît.`,exampleTranslation:`We have known each other for six months.`},{french:`Depuis quand ?`,english:`Since when? / How long has this been going on?`,pronunciation:`dəpɥi kɑ̃`,example:`Depuis quand tu apprends le français ?`,exampleTranslation:`How long have you been learning French?`}],exercises:[{type:`multiple-choice`,prompt:`"J'habite à Lyon ___ cinq ans." She still lives there. Which word fits?`,answer:`depuis`,options:[`depuis`,`pendant`,`il y a`,`dans`]},{type:`fill-blank`,prompt:`Elle est née ___ vingt ans. (twenty years ago)`,answer:`il y a`,hint:`"Ago" looks backward from now — one specific two-word marker. Mind the accent: "a" not "à".`},{type:`translation`,prompt:`I have lived in Paris for three years, and I still do. Use the présent tense with depuis.`,answer:`J'habite à Paris depuis trois ans.`,hint:`Présent tense + à (mind the accent) + depuis + duration, no passé composé.`},{type:`multiple-choice`,prompt:`Which tense follows "depuis" when the action described is still true right now?`,answer:`Le présent`,options:[`Le passé composé`,`L'imparfait`,`Le présent`,`Le futur`]},{type:`fill-blank`,prompt:`J'ai fini mes devoirs ___ une heure. (it took me one hour to finish)`,answer:`en`,hint:`En marks how long an action took to complete, not when it starts.`},{type:`translation`,prompt:`The film starts in ten minutes. Use dans for the future point in time.`,answer:`Le film commence dans dix minutes.`,hint:`Dans + duration = a future point on the clock.`}]},{id:`b1-narration-2`,title:`The Past Before the Past`,subtitle:`The plus-que-parfait lets you say what had already happened before your story even started — skip it and your timeline collapses.`,xpReward:35,vocab:[{french:`avais / étais + participe passé`,english:`had done (the plus-que-parfait)`,pronunciation:`avɛ / etɛ`,funnyNote:`Formed exactly like the passé composé, but with the imparfait of avoir/être instead of the présent: j'avais mangé, j'étais parti(e). It marks the earlier of two past events — the one that had already happened before the story's main action.`},{french:`avant de + infinitif`,english:`before doing (something)`,pronunciation:`avɑ̃ də`,example:`Avant de partir, j'ai fermé la porte.`,exampleTranslation:`Before leaving, I closed the door.`,funnyNote:`Avant de + infinitive only works when both actions share the same subject. Different subjects ("before HE arrived") need avant que + subjonctif instead — a trickier structure for another day.`},{french:`après avoir + participe passé`,english:`after doing / having done (most verbs)`,pronunciation:`apʁɛ avwaʁ`,example:`Après avoir mangé, elle est sortie.`,exampleTranslation:`After eating, she went out.`},{french:`après être + participe passé`,english:`after doing / having done (être-verbs)`,pronunciation:`apʁɛ ɛtʁ`,example:`Après être arrivée, elle a appelé sa mère.`,exampleTranslation:`After arriving, she called her mother.`,funnyNote:`The choice between avoir and être here depends on the SECOND verb, never the first — and with être, the past participle still agrees with the subject: "après être arrivée" for a woman, "après être arrivés" for a group.`},{french:`au moment où`,english:`just as / at the (exact) moment when`,pronunciation:`o mɔmɑ̃ u`,example:`Au moment où je suis sorti, il pleuvait.`,exampleTranslation:`Just as I went out, it was raining.`},{french:`il avait déjà fini`,english:`he had already finished`,pronunciation:`il avɛ deʒa fini`,example:`Quand je suis arrivé, il avait déjà fini.`,exampleTranslation:`When I arrived, he had already finished.`,funnyNote:`Déjà is the classic signal word for the plus-que-parfait: it flags that one event was already complete before the next one started.`},{french:`elle n'avait pas encore mangé`,english:`she had not yet eaten`,pronunciation:`ɛl navɛ pa zɑ̃kɔʁ mɑ̃ʒe`,example:`Elle n'avait pas encore mangé quand nous sommes arrivés.`,exampleTranslation:`She had not yet eaten when we arrived.`},{french:`la veille`,english:`the day before / the previous day`,pronunciation:`la vɛj`,example:`Il était parti la veille.`,exampleTranslation:`He had left the day before.`,funnyNote:`When you narrate in the past, "hier" (yesterday) shifts to "la veille" — you're no longer speaking from today, so you need a marker relative to the story's own timeline.`}],exercises:[{type:`multiple-choice`,prompt:`Quand je suis arrivé, elle ___ déjà partie. Which form is correct?`,answer:`était`,options:[`avait`,`était`,`a`,`est`]},{type:`fill-blank`,prompt:`Après ___ mangé, nous avons pris un café. (after eating)`,answer:`avoir`,hint:`Après + avoir + past participle, for most verbs.`},{type:`translation`,prompt:`Before leaving, I closed the door. Use avant de + infinitive.`,answer:`Avant de partir, j'ai fermé la porte.`,hint:`avant de + infinitif, same subject throughout. Mind the accent on la (à/la distinction).`},{type:`multiple-choice`,prompt:`In "après être arrivée", what does the final "-e" agree with?`,answer:`The subject`,options:[`The direct object`,`The subject`,`It never agrees`,`The verb's tense`]},{type:`fill-blank`,prompt:`Il ___ déjà fini quand je suis arrivé. (had already finished)`,answer:`avait`,hint:`Plus-que-parfait of finir = imparfait of avoir + fini.`},{type:`translation`,prompt:`Just as I went out, it was raining. Use au moment où.`,answer:`Au moment où je suis sorti, il pleuvait.`,hint:`au moment où (mind the accent on où: ou/où distinction) + passé composé, then imparfait for the backdrop.`}]},{id:`b1-narration-3`,title:`Dinner Party Storytelling`,subtitle:`Openers, reactions, and the art of holding the floor — every anecdote needs an audience that gasps on cue.`,xpReward:35,vocab:[{french:`l'autre jour`,english:`the other day`,pronunciation:`lotʁ ʒuʁ`,example:`L'autre jour, j'ai croisé mon prof de lycée au supermarché.`,exampleTranslation:`The other day, I ran into my high school teacher at the supermarket.`},{french:`tout à coup`,english:`all of a sudden`,pronunciation:`tu ta ku`,example:`Tout à coup, la lumière s'est éteinte.`,exampleTranslation:`All of a sudden, the light went out.`},{french:`du coup`,english:`so / as a result`,pronunciation:`dy ku`,example:`Il pleuvait, du coup on est restés à la maison.`,exampleTranslation:`It was raining, so we stayed home.`,funnyNote:`Du coup is everywhere in spoken French — so common that some people use it as a pure filler with no real "result" attached. Great for fitting in, risky in a formal essay: reach for "par conséquent" or "donc" there instead.`},{french:`finalement`,english:`in the end / as it turns out`,pronunciation:`finalmɑ̃`,example:`Je pensais qu'il allait refuser, mais finalement il a dit oui.`,exampleTranslation:`I thought he was going to refuse, but in the end he said yes.`,funnyNote:`False friend alert: finalement doesn't mean "finally" in the sense of "at last, after a long wait" — that's "enfin". Finalement signals a surprising or unexpected outcome, closer to "as it turns out".`},{french:`Sans blague ?`,english:`No kidding? / Seriously?`,pronunciation:`sɑ̃ blag`,example:`— J'ai gagné au loto. — Sans blague ?`,exampleTranslation:`"I won the lottery." "No kidding?"`},{french:`Ah bon ?`,english:`Oh really? (mild surprise)`,pronunciation:`a bɔ̃`},{french:`Et alors ?`,english:`And then? / So what?`,pronunciation:`e alɔʁ`,example:`— Il m'a dit non. — Et alors, tu as fait quoi ?`,exampleTranslation:`"He told me no." "And then, what did you do?"`,funnyNote:`Et alors ? carries two completely different tones: asked with rising curiosity it means "and then what happened?"; said flatly it means "so what, who cares?" Context and tone of voice carry the whole meaning.`},{french:`bref`,english:`anyway / long story short`,pronunciation:`bʁɛf`,funnyNote:`Bref is the storyteller's escape hatch: drop it in when you're cutting a long story short or getting back to the point. "Enfin bref" is the same move with extra emphasis.`},{french:`je te raconte`,english:`let me tell you (about this) / so get this`,pronunciation:`ʒə tə ʁakɔ̃t`,example:`Je te raconte : hier, j'ai vu Marc à la gare.`,exampleTranslation:`Let me tell you: yesterday, I saw Marc at the station.`}],exercises:[{type:`multiple-choice`,prompt:`Which word signals "so / as a result" in a casual spoken story?`,answer:`du coup`,options:[`bref`,`du coup`,`ah bon`,`sans blague`]},{type:`fill-blank`,prompt:`Il faisait froid, ___ on est rentrés tôt. (so / as a result)`,answer:`du coup`,hint:`The everyday spoken connector for cause → result. Mind du (du/dû distinction).`},{type:`translation`,prompt:`The other day, I saw my old teacher at the market. Start with l'autre jour.`,answer:`L'autre jour, j'ai vu mon ancien prof au marché.`,hint:`l'autre jour + passé composé. Mind the accent on marché.`},{type:`multiple-choice`,prompt:`Someone just finished a long, winding story. Which word means "anyway, to cut it short"?`,answer:`bref`,options:[`bref`,`et alors`,`ah bon`,`tout à coup`]},{type:`fill-blank`,prompt:`Je pensais qu'il allait refuser, mais ___, il a dit oui. (in the end / as it turned out)`,answer:`finalement`,hint:`False friend: not the same as "enfin" (at last).`},{type:`translation`,prompt:`So what happened next? Use et alors to ask for more of the story.`,answer:`Et alors ?`,hint:`Two words, rising intonation = "and then?"`}]}],isA1:!1,isBeyondA1:!1,isB1:!0},{id:`b1-opinions`,slug:`b1-opinions`,title:`Well, Actually…`,emoji:`💭`,tagline:`Opinions & Agreement`,funnyDescription:`In France, having an opinion is a civic duty and disagreeing well is an art form. Time to participate.`,color:`#8B5CF6`,accentColor:`#a78bfa`,lessons:[{id:`b1-opinions-1`,title:`Well, I Think That...`,subtitle:`Seven ways to launch an opinion, because in France silence is basically a crime.`,xpReward:35,vocab:[{french:`je pense que`,english:`I think that`,pronunciation:`ʒə pɑ̃s kə`,example:`Je pense que c'est une bonne idée.`,exampleTranslation:`I think that's a good idea.`,funnyNote:`Affirmative "penser que" takes a normal indicative verb, like here. Negate it — "je ne pense pas que..." — and the following verb switches mood entirely. That's a lesson for later; for now, keep it affirmative.`},{french:`je crois que`,english:`I believe that / I think that`,pronunciation:`ʒə kʁwa kə`,example:`Je crois que le train part à midi.`,exampleTranslation:`I think the train leaves at noon.`},{french:`je trouve que`,english:`I find that`,pronunciation:`ʒə tʁuv kə`,example:`Je trouve que ce musée est fascinant.`,exampleTranslation:`I find this museum fascinating.`,funnyNote:`"Trouver que" is for reactions to something you've experienced — a meal, a film, a decision. "Je pense que" would work too, but "je trouve que" sounds more personal, like a taste rather than a theory.`},{french:`à mon avis`,english:`in my opinion`,pronunciation:`a mɔ̃ navi`,example:`À mon avis, il vaut mieux partir tôt.`,exampleTranslation:`In my opinion, it's better to leave early.`},{french:`selon moi`,english:`according to me / in my view`,pronunciation:`səlɔ̃ mwa`,example:`Selon moi, cette décision est risquée.`,exampleTranslation:`In my view, this decision is risky.`,funnyNote:`"Selon moi" sits a notch more formal than "à mon avis" — you'll hear it in debates, opinion pieces, and any moment someone wants to sound serious.`},{french:`pour moi`,english:`to my mind / for me`,pronunciation:`puʁ mwa`,example:`Pour moi, le plus important, c'est la santé.`,exampleTranslation:`To my mind, the most important thing is health.`,funnyNote:`The same three words also mean literally "for me" when ordering ("un café pour moi"). At the start of a sentence stating a stance, it signals opinion, not a coffee order.`},{french:`il me semble que`,english:`it seems to me that`,pronunciation:`il mə sɑ̃bl kə`,example:`Il me semble que tout le monde est d'accord.`,exampleTranslation:`It seems to me that everyone agrees.`},{french:`j'ai l'impression que`,english:`I have the feeling that`,pronunciation:`ʒe lɛ̃pʁesjɔ̃ kə`,example:`J'ai l'impression que ça va marcher.`,exampleTranslation:`I have a feeling that it's going to work.`,funnyNote:`Softer and more intuitive than "je pense que" — good for a hedged, gut-feeling opinion rather than a firm one.`}],exercises:[{type:`multiple-choice`,prompt:`Which opinion phrase is followed directly by a complete sentence, with no "que"?`,answer:`à mon avis`,options:[`à mon avis`,`je pense que`,`je trouve que`,`il me semble que`]},{type:`fill-blank`,prompt:`Je ___ que ce restaurant est excellent. (I find that this restaurant is excellent)`,answer:`trouve`,hint:`"Trouver que" for a personal reaction to something you experienced.`},{type:`translation`,prompt:`Say: "I think that he is right." (Use je pense)`,answer:`Je pense qu'il a raison`,hint:`je pense que + il → qu'il`},{type:`multiple-choice`,prompt:`Which phrase is a notch more formal than "à mon avis" and common in debates or opinion pieces?`,answer:`Selon moi`,options:[`Selon moi`,`Pour moi`,`J'ai l'impression que`,`Il me semble que`]},{type:`fill-blank`,prompt:`___, il vaut mieux réserver à l'avance. (In my opinion, it's better to book in advance)`,answer:`À mon avis`,hint:`Adverbial opinion phrase, no "que" needed before the clause. Mind the accent on À.`},{type:`translation`,prompt:`Say: "I have the feeling that it's true." (Use j'ai l'impression)`,answer:`J'ai l'impression que c'est vrai`,hint:`j'ai l'impression que + clause`}]},{id:`b1-opinions-2`,title:`Actually, No`,subtitle:`Agreeing, disagreeing, and surviving both without anyone storming off.`,xpReward:35,vocab:[{french:`être d'accord (avec)`,english:`to agree (with)`,pronunciation:`ɛtʁ dakɔʁ`,example:`Je suis d'accord avec toi.`,exampleTranslation:`I agree with you.`},{french:`tout à fait`,english:`absolutely / totally`,pronunciation:`tu ta fɛ`,example:`Tout à fait, tu as raison.`,exampleTranslation:`Absolutely, you're right.`},{french:`exactement`,english:`exactly`,pronunciation:`ɛgzaktəmɑ̃`,example:`Exactement, c'est ce que je voulais dire.`,exampleTranslation:`Exactly, that's what I meant.`},{french:`pas du tout`,english:`not at all`,pronunciation:`pa dy tu`,example:`Pas du tout, je ne suis pas d'accord.`,exampleTranslation:`Not at all, I disagree.`,funnyNote:`"Pas du tout" can answer either "do you agree?" (= no) or "does this bother you?" (= not at all, no problem). The words don't change — the question's polarity decides the meaning.`},{french:`je ne suis pas d'accord`,english:`I disagree`,pronunciation:`ʒə nə sɥi pa dakɔʁ`,example:`Je ne suis pas d'accord avec cette idée.`,exampleTranslation:`I disagree with this idea.`,funnyNote:`Completely normal, not rude, in French conversation. French debate culture treats a flat "je ne suis pas d'accord" as honest — as long as you back it up with a reason.`},{french:`tu as raison / tu as tort`,english:`you're right / you're wrong`,pronunciation:`ty a ʁɛzɔ̃ / ty a tɔʁ`,example:`Tu as raison, j'ai mal compris.`,exampleTranslation:`You're right, I misunderstood.`,funnyNote:`Literally "you have reason" / "you have wrong" — avoir carries this one, not être. "Tu es raison" is a classic anglicism trap.`},{french:`c'est vrai, mais...`,english:`that's true, but...`,pronunciation:`sɛ vʁɛ mɛ`,example:`C'est vrai, mais ce n'est pas si simple.`,exampleTranslation:`That's true, but it's not that simple.`,funnyNote:`The classic French move: concede a point before pushing back. It signals you listened, then lets you disagree without sounding combative.`},{french:`je vois ce que tu veux dire`,english:`I see what you mean`,pronunciation:`ʒə vwa sə kə ty vø diʁ`,example:`Je vois ce que tu veux dire, mais je ne suis pas convaincu.`,exampleTranslation:`I see what you mean, but I'm not convinced.`},{french:`mouais`,english:`yeah... (unconvinced)`,pronunciation:`mwɛ`,example:`Mouais, je ne suis pas sûr.`,exampleTranslation:`Yeah... I'm not sure.`,funnyNote:`Pure spoken French — a skeptical half-agreement between "oui" and "non." Never write it in an email; save it for friends and the occasional eye-roll.`}],exercises:[{type:`multiple-choice`,prompt:`How do you say "You're right" in French?`,answer:`Tu as raison`,options:[`Tu es raison`,`Tu as raison`,`Tu es vrai`,`Tu as vrai`]},{type:`fill-blank`,prompt:`C'est vrai, ___ ce n'est pas si simple. (that's true, but it's not that simple)`,answer:`mais`,hint:`Concede the point, then push back.`},{type:`translation`,prompt:`Say: "You're wrong." (Use avoir)`,answer:`Tu as tort`,hint:`avoir + tort, not être`},{type:`multiple-choice`,prompt:`Which word is spoken-only, skeptical, and shouldn't appear in an email?`,answer:`Mouais`,options:[`Tout à fait`,`Exactement`,`Mouais`,`Je suis d'accord`]},{type:`fill-blank`,prompt:`Je ne suis pas ___ avec cette idée. (I disagree with this idea)`,answer:`d'accord`,hint:`Negate "être d'accord."`},{type:`translation`,prompt:`Say: "I see what you mean." (The softening phrase from this lesson)`,answer:`Je vois ce que tu veux dire`,hint:`je vois ce que tu veux dire`}]},{id:`b1-opinions-3`,title:`It Depends, Sort Of`,subtitle:`The art of committing to an opinion without actually committing to it.`,xpReward:35,vocab:[{french:`plutôt`,english:`rather / more accurately`,pronunciation:`plyto`,example:`C'est plutôt compliqué.`,exampleTranslation:`It's rather complicated.`},{french:`assez`,english:`fairly / quite`,pronunciation:`ase`,example:`C'est assez intéressant.`,exampleTranslation:`It's fairly interesting.`,funnyNote:`A false-friend trap: before an adjective, "assez" means "fairly/quite." After a verb, it means "enough" ("j'ai assez mangé" = I've eaten enough). Same word, different job depending on position.`},{french:`un peu`,english:`a little / somewhat`,pronunciation:`œ̃ pø`,example:`Je suis un peu fatigué.`,exampleTranslation:`I'm a little tired.`},{french:`pas vraiment`,english:`not really`,pronunciation:`pa vʁɛmɑ̃`,example:`Pas vraiment, ce n'est pas mon avis.`,exampleTranslation:`Not really, that's not my view.`},{french:`ça dépend`,english:`it depends`,pronunciation:`sa depɑ̃`,example:`Ça dépend du contexte.`,exampleTranslation:`It depends on the context.`,funnyNote:`The classic hedge for refusing to commit to a flat opinion — perfectly acceptable, even expected, in French discussion.`},{french:`d'un côté... de l'autre`,english:`on one hand... on the other`,pronunciation:`dœ̃ kote... də lotʁ`,example:`D'un côté, c'est cher ; de l'autre, c'est pratique.`,exampleTranslation:`On one hand it's expensive; on the other, it's practical.`,funnyNote:`The two halves are a pair — using "d'un côté" alone leaves the listener waiting for the "de l'autre" that never comes.`},{french:`en général`,english:`in general`,pronunciation:`ɑ̃ ʒeneʁal`,example:`En général, les magasins ferment le dimanche.`,exampleTranslation:`In general, shops close on Sundays.`},{french:`dans l'ensemble`,english:`overall / on the whole`,pronunciation:`dɑ̃ lɑ̃sɑ̃bl`,example:`Dans l'ensemble, le voyage s'est bien passé.`,exampleTranslation:`Overall, the trip went well.`,funnyNote:`"Dans l'ensemble" sums up a mixed experience after weighing the details — more measured than "en général," which just states a broad pattern.`},{french:`je dirais que`,english:`I would say that`,pronunciation:`ʒə diʁɛ kə`,example:`Je dirais que c'est une bonne idée, mais...`,exampleTranslation:`I would say that it's a good idea, but...`,funnyNote:`The conditional of "dire" — softer than "je pense que." It hedges the opinion as a careful guess, not a flat statement.`}],exercises:[{type:`multiple-choice`,prompt:`In "C'est assez intéressant," what does "assez" mean here?`,answer:`Fairly / quite`,options:[`Enough`,`Fairly / quite`,`Very`,`Not at all`]},{type:`fill-blank`,prompt:`___, ça dépend des gens. (In general, it depends on people)`,answer:`En général`,hint:`A broad-pattern hedge, not a mixed-results one.`},{type:`translation`,prompt:`Say: "It depends."`,answer:`Ça dépend`,hint:`ça + dépendre, present tense`},{type:`multiple-choice`,prompt:`Which pair of connectors must be used together to contrast two sides of an issue?`,answer:`d'un côté... de l'autre`,options:[`d'un côté... de l'autre`,`en général... dans l'ensemble`,`plutôt... assez`,`ça dépend... pas vraiment`]},{type:`fill-blank`,prompt:`Je ___ que c'est une bonne solution, mais je ne suis pas sûr. (I would say that it's a good solution, but I'm not sure)`,answer:`dirais`,hint:`Conditional of dire.`},{type:`translation`,prompt:`Say: "Overall, it's a good idea." (Use dans l'ensemble)`,answer:`Dans l'ensemble, c'est une bonne idée`,hint:`dans l'ensemble + c'est une bonne idée`}]}],isA1:!1,isBeyondA1:!1,isB1:!0},{id:`b1-hypothetical`,slug:`b1-hypothetical`,title:`Si J'étais Riche`,emoji:`🔮`,tagline:`Future, Conditional & Si-Clauses`,funnyDescription:`Dreams, plans, polite requests and regrets all live in the same two tenses. Master them and you can finally say what you would do.`,color:`#EC4899`,accentColor:`#f472b6`,lessons:[{id:`b1-hypothetical-1`,title:`Tomorrow, Probably`,subtitle:`Futur simple: one set of endings, ten stems that refuse to behave.`,xpReward:35,vocab:[{french:`être → je serai`,english:`to be → I will be`,pronunciation:`ʒə səʁe`,example:`Je serai en retard.`,exampleTranslation:`I will be late.`,funnyNote:`Futur simple always uses six fixed endings — -ai, -as, -a, -ons, -ez, -ont — glued onto a stem. Regular verbs use the infinitive as the stem (parler → parlerai); irregulars like être just swap in a different stem and keep the same endings.`},{french:`avoir → j'aurai`,english:`to have → I will have`,pronunciation:`ʒoʁe`,example:`J'aurai trente ans en mai.`,exampleTranslation:`I will turn thirty in May.`},{french:`aller → j'irai`,english:`to go → I will go`,pronunciation:`ʒiʁe`,example:`J'irai à la boulangerie après le travail.`,exampleTranslation:`I'll go to the bakery after work.`},{french:`faire → je ferai`,english:`to do/make → I will do/make`,pronunciation:`ʒə fəʁe`,example:`Je ferai la vaisselle ce soir.`,exampleTranslation:`I'll do the dishes tonight.`},{french:`pouvoir → je pourrai`,english:`to be able to → I will be able to`,pronunciation:`ʒə puʁʁe`,example:`Je pourrai t'aider demain.`,exampleTranslation:`I'll be able to help you tomorrow.`,funnyNote:`Pouvoir, venir, vouloir, devoir, savoir and voir all get similar irregular stems: pourr-, viendr-, voudr-, devr-, saur-, verr-. Learn them as a block — they show up constantly in real speech.`},{french:`Quand tu arriveras, appelle-moi.`,english:`When you arrive, call me.`,pronunciation:`kɑ̃ ty aʁivʁa apɛl mwa`,funnyNote:`English says "when you arrive" — present tense, even though arriving is still in the future. French refuses: if the event hasn't happened yet, quand takes the futur simple. Quand tu arriveras, never quand tu arrives.`},{french:`je vais manger / je mangerai`,english:`I'm going to eat / I will eat`,pronunciation:`ʒə vɛ mɑ̃ʒe / ʒə mɑ̃ʒʁe`},{french:`Dès qu'il arrivera, on partira.`,english:`As soon as he arrives, we'll leave.`,pronunciation:`dɛ kil aʁivʁa ɔ̃ paʁtiʁa`,funnyNote:`Same trap as quand: dès que, aussitôt que, and tant que all pull the futur simple when the event is still ahead of you. Dès qu'il arrivera — never dès qu'il arrive, if he hasn't arrived yet.`}],exercises:[{type:`multiple-choice`,prompt:`Which is the correct futur simple of "être" for "tu"?`,answer:`tu seras`,options:[`tu seras`,`tu étais`,`tu es`,`tu serais`]},{type:`fill-blank`,prompt:`Nous ___ le temps demain. (We will have time tomorrow)`,answer:`aurons`,hint:`Futur simple of avoir, nous form — irregular stem aur-`},{type:`translation`,prompt:`When you arrive, call me. (Use the futur simple after quand.)`,answer:`Quand tu arriveras, appelle-moi`,hint:`quand + futur simple of arriver, then the imperative appelle-moi`},{type:`multiple-choice`,prompt:`Which sentence correctly translates "When I am big, I'll be a doctor"?`,answer:`Quand je serai grand, je serai médecin`,options:[`Quand je suis grand, je serai médecin`,`Quand je serai grand, je serai médecin`,`Quand je serai grand, je suis médecin`,`Quand je vais être grand, je serai médecin`]},{type:`fill-blank`,prompt:`Dès que tu ___ (finir), appelle-moi. (As soon as you finish, call me)`,answer:`finiras`,hint:`Futur simple of finir after dès que — the event hasn't happened yet`},{type:`translation`,prompt:`I will go to Paris next year. (Use the futur simple.)`,answer:`J'irai à Paris l'année prochaine`,hint:`aller → j'irai, + à (mind the accent) + l'année prochaine`}]},{id:`b1-hypothetical-2`,title:`The Art of Asking Nicely`,subtitle:`Conditionnel présent: politeness, advice, wishes, and gossip you can't confirm.`,xpReward:35,vocab:[{french:`je voudrais`,english:`I would like`,pronunciation:`ʒə vudʁɛ`,example:`Je voudrais un café, s'il vous plaît.`,exampleTranslation:`I'd like a coffee, please.`,funnyNote:`Vouloir's conditional softens a demand into a request. "Je veux un café" sounds like a toddler; "je voudrais un café" sounds like an adult.`},{french:`j'aimerais`,english:`I would love to / I would like to`,pronunciation:`ʒɛmʁɛ`,example:`J'aimerais visiter le Japon un jour.`,exampleTranslation:`I'd love to visit Japan someday.`},{french:`Pourriez-vous... ?`,english:`Could you...? (formal)`,pronunciation:`puʁje vu`,example:`Pourriez-vous répéter, s'il vous plaît ?`,exampleTranslation:`Could you repeat that, please?`,funnyNote:`Pouvoir in the conditional, plus vous — this is about as polite as French gets. Save it for strangers, service staff, and anyone you're trying to impress.`},{french:`tu devrais`,english:`you should`,pronunciation:`ty dəvʁɛ`,example:`Tu devrais dormir plus.`,exampleTranslation:`You should sleep more.`},{french:`à ta place, je...`,english:`in your place, I would...`,pronunciation:`a ta plas ʒə`,example:`À ta place, je démissionnerais.`,exampleTranslation:`In your place, I'd quit.`,funnyNote:`A classic advice frame: state the hypothetical situation, then finish with a conditionnel. No "si" required — "à ta place" already implies it.`},{french:`il serait + adjectif`,english:`it would be + adjective`,pronunciation:`il səʁɛ`,example:`Il serait utile de réserver à l'avance.`,exampleTranslation:`It would be useful to book in advance.`},{french:`selon lui, il... (conditionnel)`,english:`according to him, he supposedly...`,pronunciation:`səlɔ̃ lɥi il`,example:`Selon lui, la réunion serait annulée.`,exampleTranslation:`According to him, the meeting has apparently been cancelled.`,funnyNote:`French news uses the conditionnel to report unverified information. "Le président serait en visite" means "the president is reportedly visiting" — not confirmed, don't quote it as fact.`},{french:`j'aurais / je serais / je ferais`,english:`I would have / I would be / I would do`,pronunciation:`ʒoʁɛ / ʒə səʁɛ / ʒə fəʁɛ`,funnyNote:`Same irregular stems as the futur simple (aur-, ser-, fer-...) but with imparfait endings: -ais, -ais, -ait, -ions, -iez, -aient. If you know the future stem, the conditional is free.`}],exercises:[{type:`multiple-choice`,prompt:`Which is the correct conditionnel of "avoir" for "tu"?`,answer:`tu aurais`,options:[`tu auras`,`tu aurais`,`tu avais`,`tu aies`]},{type:`fill-blank`,prompt:`Tu ___ faire attention. (You should be careful)`,answer:`devrais`,hint:`Conditionnel of devoir, tu form`},{type:`translation`,prompt:`I would like a coffee, please. (Use je voudrais.)`,answer:`Je voudrais un café, s'il vous plaît`,hint:`je voudrais + un café (mind the accent) + s'il vous plaît`},{type:`multiple-choice`,prompt:`Which sentence reports news French journalists haven't confirmed yet?`,answer:`Le président serait en visite.`,options:[`Le président est en visite.`,`Le président serait en visite.`,`Le président sera en visite.`,`Le président a été en visite.`]},{type:`fill-blank`,prompt:`___-vous m'aider ? (Could you help me?)`,answer:`Pourriez`,hint:`Conditionnel of pouvoir + vous, inverted for a question`},{type:`translation`,prompt:`In your place, I would quit. (Use à ta place, je + conditionnel of démissionner.)`,answer:`À ta place, je démissionnerais`,hint:`à (mind the accent) + ta place, je + démissionnerais`}]},{id:`b1-hypothetical-3`,title:`Si J'étais Riche`,subtitle:`Si-clauses: présents pair with futurs, imparfaits pair with conditionnels — never mix them.`,xpReward:35,vocab:[{french:`si + présent → futur`,english:`if + present → future`,pronunciation:`si`,example:`Si tu viens, je serai content.`,exampleTranslation:`If you come, I'll be happy.`,funnyNote:`The most common si-clause: si + présent in the "if" part, futur simple (or présent, or impératif) in the result. Never conditionnel after si — see the next entry.`},{french:`jamais de conditionnel après si`,english:`never conditionnel right after si`,pronunciation:`ʒamɛ də kɔ̃disjɔnɛl apʁɛ si`,example:`Si j'avais de l'argent...`,exampleTranslation:`If I had money... (never "si j'aurais")`,funnyNote:`This is THE trap. "Si j'aurais" is one of the most common mistakes English speakers make — French never puts a conditionnel directly after si meaning "if". Présent or imparfait only.`},{french:`si + imparfait → conditionnel`,english:`if + imperfect → conditional`,pronunciation:`si`,example:`Si j'avais de l'argent, je voyagerais.`,exampleTranslation:`If I had money, I would travel.`},{french:`si + présent → impératif`,english:`if + present → command`,pronunciation:`si`,example:`Si tu as faim, mange quelque chose.`,exampleTranslation:`If you're hungry, eat something.`},{french:`même si + indicatif`,english:`even if + indicative`,pronunciation:`mɛm si`,example:`Même si tu pars tôt, tu seras en retard.`,exampleTranslation:`Even if you leave early, you'll be late.`,funnyNote:`Même si always takes the indicatif (présent, futur, imparfait...), never the subjonctif — unlike bien que, which demands the subjonctif. Easy to mix up once you've met bien que.`},{french:`Si j'étais toi...`,english:`If I were you...`,pronunciation:`si ʒetɛ twa`,example:`Si j'étais toi, j'accepterais l'offre.`,exampleTranslation:`If I were you, I'd accept the offer.`,funnyNote:`Interchangeable with "à ta place" for giving advice. "Étais" here is just the imparfait of être — French doesn't have a separate subjunctive-like "were" form the way English does.`},{french:`Si seulement...`,english:`If only...`,pronunciation:`si sœlmɑ̃`,example:`Si seulement j'avais du temps !`,exampleTranslation:`If only I had time!`,funnyNote:`A wish, often left hanging with no result clause at all — just si seulement + imparfait and a sigh.`}],exercises:[{type:`multiple-choice`,prompt:`Which sentence is correct?`,answer:`Si j'avais de l'argent, je voyagerais.`,options:[`Si j'aurais de l'argent, je voyagerais.`,`Si j'avais de l'argent, je voyagerais.`,`Si j'ai de l'argent, je voyagerais.`,`Si j'avais de l'argent, je voyage.`]},{type:`fill-blank`,prompt:`Si tu ___ faim, mange quelque chose. (If you're hungry, eat something)`,answer:`as`,hint:`Présent of avoir, tu form — si + présent here`},{type:`translation`,prompt:`If it rains, we will stay home. (Use si + présent + futur simple.)`,answer:`S'il pleut, nous resterons à la maison`,hint:`s'il pleut + nous resterons + à (mind the accent) + la maison`},{type:`multiple-choice`,prompt:`Which mood follows "même si"?`,answer:`L'indicatif`,options:[`Le subjonctif`,`Le conditionnel`,`L'indicatif`,`L'impératif`]},{type:`fill-blank`,prompt:`Si j'___ le temps, je t'appellerais. (If I had time, I would call you)`,answer:`avais`,hint:`Imparfait of avoir — si + imparfait triggers the conditionnel in the result`},{type:`translation`,prompt:`If I were rich, I would travel. (Use si + imparfait + conditionnel.)`,answer:`Si j'étais riche, je voyagerais`,hint:`si + imparfait of être + conditionnel of voyager`}]}],isA1:!1,isBeyondA1:!1,isB1:!0},{id:`b1-workplace`,slug:`b1-workplace`,title:`Bureau Politics`,emoji:`💼`,tagline:`French at Work`,funnyDescription:`French professional life runs on formulas. Miss one in an email and everyone notices. Nail them and you sound like you belong.`,color:`#457B9D`,accentColor:`#6b9cc0`,lessons:[{id:`b1-workplace-1`,title:`The Email Formula`,subtitle:`Skip "Madame, Monsieur" and the whole office silently judges you.`,xpReward:35,vocab:[{french:`Madame, Monsieur,`,english:`Dear Sir or Madam, (recipient unknown)`,pronunciation:`madam məsjø`,funnyNote:`Use this when you don't know who will read the email. Note the comma, never an exclamation mark — and no "Cher/Chère", which would feel oddly intimate for a total stranger.`},{french:`Bonjour Madame Dupont,`,english:`Hello Ms. Dupont, (once you know the name)`,pronunciation:`bɔ̃ʒuʁ madam dypɔ̃`,example:`Bonjour Madame Dupont, suite à notre appel...`,exampleTranslation:`Hello Ms. Dupont, following our call...`},{french:`suite à...`,english:`following... / further to...`,pronunciation:`sɥit a`,example:`Suite à notre réunion, voici le compte-rendu.`,exampleTranslation:`Following our meeting, here is the summary.`},{french:`je me permets de...`,english:`I am taking the liberty of... / allow me to...`,pronunciation:`ʒə mə pɛʁmɛ də`,example:`Je me permets de vous relancer au sujet du dossier.`,exampleTranslation:`I am taking the liberty of following up on the file.`,funnyNote:`A polite way to justify writing at all, as if you need permission to take up someone's time. Very French, very useful for a first contact or a reminder email.`},{french:`vous trouverez ci-joint...`,english:`please find attached...`,pronunciation:`vu tʁuvʁe siʒwɛ̃`,example:`Vous trouverez ci-joint le devis demandé.`,exampleTranslation:`Please find attached the requested quote.`,funnyNote:`Purists agree "ci-joint" with the noun in very formal writing (ci-jointe la facture), but "vous trouverez ci-joint" left invariable, as shown here, is always safe and what you'll see most often.`},{french:`n'hésitez pas à...`,english:`don't hesitate to...`,pronunciation:`neizite pa a`,example:`N'hésitez pas à me contacter pour toute question.`,exampleTranslation:`Don't hesitate to contact me with any questions.`},{french:`dans l'attente de votre réponse`,english:`looking forward to your reply`,pronunciation:`dɑ̃ latɑ̃t də vɔtʁ ʁepɔ̃s`,example:`Dans l'attente de votre réponse, bien cordialement.`,exampleTranslation:`Looking forward to your reply, best regards.`},{french:`cordialement / bien cordialement / bien à vous`,english:`regards / kind regards / best (warmer)`,pronunciation:`kɔʁdjalmɑ̃ / bjɛ̃ kɔʁdjalmɑ̃ / bjɛ̃ a vu`,funnyNote:`A real register ladder: "cordialement" is the neutral default, "bien cordialement" adds a touch of warmth, and "bien à vous" is for people you actually know. Never end with "salut" in a professional email — it clashes badly with everything before it.`},{french:`Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.`,english:`Yours faithfully, (extremely formal closing)`,pronunciation:`ʒə vu pʁi dagʁee madam məsjø lɛkspʁɛsjɔ̃ də me salytasjɔ̃ distɛ̃ge`,funnyNote:`Still alive in postal letters, official administration replies, and legal correspondence — but in everyday email it reads as stiff, even sarcastic. Save it for the préfecture, not for a colleague.`}],exercises:[{type:`multiple-choice`,prompt:`You don't know the name of the person you're emailing at a company. Which opening is correct?`,answer:`Madame, Monsieur,`,options:[`Salut,`,`Madame, Monsieur,`,`Chers collègues,`,`Coucou,`]},{type:`fill-blank`,prompt:`___ notre conversation téléphonique, je vous confirme le rendez-vous. (Following our phone conversation)`,answer:`Suite à`,hint:`A chunk meaning "following" — always followed by a noun. Mind the accent on à.`},{type:`translation`,prompt:`Translate: "Looking forward to your reply." Use dans l'attente de.`,answer:`Dans l'attente de votre réponse`,hint:`dans l'attente de + votre réponse`},{type:`fill-blank`,prompt:`N'hésitez pas ___ me contacter. (Don't hesitate to contact me)`,answer:`à`,hint:`n'hésitez pas is always followed by à + infinitive. Mind the accent on à.`},{type:`multiple-choice`,prompt:`You're writing a first email to a supplier you've never met. Which closing is the safe, neutral choice?`,answer:`Cordialement,`,options:[`Bisous,`,`Cordialement,`,`Bien à vous,`,`À plus,`]},{type:`translation`,prompt:`Translate: "Please find attached the document." Use vous trouverez ci-joint.`,answer:`Vous trouverez ci-joint le document`,hint:`vous trouverez ci-joint + le document`}]},{id:`b1-workplace-2`,title:`Meetings, Calls, and Surviving Both`,subtitle:`Half of office French is knowing when to say "ne quittez pas" and mean it.`,xpReward:35,vocab:[{french:`une réunion`,english:`a meeting`,pronunciation:`yn ʁeynjɔ̃`,example:`On a une réunion à 14h.`,exampleTranslation:`We have a meeting at 2pm.`},{french:`l'ordre du jour`,english:`the agenda`,pronunciation:`lɔʁdʁ dy ʒuʁ`,example:`Voici l'ordre du jour de la réunion.`,exampleTranslation:`Here is the agenda for the meeting.`},{french:`faire le point`,english:`to take stock / to review progress`,pronunciation:`fɛʁ lə pwɛ̃`,example:`On va faire le point sur le projet.`,exampleTranslation:`We're going to review progress on the project.`},{french:`prendre la parole`,english:`to take the floor / to start speaking`,pronunciation:`pʁɑ̃dʁ la paʁɔl`,example:`Je peux prendre la parole ?`,exampleTranslation:`May I take the floor?`,funnyNote:`You don't literally hold anything — "la parole" is "speech" itself. In French you "take" the right to speak, you don't "have" it.`},{french:`je vous passe... / ne quittez pas`,english:`I'll put you through to... / please hold`,pronunciation:`ʒə vu pas / nə kite pa`,example:`Je vous passe le service comptabilité, ne quittez pas.`,exampleTranslation:`I'll put you through to the accounting department, please hold.`,funnyNote:`"Ne quittez pas" literally means "don't leave" — it's the fixed phrase before putting someone on hold. Saying "attendez" instead sounds like an order.`},{french:`pourriez-vous répéter ?`,english:`could you repeat that?`,pronunciation:`puʁje vu ʁepete`,example:`Pourriez-vous répéter, s'il vous plaît ? La ligne est mauvaise.`,exampleTranslation:`Could you repeat that, please? The line is bad.`,funnyNote:`"Pourriez-vous" is the conditional of pouvoir — the same softening trick you use anywhere in formal French. On the phone, where your face and tone are invisible, this politeness carries even more weight than usual.`},{french:`je vous rappelle`,english:`I'll call you back`,pronunciation:`ʒə vu ʁapɛl`,example:`Je vous rappelle dans dix minutes.`,exampleTranslation:`I'll call you back in ten minutes.`,funnyNote:`Don't confuse "rappeler" (to call back) with "se rappeler" (to remember) — same root, completely different job.`},{french:`on se tient au courant`,english:`we'll keep each other posted`,pronunciation:`ɔ̃ sə tjɛ̃ o kuʁɑ̃`,example:`Parfait, on se tient au courant.`,exampleTranslation:`Great, we'll keep each other posted.`},{french:`la pause-café / la pause déjeuner`,english:`the coffee break / the lunch break`,pronunciation:`la poz kafe / la poz deʒøne`,funnyNote:`The pause déjeuner is often a full hour, sometimes more, and treated as close to sacred — scheduling a meeting over lunch without asking first can raise eyebrows.`}],exercises:[{type:`multiple-choice`,prompt:`Your colleague says "On va faire le point sur le projet." What are they about to do?`,answer:`Review progress on the project`,options:[`Start a new project`,`Review progress on the project`,`Cancel the project`,`Take a break from the project`]},{type:`fill-blank`,prompt:`___-vous répéter, s'il vous plaît ? (Could you repeat, please?)`,answer:`Pourriez`,hint:`The conditional of pouvoir, inverted with vous.`},{type:`translation`,prompt:`Translate: "I'll call you back in ten minutes." Use je vous rappelle.`,answer:`Je vous rappelle dans dix minutes`,hint:`je vous rappelle + dans + the amount of time`},{type:`multiple-choice`,prompt:`On the phone, what does "ne quittez pas" mean?`,answer:`Please hold`,options:[`Please hold`,`Please hang up`,`Please speak louder`,`Please call back later`]},{type:`fill-blank`,prompt:`Je peux ___ la parole ? (May I take the floor?)`,answer:`prendre`,hint:`prendre la parole = to take the floor.`},{type:`translation`,prompt:`Translate: "We'll keep each other posted." Use on se tient au courant.`,answer:`On se tient au courant`,hint:`on se tient au courant — a fixed phrase`}]},{id:`b1-workplace-3`,title:`Getting Hired, En Français`,subtitle:`A CDI is the holy grail — learn to talk your way into one.`,xpReward:35,vocab:[{french:`un poste`,english:`a position / a job`,pronunciation:`œ̃ pɔst`,example:`Le poste est toujours disponible ?`,exampleTranslation:`Is the position still available?`},{french:`une candidature`,english:`an application`,pronunciation:`yn kɑ̃didatyʁ`,example:`J'ai envoyé ma candidature hier.`,exampleTranslation:`I sent my application yesterday.`,funnyNote:`Not "une application" — that false friend means a phone app in French. "Postuler" (to apply) and "une candidature" (an application) are the words you actually need.`},{french:`un entretien (d'embauche)`,english:`a (job) interview`,pronunciation:`œ̃ nɑ̃tʁətjɛ̃ dɑ̃boʃ`,example:`J'ai un entretien d'embauche demain matin.`,exampleTranslation:`I have a job interview tomorrow morning.`},{french:`un stage`,english:`an internship`,pronunciation:`œ̃ staʒ`,funnyNote:`"Un stage" is an internship, not a theatrical "stage" — that false friend trips up a lot of English speakers reading French job postings.`},{french:`un CDI / un CDD`,english:`a permanent contract / a fixed-term contract`,pronunciation:`œ̃ sedei / œ̃ sedede`,example:`C'est un CDI ou un CDD ?`,exampleTranslation:`Is it a permanent contract or a fixed-term one?`,funnyNote:`CDI (contrat à durée indéterminée) is the prized permanent contract; CDD (contrat à durée déterminée) has a fixed end date. The distinction matters enormously in France — job security, loans, even apartment rentals often hinge on having a CDI.`},{french:`une lettre de motivation`,english:`a cover letter`,pronunciation:`yn lɛtʁ də motivasjɔ̃`,example:`Chaque candidature demande une lettre de motivation.`,exampleTranslation:`Every application requires a cover letter.`},{french:`les points forts / les points faibles`,english:`strengths / weaknesses`,pronunciation:`le pwɛ̃ fɔʁ / le pwɛ̃ fɛbl`,example:`Quels sont vos points forts et vos points faibles ?`,exampleTranslation:`What are your strengths and weaknesses?`},{french:`être motivé / motivée`,english:`to be motivated`,pronunciation:`ɛtʁ motive`,example:`Je suis motivé pour ce poste.`,exampleTranslation:`I am motivated for this position.`,funnyNote:`The adjective agrees with you: "motivé" if you're a man, "motivée" if you're a woman. Job ads write "motivé(e)" to cover both — but in speech, or in an exercise answer, pick the one form that matches. Never mash the two together.`},{french:`depuis / pendant + passé composé`,english:`since/for (still true now) vs. for (a finished period, with passé composé)`,pronunciation:`dəpɥi / pɑ̃dɑ̃`,example:`Je travaille ici depuis trois ans, mais j'ai travaillé chez Orange pendant deux ans.`,exampleTranslation:`I've been working here for three years, but I worked at Orange for two years.`,funnyNote:`The classic trap: English "I have worked here for three years" pulls you toward the passé composé. But if it's still true now, French wants the present tense + depuis. Passé composé + pendant is for a closed chapter of your life.`}],exercises:[{type:`multiple-choice`,prompt:`A "CDD" in France is:`,answer:`A fixed-term contract`,options:[`A permanent contract`,`A fixed-term contract`,`An unpaid internship`,`A freelance agreement`]},{type:`fill-blank`,prompt:`J'ai un ___ d'embauche demain. (a job interview)`,answer:`entretien`,hint:`entretien = interview.`},{type:`translation`,prompt:`Translate, as a man: "I am motivated for this position." Use je suis motivé.`,answer:`Je suis motivé pour ce poste`,hint:`je suis + motivé (no extra ending) + pour ce poste`},{type:`fill-blank`,prompt:`Chaque candidature demande une lettre de ___. (cover letter)`,answer:`motivation`,hint:`lettre de motivation = cover letter.`},{type:`multiple-choice`,prompt:`What is "une candidature"?`,answer:`A job application`,options:[`A phone app`,`A job application`,`A work meeting`,`A job interview`]},{type:`translation`,prompt:`Translate: "I've been working here for three years." Use depuis + the present tense.`,answer:`Je travaille ici depuis trois ans`,hint:`present tense verb + depuis + trois ans, no passé composé`}]}],isA1:!1,isBeyondA1:!1,isB1:!0},{id:`b2-subjunctive`,slug:`b2-subjunctive`,title:`The Mood Swing`,emoji:`🎭`,tagline:`The Subjunctive`,funnyDescription:`Not a tense — a mood. French slips into it whenever reality becomes optional: wishes, doubts, fears and "bien que".`,color:`#B5838D`,accentColor:`#c9a0a8`,lessons:[{id:`b2-subjunctive-1`,title:`Meet the Ils-Stem`,subtitle:`Steal the "ils" form, chop off "-ent", and you've built most of the subjunctive already.`,xpReward:40,vocab:[{french:`que je parle / que nous parlions`,english:`that I speak / that we speak (subjunctive)`,pronunciation:`kə ʒə paʁl / kə nu paʁljɔ̃`,example:`Il faut que je parle au directeur.`,exampleTranslation:`I need to speak to the director.`},{french:`que je vienne / que nous venions`,english:`that I come / that we come (subjunctive)`,pronunciation:`kə ʒə vjɛn / kə nu vənjɔ̃`,example:`Il faut que tu viennes ce soir.`,exampleTranslation:`You need to come tonight.`,funnyNote:`Two different stems in one verb: vienn- for je/tu/il/ils (from ils viennent), but ven- for nous/vous — which is why "que nous venions" looks exactly like the imperfect "nous venions". Context tells them apart.`},{french:`que je prenne / que nous prenions`,english:`that I take / that we take (subjunctive)`,pronunciation:`kə ʒə pʁɛn / kə nu pʁənjɔ̃`,example:`Il faut que je prenne le train de huit heures.`,exampleTranslation:`I need to take the eight o'clock train.`},{french:`que je boive / que nous buvions`,english:`that I drink / that we drink (subjunctive)`,pronunciation:`kə ʒə bwav / kə nu byvjɔ̃`,example:`Elle veut que je boive de l'eau.`,exampleTranslation:`She wants me to drink some water.`},{french:`que je doive / que nous devions`,english:`that I must / that we must (subjunctive)`,pronunciation:`kə ʒə dwav / kə nu dəvjɔ̃`,example:`Il est possible qu'elle doive partir tôt.`,exampleTranslation:`It's possible she has to leave early.`},{french:`que je sois / que nous soyons`,english:`that I am / that we are (subjunctive)`,pronunciation:`kə ʒə swa / kə nu swajɔ̃`,example:`Il faut que je sois à l'heure.`,exampleTranslation:`I need to be on time.`,funnyNote:`Être is irregular from the ground up: the stem isn't built from "ils sont" at all. Learn sois / soyons / soyez as their own block.`},{french:`que j'aie / que nous ayons`,english:`that I have / that we have (subjunctive)`,pronunciation:`kə ʒe / kə nu zajɔ̃`,example:`Il faut que j'aie mon passeport sur moi.`,exampleTranslation:`I need to have my passport on me.`},{french:`que je fasse`,english:`that I do / make (subjunctive)`,pronunciation:`kə ʒə fas`,funnyNote:`Faire uses one stem, fass-, for all six persons — no nous/vous switch like venir or prendre. Que je fasse, que nous fassions: same family throughout.`},{french:`que j'aille / que nous allions`,english:`that I go / that we go (subjunctive)`,pronunciation:`kə ʒaj / kə nu zaljɔ̃`,funnyNote:`Aller splits like venir — aill- for je/tu/il/ils, all- for nous/vous — but it does NOT come from "ils vont". It's simply irregular and has to be memorised on its own.`}],exercises:[{type:`multiple-choice`,prompt:`The subjunctive stem for "que je parle" comes from which verb form?`,answer:`ils parlent`,options:[`je parle`,`nous parlons`,`ils parlent`,`tu parles`]},{type:`fill-blank`,prompt:`Il faut que nous ___ patients. (We need to be patient)`,answer:`soyons`,hint:`être au subjonctif, nous = soyons`},{type:`translation`,prompt:`Say "I need you to come." Use il faut que + venir, tu form.`,answer:`Il faut que tu viennes`,hint:`venir au subjonctif, tu = viennes`},{type:`multiple-choice`,prompt:`Which is the correct "nous" subjunctive form of venir?`,answer:`venions`,options:[`venions`,`viennions`,`venons`,`viennent`]},{type:`fill-blank`,prompt:`Il est possible qu'elle ___ partir tôt. (It's possible she has to leave early)`,answer:`doive`,hint:`devoir au subjonctif, elle = doive`},{type:`translation`,prompt:`Say "that we have time." Use il faut que + avoir, nous form.`,answer:`Il faut que nous ayons le temps`,hint:`avoir au subjonctif, nous = ayons`}]},{id:`b2-subjunctive-2`,title:`What Sets It Off`,subtitle:`Wanting, doubting, fearing, hoping badly enough — the subjunctive has a trigger list, and it's longer than you'd like.`,xpReward:40,vocab:[{french:`il faut que`,english:`it is necessary that / you have to`,pronunciation:`il fo kə`,example:`Il faut que tu finisses ce rapport.`,exampleTranslation:`You have to finish this report.`,funnyNote:`This impersonal trigger has no subject of its own — "il" is just a placeholder. It is followed by the subjunctive without exception.`},{french:`vouloir que`,english:`to want (someone) to`,pronunciation:`vulwaʁ kə`,example:`Je veux que tu viennes avec nous.`,exampleTranslation:`I want you to come with us.`,funnyNote:`Only use "vouloir que" when the wanter and the doer are different people. Same subject → infinitive: "je veux partir", never *"je veux que je parte".`},{french:`je suis content(e) que`,english:`I'm glad that`,pronunciation:`ʒə sɥi kɔ̃tɑ̃ kə`,example:`Je suis content que tu sois là.`,exampleTranslation:`I'm glad you're here.`},{french:`avoir peur que... ne`,english:`to be afraid that`,pronunciation:`avwaʁ pœʁ kə... nə`,example:`J'ai peur qu'il ne pleuve.`,exampleTranslation:`I'm afraid it will rain.`,funnyNote:`That "ne" isn't a negation — it's the ne explétif, a ghost that shows up after peur que, avant que and a few others in careful French. Drop it in casual speech; it changes nothing in meaning.`},{french:`douter que`,english:`to doubt that`,pronunciation:`dute kə`,example:`Je doute qu'il vienne.`,exampleTranslation:`I doubt he's coming.`},{french:`bien que`,english:`although`,pronunciation:`bjɛ̃ kə`,example:`Bien qu'il soit fatigué, il continue.`,exampleTranslation:`Although he's tired, he keeps going.`,funnyNote:`Bien que always takes the subjunctive, even when the fact is 100% true — the mood is triggered by the conjunction itself, not by how certain the fact is.`},{french:`pour que`,english:`so that`,pronunciation:`puʁ kə`,example:`Elle parle lentement pour que je comprenne.`,exampleTranslation:`She speaks slowly so that I understand.`,funnyNote:`Same-subject rule again: if one person does both actions, switch to "pour + infinitif" — "je travaille pour réussir", not *"pour que je réussisse".`},{french:`avant que`,english:`before`,pronunciation:`avɑ̃ kə`,example:`Appelle-moi avant que tu partes.`,exampleTranslation:`Call me before you leave.`},{french:`à moins que / sans que`,english:`unless / without`,pronunciation:`a mwɛ̃ kə / sɑ̃ kə`,example:`Je viendrai à moins qu'il pleuve.`,exampleTranslation:`I'll come unless it rains.`}],exercises:[{type:`multiple-choice`,prompt:`Same subject, wanting to leave — which sentence is correct?`,answer:`Je veux partir`,options:[`Je veux que je parte`,`Je veux partir`,`Je veux que tu partes`,`Je veux que pars`]},{type:`fill-blank`,prompt:`J'ai peur qu'il ne ___ demain. (I'm afraid it will rain tomorrow)`,answer:`pleuve`,hint:`pleuvoir au subjonctif = qu'il pleuve; ce "ne" n'est pas une négation`},{type:`translation`,prompt:`Say "I want you to come." Use vouloir que + venir, tu form.`,answer:`Je veux que tu viennes`,hint:`venir au subjonctif, tu = viennes`},{type:`multiple-choice`,prompt:`Which sentence correctly uses "bien que"?`,answer:`Bien qu'il soit tard, elle sort quand même.`,options:[`Bien qu'il est tard, elle sort quand même.`,`Bien qu'il soit tard, elle sort quand même.`,`Bien qu'il sera tard, elle sort quand même.`,`Bien qu'il était tard, elle sort quand même.`]},{type:`fill-blank`,prompt:`Il doute que nous ___ raison. (He doubts that we are right)`,answer:`ayons`,hint:`avoir au subjonctif, nous = ayons`},{type:`translation`,prompt:`Say "without them knowing." Use sans que + savoir, ils form.`,answer:`Sans qu'ils sachent`,hint:`savoir au subjonctif, ils = sachent`}]},{id:`b2-subjunctive-3`,title:`Fact, Opinion, or Wishful Thinking?`,subtitle:`Same verb, different mood, depending on how sure you actually are.`,xpReward:40,vocab:[{french:`penser que / croire que`,english:`to think / believe that`,pronunciation:`pɑ̃se kə / kʁwaʁ kə`,example:`Je pense qu'il a raison.`,exampleTranslation:`I think he's right.`},{french:`ne pas penser que / ne pas croire que`,english:`to not think / not believe that`,pronunciation:`nə pa pɑ̃se kə / nə pa kʁwaʁ kə`,example:`Je ne pense pas qu'il ait raison.`,exampleTranslation:`I don't think he's right.`,funnyNote:`Negate the opinion and the mood flips: doubt, even just implied doubt, pulls in the subjunctive.`},{french:`penses-tu que... ? / crois-tu que... ?`,english:`do you think that...?`,pronunciation:`pɑ̃s ty kə / kʁwa ty kə`,example:`Crois-tu qu'il vienne ?`,exampleTranslation:`Do you think he's coming?`},{french:`espérer que`,english:`to hope that`,pronunciation:`ɛspeʁe kə`,example:`J'espère qu'il fera beau demain.`,exampleTranslation:`I hope the weather will be nice tomorrow.`,funnyNote:`Espérer que is the famous exception: it FEELS like a wish, so learners expect the subjunctive, but it always takes the indicative. Non-negotiable.`},{french:`après que`,english:`after`,pronunciation:`apʁɛ kə`,example:`Il est parti après qu'elle est arrivée.`,exampleTranslation:`He left after she arrived.`,funnyNote:`You will hear French people say "après qu'elle soit arrivée" constantly — it's a famous, widespread error. Grammar books insist on the indicative, since the event already happened; it isn't hypothetical.`},{french:`il est probable que`,english:`it is likely that`,pronunciation:`il ɛ pʁɔbabl kə`,example:`Il est probable qu'il pleuvra ce soir.`,exampleTranslation:`It will probably rain tonight.`},{french:`il est possible que`,english:`it is possible that`,pronunciation:`il ɛ pɔsibl kə`,example:`Il est possible qu'il pleuve ce soir.`,exampleTranslation:`It might rain tonight.`,funnyNote:`"Probable" and "possible" look like twins but split the mood: probable leans toward certainty (indicative), possible leans toward uncertainty (subjunctive).`},{french:`le seul / le premier / le dernier... qui`,english:`the only / first / last one who`,pronunciation:`lə sœl / lə pʁəmje / lə dɛʁnje ki`,example:`C'est le seul restaurant qui soit ouvert.`,exampleTranslation:`It's the only restaurant that's open.`,funnyNote:`Superlatives and restrictive expressions (seul, premier, dernier, unique) treat the claim as subjective, so the relative clause after "qui" switches to the subjunctive.`}],exercises:[{type:`multiple-choice`,prompt:`Which is correct for "I think he's right" (a plain, confident opinion)?`,answer:`Je pense qu'il a raison.`,options:[`Je pense qu'il a raison.`,`Je pense qu'il ait raison.`,`Je pense qu'il aie raison.`,`Je pense qu'il aurait raison.`]},{type:`fill-blank`,prompt:`Il est possible qu'elle ___ en retard. (It's possible she is late)`,answer:`soit`,hint:`il est possible que + subjonctif d'être`},{type:`translation`,prompt:`Say "He is the only one who understands." Use le seul qui + comprendre.`,answer:`Il est le seul qui comprenne`,hint:`comprendre au subjonctif, il = comprenne`},{type:`multiple-choice`,prompt:`Which is the grammatically correct sentence (not the common spoken "mistake")?`,answer:`Après qu'il est parti, elle a pleuré.`,options:[`Après qu'il soit parti, elle a pleuré.`,`Après qu'il est parti, elle a pleuré.`,`Après qu'il était parti, elle a pleuré.`,`Après qu'il fût parti, elle a pleuré.`]},{type:`fill-blank`,prompt:`Il est probable qu'elle ___ en retard. (She is probably late)`,answer:`est`,hint:`il est probable que + indicatif — contraste avec il est possible que`},{type:`translation`,prompt:`Say "I don't think she's coming." Use ne pas penser que + venir.`,answer:`Je ne pense pas qu'elle vienne`,hint:`négation de penser que + subjonctif; venir, elle = vienne`}]}],isA1:!1,isBeyondA1:!1,isB2:!0},{id:`b2-argumentation`,slug:`b2-argumentation`,title:`Actually, Monsieur…`,emoji:`⚖️`,tagline:`Debate & Argumentation`,funnyDescription:`French schools drill thèse, antithèse, synthèse into every teenager. This unit teaches you to argue like you survived it too.`,color:`#D62828`,accentColor:`#e85555`,lessons:[{id:`b2-argumentation-1`,title:`Actually, Monsieur...`,subtitle:`How to structure an argument so it sounds like you went to a French lycée.`,xpReward:40,vocab:[{french:`tout d'abord`,english:`first of all / first`,pronunciation:`tu dabɔʁ`,example:`Tout d'abord, il faut définir les termes du débat.`,exampleTranslation:`First of all, we need to define the terms of the debate.`},{french:`en premier lieu`,english:`in the first place`,pronunciation:`ɑ̃ pʁəmje ljø`,funnyNote:`The dressier cousin of "tout d'abord" — swap it in when your teacher, or your dissertation, needs to sound more formal.`},{french:`en outre`,english:`furthermore / moreover`,pronunciation:`ɑ̃n utʁ`,example:`En outre, cette mesure coûterait cher à l'État.`,exampleTranslation:`Furthermore, this measure would cost the State a lot.`},{french:`par ailleurs`,english:`besides / moreover (shifting focus)`,pronunciation:`paʁ ajœʁ`,funnyNote:`"En outre" piles onto the SAME point; "par ailleurs" pivots to a related but separate one. Native writers keep them apart — you should too.`},{french:`de surcroît`,english:`what's more / on top of that`,pronunciation:`də syʁkʁwa`,funnyNote:`Strictly written and rather literary. Say it out loud at a dinner party and people will assume you're quoting Le Monde.`},{french:`en revanche`,english:`on the other hand / conversely`,pronunciation:`ɑ̃ ʁəvɑ̃ʃ`,example:`En revanche, les partisans du projet soulignent ses bénéfices écologiques.`,exampleTranslation:`On the other hand, supporters of the project highlight its ecological benefits.`,funnyNote:`Sharper than "mais", more neutral than "par contre" (which purists still frown on in formal writing). "En revanche" is the safe, elegant choice in an essay.`},{french:`d'une part... d'autre part`,english:`on the one hand... on the other hand`,pronunciation:`dyn paʁ... dotʁ paʁ`,example:`D'une part, le télétravail réduit la fatigue ; d'autre part, il isole certains salariés.`,exampleTranslation:`On the one hand, remote work reduces fatigue; on the other, it isolates some employees.`},{french:`en conclusion / pour conclure`,english:`in conclusion / to conclude`,pronunciation:`ɑ̃ kɔ̃klyzjɔ̃ / puʁ kɔ̃klyʁ`,example:`En conclusion, ce débat reste ouvert.`,exampleTranslation:`In conclusion, this debate remains open.`},{french:`le plan thèse-antithèse-synthèse`,english:`the thesis-antithesis-synthesis essay plan`,pronunciation:`lə plɑ̃ tɛz ɑ̃titɛz sɛ̃tɛz`,funnyNote:`Every French lycéen is drilled on this: paragraph one defends a position, paragraph two challenges it, paragraph three reconciles the two. It's less "pick a side" and more "prove you can hold two sides at once" — the whole cultural logic behind "certes... mais".`}],exercises:[{type:`multiple-choice`,prompt:`Which connector below signals a genuine contrast rather than simply adding another point?`,answer:`en revanche`,options:[`en outre`,`par ailleurs`,`en revanche`,`de surcroît`]},{type:`fill-blank`,prompt:`Cette réforme est complexe. ___, elle risque de coûter cher. (on top of that)`,answer:`De surcroît`,hint:`The literary, slightly heavier way to say "in addition" — rare in speech, common in written argument.`},{type:`translation`,prompt:`Translate using "en outre": "Furthermore, this argument is not new."`,answer:`En outre, cet argument n'est pas nouveau.`,hint:`"En outre" + subject + verb, exactly like "furthermore".`},{type:`multiple-choice`,prompt:`Complete the structuring pair: "D'une part... ___"`,answer:`d'autre part`,options:[`d'autre part`,`par ailleurs`,`en revanche`,`de surcroît`]},{type:`fill-blank`,prompt:`___, il faut analyser les causes du problème. (in the first place)`,answer:`En premier lieu`,hint:`The more formal cousin of "tout d'abord", favoured in written essays.`},{type:`translation`,prompt:`Translate using "en conclusion": "In conclusion, this argument is convincing."`,answer:`En conclusion, cet argument est convaincant.`,hint:`Opens the closing paragraph of an essay.`}]},{id:`b2-argumentation-2`,title:`Yes, But...`,subtitle:`Concede the point, then take it apart — the French dissertation's favourite move.`,xpReward:40,vocab:[{french:`certes... mais`,english:`granted... but`,pronunciation:`sɛʁt mɛ`,example:`Certes, le train est cher, mais il est rapide.`,exampleTranslation:`Granted, the train is expensive, but it's fast.`,funnyNote:`The single most drilled move in French argumentation: concede a point so you look fair-minded, then pivot straight into your real argument.`},{french:`bien que + subjonctif`,english:`although (+ subjunctive)`,pronunciation:`bjɛ̃ kə`,example:`Bien qu'il soit tard, nous continuons le débat.`,exampleTranslation:`Although it's late, we continue the debate.`,funnyNote:`"Bien que" ALWAYS takes the subjunctive, no exceptions — even though nothing about "it's late" is remotely uncertain. The trigger is the word itself, not the meaning.`},{french:`même si + indicatif`,english:`even if (+ indicative)`,pronunciation:`mɛm si`,example:`Même s'il pleut, la manifestation aura lieu.`,exampleTranslation:`Even if it rains, the protest will take place.`,funnyNote:`The trap: "bien que" and "même si" translate almost identically, but "même si" stays firmly in the indicative. Mix them up and a French examiner will notice instantly.`},{french:`il n'en reste pas moins que`,english:`the fact remains that / nevertheless`,pronunciation:`il nɑ̃ ʁɛst pa mwɛ̃ kə`,example:`Il n'en reste pas moins que la réforme reste impopulaire.`,exampleTranslation:`The fact remains that the reform is still unpopular.`},{french:`force est de constater que`,english:`one must admit that / it has to be said that`,pronunciation:`fɔʁs ɛ də kɔ̃state kə`,example:`Force est de constater que le système a échoué.`,exampleTranslation:`One must admit that the system has failed.`,funnyNote:`A favourite of journalists and examiners alike — it announces an uncomfortable conclusion as if reality itself forced you to say it.`},{french:`toutefois`,english:`however`,pronunciation:`tutfwa`},{french:`néanmoins`,english:`nevertheless`,pronunciation:`neɑ̃mwɛ̃`,funnyNote:`"Toutefois" and "néanmoins" are near-synonyms in essays; "néanmoins" leans very slightly stronger, but native writers use them interchangeably for variety, not meaning.`},{french:`contrairement à ce que l'on pourrait penser`,english:`contrary to what one might think`,pronunciation:`kɔ̃tʁɛʁmɑ̃ a sə kə lɔ̃ puʁʁɛ pɑ̃se`,example:`Contrairement à ce que l'on pourrait penser, cette loi profite aux petites entreprises.`,exampleTranslation:`Contrary to what one might think, this law benefits small businesses.`}],exercises:[{type:`multiple-choice`,prompt:`Which of these words forces the subjunctive in the clause that follows it?`,answer:`bien que`,options:[`même si`,`bien que`,`toutefois`,`néanmoins`]},{type:`fill-blank`,prompt:`___ tu as raison, je ne suis pas d'accord. (even if)`,answer:`Même si`,hint:`Takes the indicative — unlike "bien que", which needs the subjunctive.`},{type:`translation`,prompt:`Translate using "bien que" and the subjunctive: "Although she is right, he refuses to admit it."`,answer:`Bien qu'elle ait raison, il refuse de l'admettre.`,hint:`"Bien que" + subjunctive of "avoir raison" = "qu'elle ait raison".`},{type:`multiple-choice`,prompt:`In a French dissertation, "certes... mais" is used to:`,answer:`concede a point before refuting it`,options:[`reject an argument outright, without acknowledging it`,`concede a point before refuting it`,`introduce a completely new topic`,`summarize the conclusion`]},{type:`fill-blank`,prompt:`L'argument est solide ; ___, il reste contestable. (however)`,answer:`toutefois`,hint:`A formal-register "however" — common in essays and reports.`},{type:`translation`,prompt:`Translate using "force est de constater que": "One must admit that the plan failed."`,answer:`Force est de constater que le plan a échoué.`,hint:`A fixed formal opener — no "il" before "force". Mind the accent on échoué.`}]},{id:`b2-argumentation-3`,title:`If I May Interrupt...`,subtitle:`Persuade, hedge, and interrupt politely — the last skills before you can debate en français.`,xpReward:40,vocab:[{french:`il est indéniable que`,english:`it's undeniable that (+ indicative)`,pronunciation:`il ɛ tɛ̃denjabl kə`,example:`Il est indéniable que le climat change.`,exampleTranslation:`It's undeniable that the climate is changing.`,funnyNote:`Because it states a certainty, this phrase takes the INDICATIVE — the mirror opposite of the next expression on this list.`},{french:`on ne peut nier que + subjonctif`,english:`one cannot deny that (+ subjunctive)`,pronunciation:`ɔ̃ nə pø nje kə`,example:`On ne peut nier qu'il y ait un problème.`,exampleTranslation:`One cannot deny that there is a problem.`,funnyNote:`Confusingly, this ALSO affirms something true, yet the negated verb "nier" pulls the subjunctive in behind it. Same certainty, opposite mood — welcome to French.`},{french:`on pourrait objecter que`,english:`one could object that`,pronunciation:`ɔ̃ puʁʁɛ ɔbʒɛkte kə`,example:`On pourrait objecter que cette solution est irréaliste.`,exampleTranslation:`One could object that this solution is unrealistic.`,funnyNote:`A power move: raise the opponent's best counterargument yourself, before they do, so you look prepared rather than caught off guard.`},{french:`loin de moi l'idée de`,english:`far be it from me to`,pronunciation:`lwɛ̃ də mwa lide də`,example:`Loin de moi l'idée de vous contredire, mais...`,exampleTranslation:`Far be it from me to contradict you, but...`},{french:`il convient de`,english:`it is fitting / appropriate to`,pronunciation:`il kɔ̃vjɛ̃ də`,example:`Il convient de nuancer cette affirmation.`,exampleTranslation:`It is fitting to qualify this statement.`},{french:`dans une certaine mesure`,english:`to a certain extent`,pronunciation:`dɑ̃ zyn sɛʁtɛn məzyʁ`,example:`Dans une certaine mesure, vous avez raison.`,exampleTranslation:`To a certain extent, you're right.`},{french:`à mon sens`,english:`in my view / to my mind`,pronunciation:`a mɔ̃ sɑ̃s`,funnyNote:`A more literary register than "à mon avis" — reach for it in an essay or a formal debate, not while arguing about the bill at dinner.`},{french:`Permettez-moi de vous interrompre`,english:`Allow me to interrupt you`,pronunciation:`pɛʁmete mwa də vu zɛ̃teʁɔ̃pʁ`,example:`Permettez-moi de vous interrompre une seconde.`,exampleTranslation:`Allow me to interrupt you for a second.`,funnyNote:`French debate culture treats a well-placed interruption as engagement, not rudeness — on TV panels and in oral exams, staying silent can read as having nothing to say. This phrase interrupts politely, manners intact.`}],exercises:[{type:`multiple-choice`,prompt:`Which mood follows "on ne peut nier que"?`,answer:`the subjunctive`,options:[`the indicative`,`the subjunctive`,`the conditional`,`the imperative`]},{type:`fill-blank`,prompt:`___ nuancer cette affirmation. (it is fitting to)`,answer:`Il convient de`,hint:`Impersonal expression + de + infinitive — classic essay register.`},{type:`translation`,prompt:`Translate using "à mon sens": "In my view, this argument is weak."`,answer:`À mon sens, cet argument est faible.`,hint:`A more literary alternative to "à mon avis". Mind the accent on À.`},{type:`multiple-choice`,prompt:`What is the rhetorical purpose of "on pourrait objecter que"?`,answer:`to anticipate and pre-empt the other side's counterargument`,options:[`to state your own strongest argument`,`to anticipate and pre-empt the other side's counterargument`,`to end the debate politely`,`to change the subject`]},{type:`fill-blank`,prompt:`Dans une certaine ___, vous avez raison. (extent)`,answer:`mesure`,hint:`"Mesure" here means "extent" or "degree", not a physical measurement.`},{type:`translation`,prompt:`Translate using "loin de moi l'idée de": "Far be it from me to criticize this law."`,answer:`Loin de moi l'idée de critiquer cette loi.`,hint:`Fixed phrase + de + infinitive.`}]}],isA1:!1,isBeyondA1:!1,isB2:!0},{id:`b2-register`,slug:`b2-register`,title:`Mate, Sir, Your Excellency`,emoji:`🎩`,tagline:`Register & Style`,funnyDescription:`The same sentence can be charming at a bar and a disaster in a cover letter. Learn to hear — and choose — the register.`,color:`#003049`,accentColor:`#33607a`,lessons:[{id:`b2-register-1`,title:`Mate, Sir, Your Excellency`,subtitle:`The same idea in three outfits: jeans, chinos, and a three-piece suit.`,xpReward:40,vocab:[{french:`bouffer / manger / se restaurer`,english:`to eat (familiar / standard / formal)`,pronunciation:`bufe / mɑ̃ʒe / sə ʁɛstɔʁe`,example:`Tu bouffes avec nous ce soir ?`,exampleTranslation:`You eating with us tonight? (very casual)`,funnyNote:`"Bouffer" is what you say to your mates. "Manger" works everywhere. "Se restaurer" shows up on motorway signs and formal invitations ("un lieu pour se restaurer") — say it to a friend and they'll think you're mocking them.`},{french:`la bagnole / la voiture / le véhicule`,english:`the car (familiar / standard / formal)`,pronunciation:`baɲɔl / vwatyʁ / veikyl`,example:`Il a garé sa bagnole devant chez moi.`,exampleTranslation:`He parked his car outside my place.`,funnyNote:`"Bagnole" is garage-and-bar talk. "Voiture" is the neutral word for everything. "Véhicule" is police-report and insurance language: "le véhicule impliqué dans l'accident".`},{french:`bosser / travailler / œuvrer`,english:`to work (familiar / standard / formal)`,pronunciation:`bose / tʁavaje / œvʁe`,example:`Je bosse demain, désolé.`,exampleTranslation:`I'm working tomorrow, sorry.`},{french:`le fric / l'argent / les fonds`,english:`money (familiar / standard / formal)`,pronunciation:`fʁik / aʁʒɑ̃ / fɔ̃`,funnyNote:`"Fric" is what you complain about not having. "Argent" is the everyday word. "Fonds" is what a bank, a charity, or a minister has — "les fonds publics", never "le fric public" in an official text.`},{french:`se casser / partir / s'en aller`,english:`to leave (familiar / standard / formal)`,pronunciation:`sə kase / paʁtiʁ / sɑ̃n ale`,example:`Bon, je me casse, à demain !`,exampleTranslation:`Right, I'm off, see you tomorrow!`,funnyNote:`"Se casser" to a stranger can sound rude. "Partir" is always safe. "S'en aller" has a literary, almost wistful flavour — think novels and song lyrics, not group chats.`},{french:`le mec / l'homme / le monsieur`,english:`the guy / the man / the gentleman (familiar / standard / formal)`,pronunciation:`mɛk / ɔm / məsjø`,example:`C'est qui, ce mec, là-bas ?`,exampleTranslation:`Who's that guy over there?`},{french:`chiant / ennuyeux / fastidieux`,english:`annoying, boring (familiar / standard / formal)`,pronunciation:`ʃjɑ̃ / ɑ̃nɥijø / fastidjø`,example:`Cette réunion était vraiment chiante.`,exampleTranslation:`That meeting was really annoying.`,funnyNote:`"Chiant" is genuinely impolite — fine with friends, a problem in front of your boss. "Fastidieux" belongs in a written complaint, never in a conversation.`},{french:`gueuler / crier / vociférer`,english:`to yell (familiar / standard / formal)`,pronunciation:`gœle / kʁije / vɔsifeʁe`,example:`Il a gueulé après le chauffeur.`,exampleTranslation:`He yelled at the driver.`}],exercises:[{type:`multiple-choice`,prompt:`Which word means 'money' in registre soutenu (formal, official language)?`,answer:`les fonds`,options:[`le fric`,`l'argent`,`les fonds`,`l'oseille`]},{type:`fill-blank`,prompt:`Il a garé son ___ devant le commissariat. (his vehicle — formal register, used in a police report)`,answer:`véhicule`,hint:`The formal word for 'car', used in official documents.`},{type:`translation`,prompt:`Say 'I'm working tomorrow' using the standard, everyday register.`,answer:`Je travaille demain`,hint:`Use travailler, not bosser.`},{type:`multiple-choice`,prompt:`"Tu bosses demain ?" belongs to which register?`,answer:`familier`,options:[`soutenu`,`courant`,`familier`,`administratif`]},{type:`fill-blank`,prompt:`Ce mec est vraiment ___ . (annoying — casual register, not for use with your boss)`,answer:`chiant`,hint:`The informal word for 'annoying'.`},{type:`translation`,prompt:`Say 'He yelled at the driver' using gueuler in the passé composé.`,answer:`Il a gueulé après le chauffeur`,hint:`Il a gueulé + après + le chauffeur.`}]},{id:`b2-register-2`,title:`Chais Pas, On Verra`,subtitle:`What French people actually say is not what your textbook taught you.`,xpReward:40,vocab:[{french:`chais pas`,english:`dunno (contraction of 'je sais pas')`,pronunciation:`ʃɛ pa`,example:`Chais pas, on verra.`,exampleTranslation:`Dunno, we'll see.`,funnyNote:`"Je ne sais pas" loses its "ne" in speech ("je sais pas"), then "je" and "sais" fuse into "chais". Fine to say, never to write in anything formal.`},{french:`t'es / t'as`,english:`you're / you've (contractions of 'tu es' / 'tu as')`,pronunciation:`tɛ / ta`,example:`T'as vu ça ?`,exampleTranslation:`Did you see that?`},{french:`y a`,english:`there is/are (contraction of 'il y a')`,pronunciation:`ja`,example:`Y a du monde ce soir.`,exampleTranslation:`There's a lot of people tonight.`},{french:`on (à la place de nous)`,english:`'we' — on replaces nous in spoken French`,pronunciation:`ɔ̃`,example:`On va au ciné ?`,exampleTranslation:`Are we going to the cinema?`,funnyNote:`"On" virtually always replaces "nous" in speech, but the verb stays third-person singular: "on va", never "on allons". A very common learner trap.`},{french:`du coup`,english:`so, as a result (filler)`,pronunciation:`dy ku`,example:`Du coup, tu viens ou pas ?`,exampleTranslation:`So, are you coming or not?`,funnyNote:`"Du coup" originally meant "as a consequence" but now works as a verbal tic, like English "so..." at the start of a sentence. Overusing it marks you as very casual.`},{french:`genre`,english:`like, sort of (filler)`,pronunciation:`ʒɑ̃ʁ`,example:`Il est arrivé, genre, une heure en retard.`,exampleTranslation:`He showed up, like, an hour late.`,funnyNote:`The exact equivalent of the English filler "like". Fine among friends, an instant red flag in an email to your boss.`},{french:`en mode`,english:`'in ... mode' (trendy filler)`,pronunciation:`ɑ̃ mɔd`,example:`Elle est en mode stressée.`,exampleTranslation:`She's totally stressed out.`},{french:`quoi (en fin de phrase)`,english:`y'know, like (sentence-final filler)`,pronunciation:`kwa`,example:`C'est nul, quoi.`,exampleTranslation:`It's rubbish, y'know.`,funnyNote:`Same word as the question word "what", but at the end of a sentence it does a completely different job: a verbal shrug that adds nothing.`},{french:`ouais`,english:`yeah (casual oui)`,pronunciation:`wɛ`,example:`Ouais, ça marche.`,exampleTranslation:`Yeah, that works.`}],exercises:[{type:`multiple-choice`,prompt:`Which sentence uses 'on' correctly to mean 'we' in spoken French?`,answer:`On va au marché.`,options:[`On va au marché.`,`On allons au marché.`,`On vont au marché.`,`Nous va au marché.`]},{type:`fill-blank`,prompt:`___ pas, demande à Marie. (I dunno — a double contraction of je ne sais pas)`,answer:`Chais`,hint:`je ne sais pas → je sais pas → chais pas.`},{type:`translation`,prompt:`Say 'Did you see that?' using the casual contraction of tu as.`,answer:`T'as vu ça ?`,hint:`Contract tu as to t'as.`},{type:`multiple-choice`,prompt:`In fast spoken French, 'il y a du monde' is usually shortened to:`,answer:`Y a du monde`,options:[`Y a du monde`,`Il a du monde`,`Ya-t-il du monde`,`Il y du monde`]},{type:`fill-blank`,prompt:`Il est arrivé en retard, ___ . (a filler word meaning roughly 'y'know', placed at the end)`,answer:`quoi`,hint:`Sentence-final filler — not the question word here.`},{type:`translation`,prompt:`Say 'So, are you coming?' starting with the casual filler for 'so'.`,answer:`Du coup, tu viens ?`,hint:`Start with du coup. Mind du (du/dû distinction).`}]},{id:`b2-register-3`,title:`We Regret to Inform You`,subtitle:`How to sound like a memo instead of a text message — and read the memos that answer you.`,xpReward:40,vocab:[{french:`Pourriez-vous... ?`,english:`Could you... ? (formal inversion)`,pronunciation:`puʁje vu`,example:`Pourriez-vous me confirmer votre présence ?`,exampleTranslation:`Could you confirm your attendance?`},{french:`il s'agit de`,english:`it is about, this concerns (formal)`,pronunciation:`il saʒi də`,example:`Il s'agit d'un problème de sécurité.`,exampleTranslation:`This is about a security issue.`,funnyNote:`"S'agir de" only ever exists as an impersonal "il" form. In formal writing it replaces the anglicism-flavoured "c'est à propos de", which native readers notice as slightly off.`},{french:`Nous vous prions de bien vouloir...`,english:`We kindly ask you to... (formal-letter opener)`,pronunciation:`nu vu pʁijɔ̃ də bjɛ̃ vulwaʁ`,example:`Nous vous prions de bien vouloir patienter.`,exampleTranslation:`We kindly ask you to please wait.`},{french:`il fut / elle eut / ils allèrent`,english:`he was / she had / they went (passé simple, recognition only)`,pronunciation:`il fy / ɛl y / ilz alɛʁ`,example:`Il fut le premier à comprendre.`,exampleTranslation:`He was the first to understand.`,funnyNote:`The passé simple appears in novels, historical writing, and formal narration — never in speech. Recognise "fut" (être) and "eut" (avoir) as past-tense forms, not typos of "fût" or "eût".`},{french:`qu'il fût / qu'elle eût`,english:`(that) he were / she had (imparfait du subjonctif, reading only)`,pronunciation:`kil fy / kɛl y`,example:`Bien qu'il fût tard, elle continua à lire.`,exampleTranslation:`Although it was late, she kept reading. (modern French would say "bien qu'il soit tard")`,funnyNote:`This mood survives in 19th-century literature after a past-tense main clause. You will never need to produce it — only recognise it as a subjunctive, not a misspelling.`},{french:`néanmoins / toutefois / cependant`,english:`however (formal connectors)`,pronunciation:`neɑ̃mwɛ̃ / tutfwa / səpɑ̃dɑ̃`,example:`Le projet est ambitieux ; néanmoins, le budget reste limité.`,exampleTranslation:`The project is ambitious; however, the budget remains limited.`},{french:`en outre / par ailleurs`,english:`furthermore, moreover (formal connectors)`,pronunciation:`ɑ̃n utʁ / paʁ aljœʁ`,example:`En outre, ce choix réduit les coûts.`,exampleTranslation:`Furthermore, this choice reduces costs.`},{french:`se rendre compte de`,english:`to realise (correct formal usage)`,pronunciation:`sə ʁɑ̃dʁ kɔ̃t`,example:`Je me suis rendu compte de mon erreur.`,exampleTranslation:`I realised my mistake.`,funnyNote:`"Réaliser que" is spreading under English influence, but formal French — and every exam board — still expects "se rendre compte que/de".`},{french:`actuellement`,english:`currently (false friend — not 'actually')`,pronunciation:`aktɥɛlmɑ̃`,example:`Actuellement, je travaille à Lyon.`,exampleTranslation:`I currently work in Lyon.`,funnyNote:`The single most common false-friend trap in formal emails: "actuellement" means "currently", not "actually". "Actually" is "en fait".`}],exercises:[{type:`multiple-choice`,prompt:`Which verb form is passé simple, used only in formal written narration?`,answer:`il fut`,options:[`il a été`,`il fut`,`il est`,`il serait`]},{type:`fill-blank`,prompt:`___, je travaille à Lyon. (Currently — false friend, not "actually")`,answer:`Actuellement`,hint:`Means 'currently', not 'actually'.`},{type:`translation`,prompt:`Translate 'He was the first to understand' using the passé simple of être.`,answer:`Il fut le premier à comprendre`,hint:`Use 'fut', the passé simple of être. Mind the accent on à.`},{type:`multiple-choice`,prompt:`In formal writing, which phrase should replace the anglicism 'c'est à propos de'?`,answer:`Il s'agit de`,options:[`Il s'agit de`,`C'est à propos de`,`Ça parle de`,`C'est en question de`]},{type:`fill-blank`,prompt:`Nous vous ___ de bien vouloir patienter. (We ask you to kindly wait — formal set phrase)`,answer:`prions`,hint:`From 'prier' — the standard formal-letter verb for 'to request'.`},{type:`translation`,prompt:`Translate 'I realised my mistake' using se rendre compte, not the anglicism réaliser.`,answer:`Je me suis rendu compte de mon erreur`,hint:`Passé composé of se rendre compte de + mon erreur.`}]}],isA1:!1,isBeyondA1:!1,isB2:!0},{id:`b2-idiomatic`,slug:`b2-idiomatic`,title:`It's Raining Ropes`,emoji:`🗝️`,tagline:`Idioms & Expressions`,funnyDescription:`Fluent French is full of carrots, rabbits and onions, and none of them are about food.`,color:`#C1121F`,accentColor:`#e0404c`,lessons:[{id:`b2-idiomatic-1`,title:`Rabbits, Salads & Cooked Carrots`,subtitle:`French insults and excuses run on vegetables and farm animals — none of them mean what they say.`,xpReward:40,vocab:[{french:`poser un lapin`,english:`to stand someone up`,pronunciation:`pɔze œ̃ lapɛ̃`,example:`Il m'a posé un lapin, je l'ai attendu une heure au restaurant.`,exampleTranslation:`He stood me up, I waited an hour at the restaurant.`,funnyNote:`Literally "to put down a rabbit" — nobody agrees why a rabbit. Always takes "à quelqu'un": "il m'a posé un lapin", never a bare "il a posé un lapin" with no victim.`},{french:`raconter des salades`,english:`to tell tall tales, spin a story`,pronunciation:`ʁakɔ̃te de salad`,example:`Arrête de raconter des salades, on sait tous que tu n'étais pas au bureau.`,exampleTranslation:`Stop spinning stories, we all know you weren't at the office.`,funnyNote:`Literally "to tell salads". Lighter than "mentir" (to lie) — it suggests exaggerated, tangled stories rather than serious deception. Informal, often said with a smile.`},{french:`les carottes sont cuites`,english:`it's all over, done for`,pronunciation:`le kaʁɔt sɔ̃ kɥit`,example:`Quand le patron a vu les chiffres, on a compris que les carottes étaient cuites.`,exampleTranslation:`When the boss saw the numbers, we understood it was all over.`},{french:`ce ne sont pas tes oignons`,english:`it's none of your business`,pronunciation:`sə nə sɔ̃ pa te zɔɲɔ̃`,example:`Pourquoi tu me poses cette question ? Ce ne sont pas tes oignons.`,exampleTranslation:`Why are you asking me that? It's none of your business.`,funnyNote:`Literally "these are not your onions". Blunt and a little rude — fine between close friends, risky with your boss. The polite version is "cela ne vous regarde pas".`},{french:`avoir un chat dans la gorge`,english:`to have a frog in one's throat`,pronunciation:`avwaʁ œ̃ ʃa dɑ̃ la gɔʁʒ`,example:`Désolée, j'ai un chat dans la gorge ce matin, je vais boire un peu d'eau.`,exampleTranslation:`Sorry, I have a frog in my throat this morning, I'm going to drink some water.`},{french:`quand les poules auront des dents`,english:`when pigs fly, never`,pronunciation:`kɑ̃ le pul ɔʁɔ̃ de dɑ̃`,example:`Il arrêtera de fumer quand les poules auront des dents.`,exampleTranslation:`He'll quit smoking when pigs fly.`,funnyNote:`Literally "when hens have teeth" — since that never happens, the phrase means "never, ever". Always future tense: "auront", not "ont".`},{french:`en faire tout un fromage`,english:`to make a big deal out of nothing`,pronunciation:`ɑ̃ fɛʁ tut œ̃ fʁɔmaʒ`,example:`C'est juste une égratignure, arrête d'en faire tout un fromage.`,exampleTranslation:`It's just a scratch, stop making such a big deal out of it.`,funnyNote:`Literally "to make a whole cheese out of it". Interchangeable with "en faire toute une montagne", but "fromage" is the more colloquial, more French choice.`},{french:`avoir d'autres chats à fouetter`,english:`to have other fish to fry, bigger priorities`,pronunciation:`avwaʁ dotʁ ʃa a fwete`,example:`Je ne peux pas t'aider maintenant, j'ai d'autres chats à fouetter.`,exampleTranslation:`I can't help you right now, I have other things to deal with.`}],exercises:[{type:`multiple-choice`,prompt:`"Poser un lapin à quelqu'un" means to:`,answer:`Stand someone up`,options:[`Stand someone up`,`Give someone a gift`,`Tell a joke`,`Book a table`]},{type:`fill-blank`,prompt:`Il m'a encore ___ un lapin (He stood me up again)`,answer:`posé`,hint:`Past participle of poser`},{type:`translation`,prompt:`Say: It's none of your business. (Use tes oignons)`,answer:`Ce ne sont pas tes oignons`,hint:`Ce ne sont pas + tes oignons`},{type:`fill-blank`,prompt:`J'ai un chat dans la ___ (I have a frog in my throat)`,answer:`gorge`,hint:`Body part: throat`},{type:`multiple-choice`,prompt:`"Les carottes sont cuites" means the situation is:`,answer:`Hopeless, completely over`,options:[`Hopeless, completely over`,`Slowly improving`,`Delicious`,`Still undecided`]},{type:`translation`,prompt:`Say: Stop making such a big deal out of it. (Use fromage)`,answer:`Arrête d'en faire tout un fromage`,hint:`Arrête d'en faire tout un + fromage`}]},{id:`b2-idiomatic-2`,title:`Elbows, Feet & Wandering Heads`,subtitle:`Your body is a French idiom factory: eyes cost money, feet get broken, elbows get squeezed.`,xpReward:40,vocab:[{french:`coûter les yeux de la tête`,english:`to cost an arm and a leg`,pronunciation:`kute le zjø də la tɛt`,example:`Ce sac coûte les yeux de la tête, je ne peux pas me le permettre.`,exampleTranslation:`This bag costs an arm and a leg, I can't afford it.`,funnyNote:`Literally "to cost the eyes of the head". Informal but universally understood. Always "les" yeux (plural, definite) — never "des yeux" or "mes yeux".`},{french:`avoir le bras long`,english:`to have connections, pull strings`,pronunciation:`avwaʁ lə bʁa lɔ̃`,example:`Il a le bras long dans cette entreprise, il connaît tout le monde.`,exampleTranslation:`He has a lot of pull in this company, he knows everyone.`},{french:`casser les pieds (à quelqu'un)`,english:`to annoy, bug someone`,pronunciation:`kase le pje`,example:`Arrête de me casser les pieds avec tes questions !`,exampleTranslation:`Stop bugging me with your questions!`,funnyNote:`Literally "to break someone's feet". Mild and family-friendly — nothing like its vulgar cousin "casser les couilles". Very common between friends and family.`},{french:`mettre les pieds dans le plat`,english:`to put one's foot in it, blurt out something tactless`,pronunciation:`mɛtʁ le pje dɑ̃ lə pla`,example:`Il a mis les pieds dans le plat en demandant son âge devant tout le monde.`,exampleTranslation:`He put his foot in it by asking her age in front of everyone.`,funnyNote:`Literally "to put one's feet in the dish" — not "in one's mouth" as English has it. Describes blurting out an awkward truth out loud, not just embarrassing yourself.`},{french:`avoir la tête dans les nuages`,english:`to have one's head in the clouds, be a daydreamer`,pronunciation:`avwaʁ la tɛt dɑ̃ le nɥaʒ`,example:`Elle a toujours la tête dans les nuages pendant les cours.`,exampleTranslation:`She's always daydreaming during class.`},{french:`se serrer les coudes`,english:`to stick together, support one another`,pronunciation:`sə seʁe le kud`,example:`Dans les moments difficiles, il faut se serrer les coudes.`,exampleTranslation:`In hard times, we need to stick together.`},{french:`avoir un poil dans la main`,english:`to be extremely lazy`,pronunciation:`avwaʁ œ̃ pwal dɑ̃ la mɛ̃`,example:`Il a un poil dans la main, il n'a rien fait depuis des mois.`,exampleTranslation:`He's incredibly lazy, he hasn't done anything in months.`,funnyNote:`Literally "to have a hair growing in one's hand" — the joke is that the hand is so unused to work that a hair had time to grow there. Always a light jab, never a compliment.`},{french:`tenir la jambe à quelqu'un`,english:`to bore someone with endless talk, buttonhole someone`,pronunciation:`təniʁ la ʒɑ̃b a kɛlkœ̃`,example:`Le voisin m'a tenu la jambe pendant une heure hier.`,exampleTranslation:`The neighbour bent my ear for an hour yesterday.`,funnyNote:`Literally "to hold someone's leg" — picture someone physically not letting you walk away. Distinct from "casser les pieds": this one is specifically about trapping someone in conversation.`}],exercises:[{type:`fill-blank`,prompt:`Ne me ___ pas les pieds avec ça (Don't bug me with that)`,answer:`casse`,hint:`Negative imperative, tu-form of casser`},{type:`multiple-choice`,prompt:`"Mettre les pieds dans le plat" means to:`,answer:`Blurt out something tactless`,options:[`Blurt out something tactless`,`Cook an elaborate meal`,`Trip over furniture`,`Refuse to apologise`]},{type:`translation`,prompt:`Say: He has a lot of pull. (Use le bras long)`,answer:`Il a le bras long`,hint:`avoir + le bras long`},{type:`multiple-choice`,prompt:`"Avoir un poil dans la main" describes someone who is:`,answer:`Extremely lazy`,options:[`Extremely lazy`,`Very hardworking`,`Ticklish`,`Nervous`]},{type:`fill-blank`,prompt:`Elle a toujours la tête dans les ___ (Her head is always in the clouds)`,answer:`nuages`,hint:`Clouds`},{type:`translation`,prompt:`Say: We need to stick together. (Use se serrer les coudes)`,answer:`Il faut se serrer les coudes`,hint:`il faut + se serrer les coudes`}]},{id:`b2-idiomatic-3`,title:`Ropes, Apples & Cockroaches`,subtitle:`Weather, moods and mornings — the weirdest images in French describe totally ordinary days.`,xpReward:40,vocab:[{french:`il pleut des cordes`,english:`it's pouring rain`,pronunciation:`il plø de kɔʁd`,example:`Ne sors pas sans parapluie, il pleut des cordes.`,exampleTranslation:`Don't go out without an umbrella, it's pouring rain.`,funnyNote:`Literally "it's raining ropes". Just as common as "il pleut des seaux" (raining buckets) — both describe genuinely heavy rain, not a drizzle.`},{french:`avoir le cafard`,english:`to feel down, have the blues`,pronunciation:`avwaʁ lə kafaʁ`,example:`Depuis la fin de l'été, j'ai un peu le cafard.`,exampleTranslation:`Since the end of summer, I've been feeling a bit down.`,funnyNote:`Literally "to have the cockroach" — a low mood that won't scuttle off. Informal but sincere; used for real, if usually temporary, sadness.`},{french:`tomber dans les pommes`,english:`to faint, pass out`,pronunciation:`tɔ̃be dɑ̃ le pɔm`,example:`Il faisait si chaud qu'elle est tombée dans les pommes.`,exampleTranslation:`It was so hot that she fainted.`,funnyNote:`Literally "to fall into the apples" — the everyday word for fainting, more common in speech than the clinical "s'évanouir". Takes "être": elle est tombée.`},{french:`se faire rouler dans la farine`,english:`to be conned, get duped`,pronunciation:`sə fɛʁ ʁule dɑ̃ la faʁin`,example:`Il s'est fait rouler dans la farine par ce faux vendeur.`,exampleTranslation:`He got conned by that fake salesman.`},{french:`avoir du pain sur la planche`,english:`to have a lot on one's plate, plenty of work to do`,pronunciation:`avwaʁ dy pɛ̃ syʁ la plɑ̃ʃ`,example:`Avec ce nouveau projet, on a du pain sur la planche.`,exampleTranslation:`With this new project, we have a lot of work ahead of us.`},{french:`c'est la fin des haricots`,english:`that's the last straw, it's all over`,pronunciation:`sɛ la fɛ̃ de aʁiko`,example:`Si le train est encore annulé, c'est vraiment la fin des haricots.`,exampleTranslation:`If the train is cancelled again, that really is the last straw.`,funnyNote:`Literally "it's the end of the beans". Note the missing liaison: "haricot" starts with an h aspiré, so it's "les haricots" with no z-sound, never "le-z-aricots".`},{french:`prendre la mouche`,english:`to get offended, take umbrage`,pronunciation:`pʁɑ̃dʁ la muʃ`,example:`Il a pris la mouche quand je lui ai fait une remarque.`,exampleTranslation:`He got offended when I made a remark to him.`},{french:`faire la grasse matinée`,english:`to sleep in`,pronunciation:`fɛʁ la gʁas matine`,example:`Le dimanche, j'aime faire la grasse matinée.`,exampleTranslation:`On Sundays, I like to sleep in.`,funnyNote:`Literally "to make the fat morning" — nothing to do with food, everything to do with sleeping in. Fixed phrase: you "fais" la grasse matinée, you don't "dors" it.`}],exercises:[{type:`translation`,prompt:`Say: That's the last straw! (Use fin des haricots)`,answer:`C'est la fin des haricots`,hint:`C'est la fin des + haricots`},{type:`multiple-choice`,prompt:`"Avoir le cafard" means to feel:`,answer:`Sad, down in the dumps`,options:[`Sad, down in the dumps`,`Extremely energetic`,`Hungry`,`Nervous before an exam`]},{type:`fill-blank`,prompt:`Il pleut des ___, prends ton parapluie (It's pouring rain)`,answer:`cordes`,hint:`Ropes`},{type:`multiple-choice`,prompt:`"Avoir du pain sur la planche" means:`,answer:`To have a lot of work to do`,options:[`To have a lot of work to do`,`To be very hungry`,`To be broke`,`To bake bread at home`]},{type:`translation`,prompt:`Say: She fainted. (Use tomber dans les pommes)`,answer:`Elle est tombée dans les pommes`,hint:`Passé composé with être; watch the agreement`},{type:`fill-blank`,prompt:`Le dimanche, on aime faire la grasse ___ (We like to sleep in on Sundays)`,answer:`matinée`,hint:`Morning (feminine noun)`}]}],isA1:!1,isBeyondA1:!1,isB2:!0}],t=[`emergency`,`food`,`directions`,`numbers`,`greetings`,`shopping`,`accommodation`,`medical`,`smalltalk`,`grammar`];function n(){return e.reduce((e,t)=>e+t.lessons.length,0)}function r(){return e.flatMap(e=>e.lessons.flatMap(t=>t.vocab.map(n=>({...n,unitId:e.id,unitTitle:e.title,lessonId:t.id}))))}export{n as i,e as n,r,t};